            ///<summary>
            ///Initializes the state for bitwise reading operations. Resets `bits` accumulator and `bit` pointer.
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void init_bits()
            {
                bits = 0;
                bit = 8;
            }

            ///<summary>
            ///Gets the value currently stored in `u4` (populated by `try_get_bits`), reinterpreted as type `T`.
            ///</summary>
            ///<typeparam name="T">The type to reinterpret `u4` as.</typeparam>
            ///<returns>The bits value from `u4` cast to type `T`.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public T get_bits<T>() => Unsafe.As<uint, T>(ref u4);

            ///<summary>
            ///Reads a specified number of bits from the buffer, potentially consuming one or more bytes.
            ///Bits are read from the internal `bits` accumulator; if more bits are needed, a byte is read from `buffer`.
            ///</summary>
            ///<typeparam name="T">The type to return the bits as (e.g., int, byte). The value is stored in the lower bits of `T`.</typeparam>
            ///<param name="len_bits">The number of bits to read (must be less than or equal to the bit-width of `T` and typically small, e.g., 1-8).</param>
            ///<returns>The bits read from the buffer, cast to type `T`.</returns>
            public T get_bits<T>(int len_bits)
            {
                uint ret;
                if (bit + len_bits < 9)
                {
                    ret = bits >> bit & 0xFFU >> 8 - len_bits;
                    bit += len_bits;
                }
                else
                {
                    ret = (bits >> bit | (bits = buffer![byte_++]) << 8 - bit) & 0xFFU >> 8 - len_bits;
                    bit = bit + len_bits - 8;
                }

                return Unsafe.As<uint, T>(ref ret);
            }

            ///<summary>
            ///Items of a bit array straight into its list: while the bit stream stands on a byte boundary, whole chunks -
            ///as many groups of 8 items (<c>bitsPerItem</c> bytes each) as one ulong takes - go from the buffer in one
            ///read and one or two word writes. The items before the next boundary and the tail go one by one, as before.
            ///</summary>
            ///<returns>The items received: a multiple of 8, and 0 when the stream is not on a byte boundary.</returns>
            public int get_bits<T>(org.unirail.collections.BitsList<T>.RW dst, int item, int items)
                where T : struct
            {
                if (bit != 8)
                    return 0;
                if (BitConverter.IsLittleEndian) //the list's words are LSB first: its bytes are the wire's - all whole groups in one copy
                {
                    int bl = dst.bitsPerItem, gl = Math.Min(items >> 3, (byte_max - byte_) / bl);
                    if (gl == 0)
                        return 0;
                    buffer.AsSpan(byte_, gl * bl).CopyTo(dst.BytesFor(item, gl << 3));
                    byte_ += gl * bl;
                    return gl << 3;
                }
                int b = dst.bitsPerItem, K = 8 / b, pos = byte_, got = 0;
                for (int g; 0 < (g = Math.Min(Math.Min(K, items - got >> 3), (byte_max - pos) / b)); got += g << 3, pos += g * b)
                    dst.Raw(item + got, g << 3, load(buffer!, pos, g * b));
                byte_ = pos;
                return got;
            }

            ///<summary><see cref="get_bits{T}(org.unirail.collections.BitsList{T}.RW, int, int)"/> of one-bit items: appended,
            ///64 at a time - the list is filled in order, <paramref name="item"/> is its count.</summary>
            public int get_bits(org.unirail.collections.BitList.RW dst, int item, int items)
            {
                if (bit != 8)
                    return 0;
                int pos = byte_, got = 0;
                for (int g; 0 < (g = Math.Min(Math.Min(8, items - got >> 3), byte_max - pos)); got += g << 3, pos += g)
                    dst.Append(load(buffer!, pos, g), g << 3);
                byte_ = pos;
                return got;
            }

            ///<summary>
            ///A chunk of a bit array an abstract pack takes item by item: while the bit stream stands on a byte boundary, up
            ///to <paramref name="items"/> items of <paramref name="bits_per_item"/> bits - as many as one ulong and the buffer
            ///hold, whole bytes - read into <see cref="AdHoc.u8"/> at once, item 0 in the lowest bits. The codec hands them on
            ///shifting it down.
            ///</summary>
            ///<returns>The items read, 0 when the stream is not on a byte boundary or no chunk is there.</returns>
            public int bits8(int items, int bits_per_item)
            {
                if (bit != 8)
                    return 0;
                var n = Math.Min(Math.Min(items, 64 / bits_per_item), (byte_max - byte_ << 3) / bits_per_item);
                n -= n % (8 >> System.Numerics.BitOperations.TrailingZeroCount(bits_per_item)); //whole bytes
                if (n <= 0)
                    return 0;
                var bytes = n * bits_per_item >> 3;
                u8 = load(buffer!, byte_, bytes);
                byte_ += bytes;
                return n;
            }

            ///<summary>Whether the bit stream holds <paramref name="len_bits"/> more bits: the rest of the current byte and the buffer.</summary>
            public bool has_bits(int len_bits) => len_bits <= 8 - bit + (byte_max - byte_ << 3);

            ///<summary>
            ///Attempts to read a specified number of bits from the buffer into `u4`.
            ///If not enough data (bytes) is available in the buffer to satisfy the bit read,
            ///sets up a retry at `this_case`.
            ///</summary>
            ///<param name="len_bits">The number of bits to read.</param>
            ///<param name="this_case">The state to retry at if reading fails due to insufficient underlying bytes.</param>
            ///<returns>True if the bits were read successfully into `u4`; false if a retry is needed.</returns>
            public bool try_get_bits(int len_bits, uint this_case)
            {
                if (bit + len_bits < 9)
                {
                    u4 = bits >> bit & 0xFFU >> 8 - len_bits;
                    bit += len_bits;
                }
                else if (byte_ < byte_max)
                {
                    u4 = (bits >> bit | (bits = buffer![byte_++]) << 8 - bit) & 0xFFU >> 8 - len_bits;
                    bit = bit + len_bits - 8;
                }
                else //not enough data
                {
                    retry_at(this_case);
                    return false;
                }

                return true;
            }
