            ///<returns>True if bytes were read successfully; false if a retry is needed.</returns>
            public bool try_get8(uint next_case) => try_get8(bytes_left, next_case);

            ///<summary>
            ///Tries to read 1 bit for varint length information (0 for 1 byte, 1 for 2 bytes).
            ///Sets `bytes_left` and `bytes_max` according to this length.
            ///</summary>
            ///<param name="bits">Number of bits for length info (should be 1 for this method).</param>
            ///<param name="this_case">The state to retry at if reading bits fails.</param>
            ///<returns>True if length bit was read and `bytes_left` set; false if retry is needed.</returns>
            public bool try_get_varint_bits1(int bits, uint this_case)
            {
                if (!try_get_bits(bits, this_case))
                    return false;
                bytes_left = bytes_max = get_bits<int>() + 1;
                return true;
            }

            ///<summary>
            ///Tries to read a specified number of bits for varint length information.
            ///Sets `bytes_left` and `bytes_max` according to this length.
            ///</summary>
            ///<param name="bits">Number of bits for length info.</param>
            ///<param name="this_case">The state to retry at if reading bits fails.</param>
            ///<returns>True if length bits were read and `bytes_left` set; false if retry is needed.</returns>
            public bool try_get_varint_bits(int bits, uint this_case)
            {
                if (!try_get_bits(bits, this_case))
                    return false;
                bytes_left = bytes_max = get_bits<int>();
                return true;
            }

            ///<summary>
            ///Attempts to read a varint-encoded unsigned long from the buffer into `u8`.
            ///If not enough data, sets mode to `VARINT` and state to `next_case` for retry.
            ///</summary>
            ///<param name="next_case">The state to retry at if reading fails.</param>
            ///<returns>True if the varint was read successfully; false if a retry is needed.</returns>
            public bool try_get_varint(uint next_case)
            {
                u8 = 0;
                bytes_left = 0;

                if (varint())
                    return true;

                slot!.state = next_case;
                mode = VARINT;
                return false;
            }

            ///<summary>
            ///Reads a varint-encoded unsigned long from the `buffer` and accumulates it into `u8`.
            ///Updates `byte_` (buffer position) and `bytes_left` (varint shift accumulator).
            ///</summary>
            ///<returns>True if a complete varint value has been read; false if more bytes are needed from the buffer.</returns>
            internal bool varint()
            {
                for (ulong b; byte_ < byte_max; u8 |= (b & 0x7FUL) << bytes_left, bytes_left += 7)
                    if ((b = buffer![byte_++]) < 0x80)
                    {
                        u8 |= b << bytes_left;
                        return true;
                    }

                return false;
            }

            ///<summary>
            ///Decodes a ZigZag-encoded unsigned long back to a signed long.
            ///ZigZag encoding maps signed integers to unsigned integers so that numbers with a small absolute value
            ///(i.e., close to zero, positive or negative) have a small varint encoded value.
            ///</summary>
            ///<param name="src">The ZigZag-encoded unsigned long value.</param>
            ///<returns>The decoded signed long value.</returns>
            public static long zig_zag(ulong src) => -(long)(src & 1) ^ (long)(src >> 1);
#endregion
#region dims
            int[] dims = Array.Empty<int>(); //temporary buffer for the receiving string and more

            ///<summary>
            ///Initializes or resizes the internal `dims` array used for storing dimensions of multi-dimensional data.
            ///Also resets `u8` to 1 (often used as a running product of dimensions).
            ///</summary>
            ///<param name="size">The required size of the dimensions array.</param>
            public void init_dims(int size)
            {
                u8 = 1;
                if (size <= dims.Length)
                    return;
                ArrayPool<int>.Shared.Return(dims);
                dims = ArrayPool<int>.Shared.Rent(size);
            }

            ///<summary>
            ///Gets a dimension value from the internal `dims` array at the specified index.
            ///</summary>
            ///<param name="index">The index of the dimension to retrieve.</param>
            ///<returns>The dimension value stored at `dims[index]`.</returns>
            public int dim(int index) => dims[index];

            ///<summary>
            ///Reads a 4-byte integer from the buffer, validates it against `max`, stores it in `dims[index]`,
            ///and multiplies it into `u8` (which typically accumulates the total number of elements).
            ///Reports an overflow error if `dim > max`.
            ///</summary>
            ///<param name="max">The maximum allowed value for this dimension.</param>
            ///<param name="index">The index in the `dims` array where this dimension should be stored.</param>
            public void dim(int max, int index)
            {
                var dim = get4<int>();
                if (max < dim)
                    error_handler.error(this, null, OnError.OVERFLOW, new ArgumentOutOfRangeException("In dim(int max, int index){} max < dim : " + max + " < " + dim));

                u8 *= (ulong)dim;
                dims[index] = dim;
            }

            ///<summary>
            ///Reads a 4-byte integer from the buffer representing a length, and validates it against `max`.
            ///Reports an overflow error if `len > max`. If an overflow occurs, `u8` (often total elements) is set to 0.
            ///</summary>
            ///<param name="max">The maximum allowed value for this length.</param>
            ///<returns>The read length if it's within the `max` limit; otherwise, 0 if an overflow occurred.</returns>
            public long length(long max)
            {
                var len = get4<int>();
                if (len <= max)
                    return len;

                error_handler.error(this, null, OnError.OVERFLOW, new ArgumentOutOfRangeException("In length(long max){} max < len : " + max + " < " + len));
                u8 = 0;
                return 0;
            }
#endregion
#region string
            ///<summary>
            ///Gets the string value currently stored in the `str` field and then clears `str` to null.
            ///Assumes `str` was populated by a previous string deserialization operation.
            ///</summary>
            ///<returns>The string value from the `str` field, or null if `str` was already null.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public string? get_string()
            {
                var ret = str;
                str = null;
                return ret;
            }

            ///<summary>
            ///Attempts to read a varint-encoded string from the buffer. The string consists of a varint-encoded length
            ///followed by varint-encoded characters.
            ///If not enough data, sets mode to `STR` and state to `get_string_case` for retry.
            ///</summary>
            ///<param name="max_chars">The maximum number of characters allowed for the string. An overflow error is reported if the decoded length exceeds this.</param>
            ///<param name="get_string_case">The state to retry at if reading fails.</param>
            ///<returns>True if the string was read successfully and stored in `str`; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool try_get_string(uint max_chars, int get_string_case)
            {
                bit = ~get_string_case; //see the string-leaf park discriminator: for a PLAIN field park slot.state == get_string_case
                //while bit == ~get_string_case — never equal; only a chain leaf's flip makes slot.state == (uint)bit
                u4 = max_chars;
                u8_ = ulong.MaxValue; //indicate state before string length received
                u8 = 0;               //varint receiving string char holde
                bytes_left = 0;       //varint pointer

                if (varint() && //getting string length into u8
                    check_length_and_getting_string())
                    return true;

                slot!.state = (uint)get_string_case;
                mode = STR; //lack of received bytes, switch to reading lines internally
                return false;
            }

            internal char[]? chs;

            ///<summary>
            ///Checks if the decoded string length (`u8`) is within the `u4` (max_chars) limit.
            ///Allocates or reuses `chs` character buffer, resets the split-char state and proceeds to read
            ///characters via <see cref="getting_chars"/>.
            ///</summary>
            ///<returns>True if length check passes and <see cref="getting_chars"/> returns true; false otherwise (e.g., overflow or incomplete character read).</returns>
            internal bool check_length_and_getting_string()
            {
                if (u4 < u8)
                { //Above the field's STR_LEN_MAX. The wire says how much to allocate, so trusting it is the
                  //denial of service the ceiling exists to prevent — fatal before the allocation: the catch in
                  //Write() reports it and aborts the link.
                    error_handler.error(this, null, OnError.OVERFLOW, new ArgumentOutOfRangeException("In check_length_and_getting_string(){} u4 < u8 : " + u4 + " < " + u8));
                    throw new InvalidOperationException("Declared string length " + u8 + " exceeds the maximum " + u4 + " this field accepts");
                }
                if (chs == null)
                    chs = ArrayPool<char>.Shared.Rent((int)u8);
                else if (chs.Length < (int)u8)
                {
                    ArrayPool<char>.Shared.Return(chs);
                    chs = ArrayPool<char>.Shared.Rent((int)u8);
                }

                u8_ = u8;       //store string length into u8_
                u4 = 0;         //index receiving char
                u8 = 0;         //split-char value holder starts empty (u8 held the length until here)
                bytes_left = 0; //split-char shift

                return getting_chars((int)u8_);
            }

            ///<summary>
            ///Reads VarInt-encoded characters into <see cref="chs"/> — the shared engine of BOTH string wires:
            ///<list type="bullet">
            ///<item><paramref name="target"/> = the declared character count — the prefixed
            ///<see cref="try_get_string(uint, int)"/> wire: completes (builds <see cref="str"/>, returns
            ///<c>true</c>) once the count is reached;</item>
            ///<item><paramref name="target"/> = <see cref="int.MaxValue"/> — the prefix-less
            ///<see cref="try_get_str"/> wire: no count exists, the window is the only bound, <see cref="chs"/>
            ///capacity is reserved ONCE per window (<see cref="grow_chs"/> — a no-op on the prefixed wire, whose
            ///<c>chs</c> is pre-rented to the count) and the method ALWAYS parks: the string ends WITH the
            ///enclosing stream, finalized by the framer's <c>[0]</c>-terminator branch (<see cref="Chunked"/>).</item>
            ///</list>
            ///A character split by a window boundary rides <c>u8</c> (value bits) / <c>bytes_left</c> (shift):
            ///read back at entry, committed on park — the method resumes itself, callers just re-invoke it.
            ///A fresh string transfer must zero both before the first call.
            ///<para>
            ///Hot path: 8 bytes per absolute long read via <see cref="Unsafe.ReadUnaligned{T}(ref byte)"/>.
            ///If all 8 bytes are ASCII (mask <c>0x8080808080808080</c>) and there's no partial char in
            ///flight, unpack directly into <c>chs</c> with no per-byte branches.
            ///Mixed path: extract bytes from the loaded long, decode varints in registers — no second
            ///pass over the buffer. Buffer state (<c>byte_</c>, <c>byte_max</c>) is cached into stack locals
            ///for the duration of the call; <c>byte_</c> is committed back exactly once on exit.
            ///</para>
            ///</summary>
            ///<param name="target">Char index to stop at: the declared count (prefixed wire) or
            ///<see cref="int.MaxValue"/> (prefix-less wire).</param>
            ///<returns>True — <paramref name="target"/> reached, <see cref="str"/> is built; false — window
            ///exhausted, the split-char state is committed to <c>u8</c>/<c>bytes_left</c> for resume.</returns>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            internal bool getting_chars(int target)
            {
                var buf = buffer!;
                var c = chs!;
                var pos = byte_;
                var limit = byte_max;
                var u4_ = u4;

                //Resume a character split by the previous window (0/0 when none is in flight).
                var val = u8;
                var shift = bytes_left;

                //ONE capacity reservation per window — no growth inside the hot loops. A varint char
                //consumes at least one byte, so this window adds at most (limit - pos) chars; +8 slack
                //keeps every in-loop capacity test provably true. The clamp by target makes this a
                //no-op on the prefixed wire (chs is pre-rented to the declared count), and on the
                //prefix-less wire every window byte belongs to the string — the framer clamps windows
                //to stream data — so the reservation is exact, not an overshoot.
                {
                    var bytes = limit - pos;
                    if (0 < bytes)
                    {
                        var cap = Math.Min((long)u4_ + bytes + 8, target);
                        if (c.Length < cap)
                            c = grow_chs((int)cap);
                    }
                }

                ref var bufRef = ref MemoryMarshal.GetArrayDataReference(buf);
                ref var chsRef = ref MemoryMarshal.GetArrayDataReference(c);
                var charLen = c.Length;

                //=== Main loop: 8 bytes per iteration ===
                while (u4_ < target && pos <= limit - 8)
                {
                    var packed = Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref bufRef, pos));

                    //Fast path: shift==0 + all 8 bytes ASCII + room for 8 chars
                    //(u4_ + 8 <= charLen is always true after the reservation — kept because the
                    //dominating test keeps every blind store provably in bounds).
                    if (shift == 0 && u4_ + 8 <= target && u4_ + 8 <= (uint)charLen &&
                        (packed & 0x8080808080808080UL) == 0)
                    {
                        Unsafe.Add(ref chsRef, (nint)u4_) = (char)(packed & 0xFF);
                        Unsafe.Add(ref chsRef, (nint)u4_ + 1) = (char)((packed >> 8) & 0xFF);
                        Unsafe.Add(ref chsRef, (nint)u4_ + 2) = (char)((packed >> 16) & 0xFF);
                        Unsafe.Add(ref chsRef, (nint)u4_ + 3) = (char)((packed >> 24) & 0xFF);
                        Unsafe.Add(ref chsRef, (nint)u4_ + 4) = (char)((packed >> 32) & 0xFF);
                        Unsafe.Add(ref chsRef, (nint)u4_ + 5) = (char)((packed >> 40) & 0xFF);
                        Unsafe.Add(ref chsRef, (nint)u4_ + 6) = (char)((packed >> 48) & 0xFF);
                        Unsafe.Add(ref chsRef, (nint)u4_ + 7) = (char)((packed >> 56) & 0xFF);
                        u4_ += 8;
                        pos += 8;
                        continue;
                    }

                    //Mixed path: extract bytes from the already-loaded long.
                    var rem = packed;
                    var consumed = 0;
                    while (consumed < 8 && u4_ < target && u4_ < (uint)charLen)
                    {
                        var b = (sbyte)rem;
                        rem >>= 8;
                        consumed++;

                        if (b >= 0)
                        {
                            Unsafe.Add(ref chsRef, (nint)u4_) = (char)(val | ((ulong)b << shift));
                            u4_++;
                            val = 0;
                            shift = 0;
                        }
                        else
                        {
                            val |= ((ulong)(b & 0x7F)) << shift;
                            shift += 7;
                        }
                    }

                    pos += consumed;
                }

                //=== Tail: fewer than 8 bytes remain ===
                while (u4_ < target && pos < limit)
                {
                    var b = (sbyte)Unsafe.Add(ref bufRef, pos++);
                    if (b < 0)
                    {
                        val |= ((ulong)(b & 0x7F)) << shift;
                        shift += 7;
                    }
                    else
                    {
                        Unsafe.Add(ref chsRef, (nint)u4_) = (char)(val | ((ulong)b << shift));
                        u4_++;
                        val = 0;
                        shift = 0;
                    }
                }

                if (u4_ < target)
                {
                    //Window exhausted (always, on the prefix-less wire) — commit the split-char state for resume.
                    byte_ = pos;
                    u4 = u4_;
                    u8 = val;
                    bytes_left = shift;
                    return false;
                }

                //The declared count is reached — only the prefixed wire gets here.
                byte_ = pos;
                u4 = u4_;
                str = new string(c.AsSpan(0, (int)u4_));
                return true;
            }

            ///<summary>
            ///Grows <see cref="chs"/> to hold at least <paramref name="min"/> chars, preserving the accumulated
            ///content — a prefix-less string learns its size only at the stream terminator, so the buffer grows
            ///as windows arrive (one capacity reservation per window — see <see cref="getting_chars"/> /
            ///<see cref="getting_string_utf"/>). Doubling keeps the copy traffic amortized O(n); <paramref name="min"/>
            ///wins when doubling is not enough.
            ///</summary>
            internal char[] grow_chs(int min)
            {
                var old = chs!;
                var c = ArrayPool<char>.Shared.Rent((int)Math.Min(Math.Max((long)old.Length << 1, min), int.MaxValue - 8));
                Array.Copy(old, c, old.Length);
                ArrayPool<char>.Shared.Return(old);
                return chs = c;
            }

            ///<summary>
            ///Reads a PREFIX-LESS string: varint-encoded characters with no character count — the wire
            ///<see cref="Transmitter.put_str"/> produces. The receiver cannot know where such a string ends, so
            ///this can never complete on its own: it drains the window, parks, and is completed by the framer
            ///that sees the enclosing stream's terminator (<see cref="Chunked"/>'s <c>[0]</c> branch). Meaningful
            ///only under such a framer — the canonical user is the <see cref="StringStream"/> chain leaf; a plain
            ///field should use <see cref="try_get_string(uint, int)"/> instead.
            ///</summary>
            ///<param name="max_chars">Ceiling on the characters the string may hold — advisory, checked at the stream terminator.</param>
            ///<param name="get_string_case">The state to retry at.</param>
            ///<returns>Always <c>false</c> — reception completes only at the enclosing stream's terminator.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool try_get_str(uint max_chars, int get_string_case)
            {
                bit = ~get_string_case; //string-leaf park discriminator seed — see try_get_string
                u8_ = max_chars;        //the character ceiling rides u8_ (no declared count on this wire)
                u4 = 0;                 //char index
                u8 = 0;                 //split-char value holder
                bytes_left = 0;         //split-char shift
                chs ??= ArrayPool<char>.Shared.Rent((int)Math.Min(max_chars, 256));

                getting_chars(int.MaxValue); //no count — the window is the only bound

                slot!.state = (uint)get_string_case;
                mode = STR_RAW;
                return false;
            }

            ///<summary>
            ///Reads a PREFIX-LESS string transmitted as raw <b>UTF-8</b> bytes — the wire format
            ///<see cref="Transmitter.put_utf"/> produces: no character count, just the bytes. The receiver
            ///cannot know where such a string ends, so this can never complete on its own: it drains the
            ///window, parks, and is completed by the framer that sees the enclosing stream's terminator
            ///(<see cref="Chunked"/>'s <c>[0]</c> branch). Meaningful only under such a framer — the canonical
            ///user is the <see cref="UTFStream"/> chain leaf.
            ///<para>
            ///The decoder is strict: overlong forms, encoded surrogates (CESU-8 / WTF-8), code points past
            ///U+10FFFF and stray/malformed continuation bytes are reported through <c>error_handler</c> as
            ///<see cref="OnError.BYTES_DISTORTION"/> and substituted with U+FFFD (one replacement char per
            ///offending byte, the byte is consumed), so decoding stays deterministic — the receiver degrades
            ///and reports, it never throws for wire content.
            ///</para>
            ///</summary>
            ///<param name="max_chars">Ceiling on the characters the string may hold — advisory, checked at the stream terminator.</param>
            ///<param name="get_string_case">The state to retry at.</param>
            ///<returns>Always <c>false</c> — reception completes only at the enclosing stream's terminator.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool try_get_utf(uint max_chars, int get_string_case)
            {
                bit = ~get_string_case; //string-leaf park discriminator seed — see try_get_string
                u8_ = max_chars;        //the character ceiling rides u8_ (no declared count on this wire)
                u4 = 0;                 //char index
                u8 = 0;                 //code-point accumulator starts empty
                bytes_left = 0;         //0 ⇒ the decoder sits at a sequence boundary
                chs ??= ArrayPool<char>.Shared.Rent((int)Math.Min(max_chars, 256));

                getting_string_utf(); //drains the window; a prefix-less string cannot self-terminate

                slot!.state = (uint)get_string_case;
                mode = STR_UTF8;
                return false;
            }

            ///<summary>
            ///Decodes PREFIX-LESS UTF-8 bytes into <c>chs</c> until the buffer window is exhausted — the wire
            ///<see cref="Transmitter.put_utf"/> produces: no character count, just the bytes.
            ///<para>
            ///Register roles while in this phase: <c>u4</c> = current char index, <c>u8</c> = partially
            ///assembled code point, <c>bytes_left</c> = packed decoder state
            ///<c>need | lo &lt;&lt; 8 | hi &lt;&lt; 16</c> where <c>need</c> is the number of continuation bytes
            ///still expected (0 ⇒ sequence boundary) and <c>lo..hi</c> is the inclusive range the NEXT byte must
            ///fall in — narrowed by the lead byte per the Unicode well-formedness table (15.0 §3.9, table 3-7),
            ///which rejects overlong forms, encoded surrogates and code points past U+10FFFF at the earliest byte.
            ///<see cref="chs"/> capacity is reserved ONCE per window (<see cref="grow_chs"/>): UTF-8 never yields
            ///more chars than bytes (+1 when a sequence split by the previous window completes here; +8 slack
            ///keeps every in-loop capacity gate provably true), and every window byte belongs to the string —
            ///the framer clamps windows to stream data — so the reservation is exact, not an overshoot.
            ///</para>
            ///<para>
            ///Bulk paths: on ASCII, UTF-8 is the identity, and <c>chs</c> is the FINAL char array — so the widened
            ///vectors land straight in it, with no staging hop (32 chars per <see cref="Vector256"/> iteration,
            ///16 per <see cref="Vector128"/>, 8 per unaligned <c>ulong</c> load). Every bulk path is gated on the
            ///reserved capacity, keeping every blind store in bounds. Scalar tail runs the validating DFA one
            ///byte at a time.
            ///</para>
            ///<para>
            ///On window exhaustion the decoder state is committed back to <c>u4</c> / <c>u8</c> /
            ///<c>bytes_left</c> — a sequence split across fills resumes naturally, no dispatcher-side
            ///completion step is needed. The string is finalized by the enclosing framer's
            ///<c>[0]</c>-terminator branch (<see cref="Chunked"/>), never here.
            ///</para>
            ///</summary>
            ///<returns>Always <c>false</c>: a prefix-less string cannot self-terminate — it ends WITH the
            ///enclosing stream, and only the framer that sees the terminator completes it.</returns>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            internal bool getting_string_utf()
            {
                var buf = buffer!;
                var c = chs!;
                var pos = byte_;
                var limit = byte_max;
                var u4_ = (int)u4;

                //Unpack the decoder state committed by the previous fill (0 ⇒ boundary, nothing in flight).
                var cp = (int)u8;
                var st = bytes_left;
                var need = st & 0xFF;
                var lo = st >> 8 & 0xFF;
                var hi = st >> 16 & 0xFF;

                //ONE capacity reservation per window — no growth inside the hot loops (see the XML doc).
                {
                    var bytes = limit - pos;
                    if (0 < bytes)
                    {
                        var cap = Math.Min((long)u4_ + bytes + 8, int.MaxValue - 8);
                        if (c.Length < cap)
                            c = grow_chs((int)cap);
                    }
                }

                ref var bufRef = ref MemoryMarshal.GetArrayDataReference(buf);
                ref var chsU = ref Unsafe.As<char, ushort>(ref MemoryMarshal.GetArrayDataReference(c));
                var charLen = c.Length;

                var skip = 0;

                while (pos < limit)
                {
                    //A run cannot start mid-sequence (need != 0) nor on a continuation byte, so one compare
                    //gates all the bulk blocks. The capacity gates below are always true after the reservation —
                    //kept because they keep every blind store provably in bounds.
                    if (need == 0 && Unsafe.Add(ref bufRef, pos) < 0x80)
                    {
                        if (0 < skip)
                            skip--;
                        else if (Vector256.IsHardwareAccelerated && 32 <= limit - pos && u4_ + 32 <= charLen)
                        {
                            var v = Vector256.LoadUnsafe(ref bufRef, (uint)pos);
                            var mask = Vector256.ExtractMostSignificantBits(v); //one bit per non-ASCII byte

                            //Room for 32 chars is guaranteed by the count gate, so widening the whole vector
                            //is in bounds even when only the leading `run` characters are meaningful.
                            var (v_lo, v_hi) = Vector256.Widen(v);
                            v_lo.StoreUnsafe(ref chsU, (uint)u4_);
                            v_hi.StoreUnsafe(ref chsU, (uint)(u4_ + 16));

                            if (mask == 0)
                            {
                                pos += 32;
                                u4_ += 32;
                                continue;
                            }

                            var run = BitOperations.TrailingZeroCount(mask);
                            pos += run; //>= 1: byte 0 was ASCII
                            u4_ += run;
                            if (run < 8)
                                skip = VARINT_BACKOFF;
                        }
                        else if (16 <= limit - pos && u4_ + 16 <= charLen)
                        {
                            var v = Vector128.LoadUnsafe(ref bufRef, (uint)pos);
                            var mask = Vector128.ExtractMostSignificantBits(v);

                            var (v_lo, v_hi) = Vector128.Widen(v);
                            v_lo.StoreUnsafe(ref chsU, (uint)u4_);
                            v_hi.StoreUnsafe(ref chsU, (uint)(u4_ + 8));

                            if (mask == 0)
                            {
                                pos += 16;
                                u4_ += 16;
                                continue;
                            }

                            var run = BitOperations.TrailingZeroCount(mask);
                            pos += run;
                            u4_ += run;
                            if (run < 8)
                                skip = VARINT_BACKOFF;
                        }
                        else if (8 <= limit - pos && u4_ + 8 <= charLen)
                        {
                            var packed = Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref bufRef, pos));
                            var mask = packed & 0x8080808080808080UL;

                            //Blind-store all 8 (room guaranteed by the count gate), advance by the ASCII run.
                            Unsafe.Add(ref chsU, (nint)u4_) = (ushort)(packed & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 1) = (ushort)(packed >> 8 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 2) = (ushort)(packed >> 16 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 3) = (ushort)(packed >> 24 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 4) = (ushort)(packed >> 32 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 5) = (ushort)(packed >> 40 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 6) = (ushort)(packed >> 48 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 7) = (ushort)(packed >> 56 & 0xFF);

                            if (mask == 0)
                            {
                                pos += 8;
                                u4_ += 8;
                                continue;
                            }

                            var run = BitOperations.TrailingZeroCount(mask) >> 3;
                            pos += run; //>= 1: byte 0 was ASCII
                            u4_ += run;
                        }
                    }

                    //Scalar: ONE byte through the validating DFA.
                    int b = Unsafe.Add(ref bufRef, pos++);

                    if (need == 0) //lead byte
                    {
                        if (b < 0x80)
                        {
                            Unsafe.Add(ref chsU, (nint)u4_++) = (ushort)b;
                            continue;
                        }

                        //0x80..0xBF is a continuation with no lead; 0xC0/0xC1 could only encode an overlong
                        //ASCII byte; 0xF5..0xFF could only lead a code point past U+10FFFF.
                        if (b < 0xC2 || 0xF4 < b)
                        {
                            error_handler.error(this, null, OnError.BYTES_DISTORTION, new InvalidDataException($"Malformed UTF-8: unexpected byte 0x{b:X2}."));
                            Unsafe.Add(ref chsU, (nint)u4_++) = 0xFFFD;
                            continue;
                        }

                        if (b < 0xE0)
                        {
                            cp = b & 0x1F;
                            need = 1;
                            lo = 0x80;
                            hi = 0xBF;
                        }
                        else if (b < 0xF0)
                        {
                            cp = b & 0x0F;
                            need = 2;
                            //E0 followed by 80..9F would be an overlong 2-byte form; ED followed by A0..BF would
                            //be an encoded surrogate. Bounding the FIRST continuation rejects both at the earliest byte.
                            lo = b == 0xE0 ? 0xA0 : 0x80;
                            hi = b == 0xED ? 0x9F : 0xBF;
                        }
                        else
                        {
                            cp = b & 0x07;
                            need = 3;
                            lo = b == 0xF0 ? 0x90 : //below that is an overlong 3-byte form
                                     0x80;
                            hi = b == 0xF4 ? 0x8F : //above that is past U+10FFFF
                                     0xBF;
                        }

                        continue;
                    }

                    if (b < lo || hi < b) //not a continuation, or out of the lead's range
                    {
                        error_handler.error(this, null, OnError.BYTES_DISTORTION, new InvalidDataException($"Malformed UTF-8: unexpected byte 0x{b:X2}."));
                        Unsafe.Add(ref chsU, (nint)u4_++) = 0xFFFD;
                        need = 0;
                        continue;
                    }

                    cp = cp << 6 | b & 0x3F;
                    lo = 0x80; //only the FIRST continuation is ever narrowed
                    hi = 0xBF;
                    if (0 < --need)
                        continue;

                    //Complete, and necessarily well-formed: the ranges above already excluded every overlong
                    //form, every encoded surrogate and everything past U+10FFFF.
                    if (cp < 0x1_0000)
                        Unsafe.Add(ref chsU, (nint)u4_++) = (ushort)cp;
                    else //astral — one code point, two UTF-16 chars
                    {
                        var u = cp - 0x1_0000;
                        Unsafe.Add(ref chsU, (nint)u4_++) = (ushort)(0xD800 | u >> 10);
                        Unsafe.Add(ref chsU, (nint)u4_++) = (ushort)(0xDC00 | u & 0x3FF);
                    }
                }

                //Window exhausted — commit the decoder state; the enclosing framer decides when the string is over.
                byte_ = pos;
                u4 = (uint)u4_;
                u8 = (uint)cp;
                bytes_left = need | lo << 8 | hi << 16;
                return false;
            }

            ///<summary>
            ///Stages the character ceiling for a transform-chain string reception and hands back the matching
            ///stateless string LEAF, ready to be embedded with <c>datatype(chain_id, leaf, next_case)</c>.
            ///The ceiling rides the <see cref="bits"/> register — otherwise idle for the whole span of a string
            ///transfer — which is what lets the leaf itself stay a shared, stateless singleton. Once the chain
            ///completes, the decoded string is in <see cref="str"/>: collect it with <see cref="get_string"/>.
            ///</summary>
            ///<param name="max_chars">Ceiling on the characters the string may hold — the field's <c>[D(+N)]</c>.</param>
            ///<param name="utf">Leaf codec: <c>true</c> — raw UTF-8 (<see cref="try_get_utf"/> wire, the
            ///directional-string case), <c>false</c> — varint characters (<see cref="try_get_str"/> wire, the
            ///plain <c>[Zstd] string</c> case). Both are PREFIX-LESS: the string ends WITH the stream,
            ///finalized by the framer's <c>[0]</c>-terminator branch.</param>
            ///<param name="get_string_case">The field's retry case — the SAME value the pack passes to
            ///<c>datatype(chain_id, leaf, get_string_case)</c>. Seeded as <c>bit = ~get_string_case</c>: unique to
            ///this field within the pack's switch, so the leaf's park state can never collide with any other
            ///<c>slot.state</c> in flight, and every string transfer re-seeds <c>bit</c> so it is never stale.</param>
            ///<returns>The shared leaf singleton to pass into the chain.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public BytesDst try_get_string(uint max_chars, bool utf, int get_string_case)
            {
                bits = max_chars;
                bit = ~get_string_case; //discriminator seed: slot.state == (uint)bit only after the leaf's FIRST park flips it
                return utf ? UTFStream.ONE : StringStream.ONE;
            }
#endregion

            public override string ToString()
            {
                if (slot == null)
                    return "";

                var s = slot;
                while (s.prev != null)
                    s = s.prev;
                var str = "";
                var offset = "";
                for (; s != slot; s = s.next, offset += "\t")
                    str += $"{offset}{s.dst.GetType()}\t{s.state}\n";

                str += $"{offset}{(slot.dst == null! ? "null" : slot.dst.GetType())}\t{s.state}\n";

                return str;
            }

            ///<summary>
            ///Chunked-stream <b>consumer</b> — the receive half of a streamed packet. Wire form
            ///<c>[id][len][data]…[len][data][0x0000]</c>: a 2-byte little-endian length prefix per chunk
            ///(payload ≤ 65535 bytes), a <c>0x0000</c> length marking end-of-stream. Dispatched by
            ///<see cref="Receiver.__id"/> exactly like a normal pack; the de-framed payload bytes are drained into a
            ///pluggable inner <see cref="Receiver.BytesDst"/> dst. Resumable across socket fills via the standard
            ///<c>false</c> = park / <c>true</c> = complete contract — all chunk state is per-instance, and the
            ///dst is a pure-byte consumer (reads only buffer/byte_/byte_max — never the slot).
            ///<para><b>Scenario-A semantics:</b> the dst is a flat byte consumer; the <c>0x0000</c> terminator
            ///is the sole end-authority — a codec stage never self-completes, so the dst's own return value is
            ///ignored. Chunked completion reaches the application through the receiver's normal <c>OnReceived</c> dispatch.</para>
            ///<para><b>tunnel_id</b> comes out of the id field as far as it reaches there, and off the wire for the
            ///rest: the receiver consumes <see cref="Receiver.id_bytes"/> bytes before dispatch, so on a carrier whose
            ///id field is wider than the pack id those trailing bytes already hold the discriminator, while on a
            ///carrier as narrow as the pack id none of it is captured and all of it is still on the wire. The arming
            ///states where the pack id ends, and only that number tells the two apart.</para>
            ///</summary>
            public class Chunked : BytesDst
            {
                protected BytesDst dst = null!;      //inner stage — pure-byte (cipher/decompressor/leaf) or a structured endpoint
                protected BytesDst datatype = null!; //the chained structured pack, or null for a raw stream

                int fullId;  //the FULL id as delivered to _OnReceiving: low pureIdBytes bytes = pack id, the rest is the captured front of [tunnel_id][body]
                int _rem;    //bytes left in the current chunk's payload; doubles as the little-endian length accumulator while _state == 0
                int _lenGot; //length-prefix bytes accumulated so far (0..2) — straddle-safe across fills
                int _state;  //PRIVATE state machine — never touches the network slot, so this stage composes when nested

                public int tunnel_id; //discriminator assembled by the prelude; valid from the first __put_bytes on
                int tunnelIdBytes;    //discriminator width: 0 = plain stream / one-to-one; 1..4 = many-to-one
                int pureIdBytes;      //width of the pack id inside fullId; the rest of fullId is captured wire
                int _tidGot;          //discriminator bytes assembled so far — survives a park
                int _overGot;         //bytes already taken out of fullId for the discriminator
                bool _tunnelDone;     //on_tunnel_id fired exactly once per arming

                public int __id => datatype != null ? datatype.__id : dst.__id; //raw Stream (no datatype): fall back to the endpoint id

                ///<summary>(Re)configure with a chained STRUCTURED <paramref name="datatype"/>: the de-framed body is
                ///deserialized into <paramref name="datatype"/>. The inner <paramref name="dst"/> is the pure-byte codec
                ///stage; <paramref name="datatype"/> may be <c>null</c> for a raw stream (then <see cref="__id"/> falls
                ///back to the endpoint's own id). Returns <c>this</c> for chaining.</summary>
                public Chunked Init(BytesDst dst, BytesDst datatype)
                {
                    this.datatype = datatype;
                    this.dst = dst;
                    return reset();
                }

                ///<summary>Convenience arming — the chain's own <see cref="_Adapter"/> serves as BOTH the inner byte
                ///stage and the datatype (its id identifies the stream): shorthand for <c>Init(_Adapter, _Adapter)</c>.</summary>
                public Chunked Init()
                {
                    datatype = _Adapter;
                    dst = _Adapter;
                    return reset();
                }

                Chunked reset()
                {
                    //NOTE: onStreamComplete is deliberately NOT cleared here — Receiver.OnStreamComplete(hook) plants
                    //it into this chain BEFORE the arming Init runs; it is consumed by invokeOnStreamComplete at the
                    //stream end (terminator or teardown), which always runs.
                    _rem = _lenGot = _state = 0;
                    tunnel_id = 0;
                    tunnelIdBytes = 0;
                    _tidGot = _overGot = 0;
                    _tunnelDone = false;
                    pureIdBytes = 0;
                    return this;
                }

                ///<summary>Arm for ONE inbound stream. <paramref name="fullId"/> is the id exactly as delivered to
                ///<c>_OnReceiving</c> — <c>src.id_bytes</c> bytes of wire, of which the low <paramref name="pureIdBytes"/>
                ///are the pack id and the rest is the captured front of <c>[tunnel_id][body]</c>. The prelude does not
                ///guess that width: on a carrier whose id field is wider than the pack id the surplus already holds the
                ///discriminator, on one as narrow as the pack id the discriminator is still on the wire, and only this
                ///number tells the two apart. <paramref name="tunnelIdBytes"/> 0 is a plain stream. Clears the chunk +
                ///private state. Returns <c>this</c> for chaining.</summary>
                public Chunked asTunnel(int fullId, int pureIdBytes, int tunnelIdBytes)
                {
                    reset();
                    this.fullId = fullId;
                    this.pureIdBytes = pureIdBytes;
                    this.tunnelIdBytes = tunnelIdBytes;
                    return this;
                }

                ///<summary>Armed as a tunnel end (<see cref="asTunnel"/> with a tunnel_id): its bytes feed a virtual connection.</summary>
                public bool isTunnel => 0 < tunnelIdBytes;

                ///<summary>
                ///This stream will not be completed — it ended as <see cref="Transmitter.Chunked.ABORT"/>, or the receiver
                ///carrying it was reset part-way. A tunnel end tells the virtual connection's receiver to drop the pack it
                ///was in the middle of; the physical connection is not involved.
                ///</summary>
                public void abandon()
                {
                    _rem = _lenGot = _state = 0;
                    if (isTunnel)
                        _Adapter.abandon();
                }

                ///<summary>Fired exactly once per armed stream, the moment <see cref="tunnel_id"/> has been shifted out of
                ///the dispatched id (tunnel endpoints only; never for a plain stream). Set it to resolve / route the inbound
                ///stream by tunnel_id (e.g. install the destination vconn into <see cref="dst"/>).</summary>
                public Action<int>? on_tunnel_id;

                ///<summary>The per-stream hook, planted DIRECTLY by the generated <c>Receiver.OnStreamComplete(hook)</c>
                ///override (<c>chain().onStreamComplete = hook</c>) right before this chain is armed. One-shot and
                ///nesting-safe by construction: <c>chain()</c> hands an inner stream a DIFFERENT (free) chain than the
                ///already-armed outer one. Consumed by <see cref="complete"/>.</summary>
                public Action<Receiver, bool>? onStreamComplete;

                ///<summary>The chain's terminal (leaf) Adapter — framer and leaf travel as ONE aggregate, so the
                ///stream-end default always has its target. Generated arming wires it (<c>_Adapter.Init(…)</c>);
                ///codec stages may sit between the framer and this leaf.</summary>
                public readonly BytesDst.Adapter _Adapter = new();

                ///<summary>Stream-boundary cleanup — the single call the generated <c>Chain</c> makes at BOTH ends of a
                ///stream's life: the completion branch (<paramref name="completed"/> <c>true</c>) and <c>Chain.Release</c>
                ///(<c>false</c>). Runs-and-consumes the armed hook; with no hook, a <see cref="FileStream"/> sink is
                ///closed (flushed by Dispose). Either way every per-stream reference on <see cref="_Adapter"/> is dropped.</summary>
                public void complete(Receiver src, bool completed)
                {
                    if (onStreamComplete != null)
                    {
                        onStreamComplete(src, completed);
                        onStreamComplete = null;
                    }
                    else if (_Adapter.dst is FileStream)
                        try
                        {
                            _Adapter.dst.Dispose();
                        }
                        catch
                        {
                        }

                    _Adapter.dst = null;
                    _Adapter.dst_ = null;
                    _Adapter.redirect = null;
                }

                ///<summary>
                ///Framework entry. Parses <c>[len][data]</c> chunks on a PRIVATE state machine, clamping
                ///<c>byte_max</c> to each chunk boundary before draining it into <see cref="dst"/>, until the
                ///<c>0x0000</c> terminator. Returns <c>true</c> on the terminator, <c>false</c> to park when the
                ///buffer is exhausted.
                ///</summary>
                public virtual bool __put_bytes(Receiver src)
                {
                    //tunnel_id prelude; a plain stream (tunnelIdBytes == 0) never enters it. The receiver had to consume
                    //src.id_bytes bytes before it could tell which pack had arrived, so on a tunnel frame everything
                    //above the pack id inside fullId is the captured front of [tunnel_id][body]. Those bytes are spent
                    //first and the remainder of the discriminator comes off the wire — which is the whole of it on a
                    //carrier whose id field is exactly the pack id. Straddle-safe: _tidGot and _overGot survive
                    //a park, so a discriminator split across two fills resumes where it stopped.
                    if (_tidGot < tunnelIdBytes)
                    {
                        var overread = src.id_bytes - pureIdBytes;
                        if (pureIdBytes < 1 || overread < 0 || tunnelIdBytes < overread)
                            throw new InvalidOperationException($"Tunnel arming mismatch: id_bytes({src.id_bytes}) - pure pack-id width({pureIdBytes}) = {overread} captured bytes, which does not fit a tunnel_id of {tunnelIdBytes} byte(s). A pack id is at least one byte, and surplus captured bytes would be body bytes this chain cannot replay.");
                        while (_tidGot < tunnelIdBytes)
                        {
                            int v;
                            if (_overGot < overread)
                                v = (int)((uint)fullId >> ((pureIdBytes + _overGot++) * 8)) & 0xFF;
                            else if (src.byte_ < src.byte_max)
                                v = src.buffer![src.byte_++];
                            else
                                break;
                            tunnel_id |= v << (8 * _tidGot++);
                        }
                        if (_tidGot < tunnelIdBytes)
                            return false; //the discriminator is split across fills, resume here
                    }
                    if (0 < tunnelIdBytes && !_tunnelDone)
                    {
                        _tunnelDone = true;
                        on_tunnel_id?.Invoke(tunnel_id);
                    }

                    for (;;)
                        switch (_state)
                        {
                            case 0: //read the 2-byte little-endian length prefix (straddle-safe, private state)

                                while (_lenGot < 2)
                                    if (src.byte_ < src.byte_max)
                                        _rem |= src.buffer![src.byte_++] << (8 * _lenGot++);
                                    else
                                        return false; //prefix split across fills → park, resume here

                                _lenGot = 0;
                                if (_rem == Transmitter.Chunked.ABORT)
                                {
                                    //The stream ends as VOID (see Transmitter.Chunked.ABORT). On a tunnel that is a relay telling us
                                    //the packet's source vanished part-way: the virtual connection drops the pack it was in the middle
                                    //of, and the stream counts as finished so the physical receiver reads its next pack — the
                                    //connection, shared by every tunnel on it, goes on. Inside a pack (a streamed field) nothing
                                    //completes the pack anymore, so that is a broken pack, reported like any other.
                                    abandon();
                                    if (!isTunnel)
                                        throw new InvalidDataException("The stream was aborted by its source.");
                                    return true;
                                }

                                if (_rem == 0)
                                {
                                    //Terminator [0]: the stream ends here. A codec inner stage (e.g. ChaCha20 → Zstd) may
                                    //still hold buffered bytes not yet drained to the downstream pack — e.g. the final
                                    //decrypted byte sitting in the cipher's scratch that the decompressor needs to finish its
                                    //frame, or decompressed plaintext not yet consumed. Drive the inner ONE more time with an
                                    //EMPTY input window so every stage flushes what it holds into its downstream before we
                                    //report completion. Without this, when delivery boundaries leave the last byte(s) buffered
                                    //exactly at the terminator, the innermost nested pack is stranded and decoded as empty.
                                    //
                                    //The flushed plaintext is dispatched to the wrapped pack through a re-entrant Write()
                                    //(the codec stage's Adapter calls dst.Write(zout)). That dispatch must run the slot.dst
                                    //dispatch loop — but a framing-level park during THIS chunk's delivery may have left mode
                                    //== STREAM_PACK, which would instead route the re-entrant Write() into unpark() and re-frame
                                    //the plaintext as a bogus chunk. The framing is finished at [0], so restore the pre-park
                                    //mode first, decoupling the framing-level streaming state from the inner pack dispatch.
                                    if (src.mode == STREAM_PACK)
                                        src.mode = src.streaming_mode;
                                    var flushMax = src.byte_max;
                                    src.byte_max = src.byte_; //empty window: no new wire bytes, only flush buffered stage output
                                    put_bytes(src);
                                    //A PREFIX-LESS string datatype (StringStream/UTFStream) cannot self-terminate — its
                                    //string ends WITH the stream. The flush above delivered anything still buffered in the
                                    //stages; the terminator makes the end authoritative HERE, so turn the chars accumulated
                                    //in chs into str, ready for get_string(). A leaf never armed (slot.state != bit — a
                                    //zero-byte stream) decodes as the empty string. A cut mid-character (mid varint / mid
                                    //UTF-8 sequence) is BYTES_DISTORTION (the UTF-8 cut substitutes U+FFFD, matching the
                                    //strict decoder's policy; the varint cut drops the partial bits). Exceeding the staged
                                    //ceiling is OVERFLOW — advisory, the chars are kept.
                                    if (datatype == StringStream.ONE || datatype == UTFStream.ONE)
                                    {
                                        if (src.slot!.state != (uint)src.bit)
                                            src.str = "";
                                        else
                                        {
                                            if (datatype == UTFStream.ONE)
                                            {
                                                if ((src.bytes_left & 0xFF) != 0)
                                                { //the terminator landed mid-sequence
                                                    error_handler.error(src, null, OnError.BYTES_DISTORTION, new InvalidDataException($"Malformed UTF-8: stream ends mid-sequence, {src.bytes_left & 0xFF} continuation byte(s) missing."));
                                                    if (src.chs!.Length == src.u4)
                                                        src.grow_chs((int)src.u4 + 1);
                                                    src.chs![src.u4++] = (char)0xFFFD;
                                                }
                                            }
                                            else if (src.bytes_left != 0) //the terminator landed mid-varint-char — the partial bits are dropped
                                                error_handler.error(src, null, OnError.BYTES_DISTORTION, new InvalidDataException("Malformed string: stream ends mid-varint character."));

                                            if (src.u8_ < src.u4)
                                                error_handler.error(src, null, OnError.OVERFLOW, new ArgumentOutOfRangeException($"max_chars < received chars : {src.u8_} < {src.u4}"));

                                            src.str = new string(src.chs.AsSpan(0, (int)src.u4));
                                            src.u8 = 0;
                                            src.bytes_left = 0;
                                            src.bit = ~src.bit; //release the leaf's park lock-step: slot.state == (uint)bit no longer holds
                                        }
                                    }
                                    src.byte_max = flushMax;
                                    return true;
                                }

                                _state = 1;
                                goto case 1;

                            case 1: //hand the chunk payload to dst, clamped to the chunk boundary
                            {
                                var feed = Math.Min(src.byte_max - src.byte_, _rem);
                                if (0 < feed)
                                {
                                    var savedMax = src.byte_max;
                                    var from = src.byte_;
                                    src.byte_max = from + feed;
                                    put_bytes(src); //a codec stage never self-completes → its return value is not an end signal
                                    src.byte_max = savedMax;
                                    _rem -= src.byte_ - from;
                                }

                                if (0 < _rem)
                                    return false; //chunk straddles fills, or dst parked → resume here

                                _state = 0; //chunk fully drained → read the next prefix
                                break;
                            }
                        }
                }

                ///<summary>Feeds the (chunk-clamped) window to the inner stage. Overridable seam for a framer subclass.</summary>
                public virtual bool put_bytes(Receiver src) => dst.__put_bytes(src);
            }

            ///<summary>Named alias only: a receive-side tunnel endpoint is just a <see cref="Chunked"/> armed as a tunnel
            ///via <see cref="Chunked.asTunnel(int,int,int)"/> — all behavior lives in <see cref="Chunked"/>.</summary>
            public abstract class Tunnel : Chunked
            {
            }

            ///<summary>
            ///Known-size file <b>consumer</b> — the receive half of a <c>File</c> packet. Wire form
            ///<c>[id][len][data…]</c>: a single varint-encoded total-length header up front, then
            ///exactly that many payload bytes — no per-chunk framing, no terminator (the count is the
            ///end-authority). Dispatched by <see cref="Receiver.__id"/> like a normal pack; payload bytes are drained
            ///into a pluggable pure-byte inner <see cref="Receiver.BytesDst"/> <c>dst</c> (reads only buffer/byte_/byte_max,
            ///never the slot). Resumable across socket fills via the standard false = park / true = complete contract.
            ///</summary>
            public class File : BytesDst
            {
                protected Stream dst = null!; //direct byte sink (any System.IO.Stream) — overridable

                //Application-level sink alternative to dst, armed by the AdHoc.BytesDst Init overloads: a byte consumer that
                //is not a System.IO.Stream (e.g. a virtual connection's Internal.BytesDst). Its Write() returns how many bytes
                //it ACCEPTED and may take fewer than offered, so the payload drain advances by that count and parks on 0.
                protected AdHoc.BytesDst? dst_; //non-null ⇒ payload goes here instead of dst
                protected int _id;
                protected uint _state; //resume cursor across parks
                protected long _rem;   //payload bytes left to write (countdown)

                public long maxStreamBytes = long.MaxValue; //cap on the declared payload length (the IDL [S(N)] limit); set by EVERY Init

                public int __id => _id;

                ///<summary>Convenience overload — <c>Init(dst, maxStreamBytes, int.MinValue)</c>: no dispatch id (id-less) — the stream
                ///serves an EMBEDDED FIELD data type of an outer pack (the field, not this framer, identifies it).</summary>
                public File Init(string dst, long maxStreamBytes) => Init(dst, maxStreamBytes, int.MinValue);

                ///<summary>(Re)configure: a built-in direct-file sink at <paramref name="dst"/> (created/truncated for writing) + the
                ///<c>[S(N)]</c> cap + dispatch id — the stream serves a dedicated TOP-LEVEL transmittable pack.</summary>
                public File Init(string dst, long maxStreamBytes, int id) => Init(new FileStream(dst, FileMode.Create, FileAccess.Write, FileShare.None), maxStreamBytes, id);

                ///<summary>Convenience overload — <c>Init(dst, maxStreamBytes, int.MinValue)</c>: no dispatch id (id-less) — the stream
                ///serves an EMBEDDED FIELD data type of an outer pack.</summary>
                public File Init(Stream dst, long maxStreamBytes) => Init(dst, maxStreamBytes, int.MinValue);

                ///<summary>PRIMARY (re)configuration: a caller-supplied byte sink (any <see cref="System.IO.Stream"/>) + the <c>[S(N)]</c>
                ///cap on the declared payload length (a longer declared length makes <see cref="__put_bytes"/> throw) + dispatch id
                ///(<see cref="int.MinValue"/> = id-less: embedded field). Returns <c>this</c> for chaining.</summary>
                public File Init(Stream dst, long maxStreamBytes, int id)
                {
                    _id = id;
                    this.maxStreamBytes = maxStreamBytes;
                    this.dst = dst;
                    dst_ = null;
                    _rem = 0;
                    _state = 0;
                    return this;
                }

                ///<summary>Convenience overload — <c>Init(dst, maxStreamBytes, int.MinValue)</c>: no dispatch id (id-less) — the stream
                ///serves an EMBEDDED FIELD data type of an outer pack.</summary>
                public File Init(AdHoc.BytesDst dst, long maxStreamBytes) => Init(dst, maxStreamBytes, int.MinValue);

                ///<summary>PRIMARY (re)configuration onto an application-level <see cref="AdHoc.BytesDst"/> sink — a byte consumer that
                ///is not a <see cref="System.IO.Stream"/> (e.g. a virtual connection's <c>Internal.BytesDst</c>) + the <c>[S(N)]</c> cap on
                ///the declared payload length (a longer declared length makes <see cref="__put_bytes"/> throw) + dispatch id
                ///(<see cref="int.MinValue"/> = id-less: embedded field).
                ///<para>Such a sink may accept fewer bytes than offered; the payload drain then parks and is re-driven until the
                ///declared length is satisfied. Returns <c>this</c> for chaining.</para></summary>
                public File Init(AdHoc.BytesDst dst, long maxStreamBytes, int id)
                {
                    _id = id;
                    this.maxStreamBytes = maxStreamBytes;
                    this.dst = null!;
                    dst_ = dst;
                    _rem = 0;
                    _state = 0;
                    return this;
                }

                ///<summary>
                ///Framework entry. Straddle-safely decodes the varint total-length header on a PRIVATE state
                ///machine, then writes exactly that many payload bytes DIRECTLY to <see cref="dst"/> (the file/stream
                ///sink). Closes the sink and returns <c>true</c> once the full payload is written.
                ///</summary>
                public virtual bool __put_bytes(Receiver src)
                {
                    int i;
                    switch (_state)
                    {
                        case 0:
                            if (!src.try_get_varint(_state = 1))
                                return false;
                            goto case 1;
                        case 1:
                            _rem = (long)src.u8;
                            if (maxStreamBytes < _rem)
                                throw new InvalidOperationException("File payload length " + _rem + " exceeds maxStreamBytes " + maxStreamBytes);
                            if (_rem == 0)
                                break;
                            _state = 2;
                            goto case 2;
                        case 2:
                            if (0 < (i = (int)Math.Min(_rem, src.byte_max - src.byte_)))
                            {
                                if (dst_ != null)
                                    //An application-level sink may take only part of the offer; charge only what it ACCEPTED so a
                                    //0-byte accept leaves _rem intact and parks below (the declared length stays the end-authority).
                                    i = dst_.Write(src.buffer!, src.byte_, i);
                                else
                                    dst.Write(src.buffer!, src.byte_, i); //Stream.Write is all-or-throw — no partial-write loop needed

                                src.byte_ += i;
                                _rem -= i;
                            }

                            if (0 < _rem)
                                return false;
                            break;
                    }

                    close();
                    return true;
                }

                ///<summary>Close the sink and drop the reference — runs at payload completion; teardown code may call it
                ///early so an aborted reception doesn't leak the handle. Idempotent.</summary>
                public void close()
                {
                    try
                    {
                        dst_?.Close();
                    }
                    catch
                    {
                    }
                    try
                    {
                        dst?.Dispose();
                    }
                    catch
                    {
                    }
                    dst_ = null;
                    dst = null!;
                }
            }

            ///<summary>
            ///Sink that fast-forwards through (and discards) any bytes. A framer installs it in place of
            ///an inner stage that completed early, so trailing chunk/payload padding is drained cleanly
            ///instead of dead-locking the framer on <c>consumed &lt; feed</c>. Stateless singleton.
            ///</summary>
            public sealed class NullDst : BytesDst
            {
                public static readonly NullDst Instance = new();
                public int __id => 0;

                public bool __put_bytes(Receiver src)
                {
                    src.byte_ = src.byte_max;
                    return false;
                }
            }
        }

        ///<summary>
        ///The outbound state machine and mirror image of <see cref="Receiver"/>: a <see cref="BytesSrc"/> that
        ///pulls queued packs and serializes them field by field into whatever buffer the transport offers. Each
        ///<c>Read</c> call fills the buffer as far as it can; when a value would overrun the buffer the machine
        ///parks (see <see cref="mode"/>) and the next call resumes it. It emits the leading packet ID, then the
        ///body, firing <c>OnSerializing</c>/<c>OnSerialized</c> around each pack.
        ///<para>
        ///Generated protocol code subclasses this with the concrete pack sources; an optional <see cref="Framing"/>
        ///layer can wrap the output to add 0xFF framing and a trailing CRC.
        ///</para>
        ///</summary>
        public abstract class Transmitter : Base_.Transmitter, BytesSrc
        {
            ///<summary>The keys the ChaCha20 stages of this session's pack chains encrypt with: the newest one. See <see cref="Connection.Keyring"/>.</summary>
            public readonly Keyring keys = new();

            ///<summary>
            ///Internal serialization-lifecycle interface layered over <see cref="BytesSrc"/>. A queued data source that
            ///needs hooks around its own serialization — to resolve / swap the actual <see cref="BytesSrc"/> that gets
            ///written, to react once the wire write of a pack completes, or to clean up on connection close — implements
            ///this instead of plain <see cref="BytesSrc"/>.
            ///<para>
            ///Implemented by the generated per-pack <c>DataPass</c> wrapper (the sending-queue element — it resolves the
            ///<see cref="BytesSrc"/> to serialize, so a framer like <see cref="Chunked"/> is pulled by it and does NOT
            ///implement this interface itself), by <see cref="Connection.Tunnel.Relay"/>, and by
            ///<see cref="Connection.Tunnel.EndPoint"/>. The base transmit loop does not call these hooks itself; the
            ///generated transmitter's <c>_OnSerializing</c> / <c>_OnSerialized</c> dispatch (and
            ///<see cref="Connection.Tunnel.Relay"/>'s own enqueue path) invoke them.
            ///</para>
            ///</summary>
            public interface IDataPass
            {
                ///<summary>Called when this entry is dequeued for serialization. Returns the actual <see cref="BytesSrc"/>
                ///to serialize (usually <c>this</c>), or <c>null</c> to skip it.</summary>
                public BytesSrc? OnSerializing(Transmitter transmitter);

                ///<summary>Called once the wire write of <paramref name="transmitted"/> has completed.</summary>
                public void OnSerialized(Transmitter transmitter, BytesSrc transmitted);

                ///<summary>Called when the owning connection is closing; release any held resources.</summary>
                public void Close(Transmitter transmitter);
            }

            public abstract int id { get; }

            ///<summary>
            ///The owning external connection, or <c>null</c> for free-standing / test transmitters.
            ///<see cref="notify_subscribers"/> and <see cref="Wake"/> read this property to reach
            ///<see cref="Connection.External.WakeTransmit"/> on the hosting transport.
            ///</summary>
            public abstract External? ext_connection { get; }

            ///<summary>
            ///Arms the per-stream completion hook — the resource-policy channel for streamed byte fields. The
            ///implementor of <c>__bytes(scope)</c> — the only party that knows how the stream it returns must be
            ///treated — calls this on the scope right before returning; the generated override plants the hook
            ///DIRECTLY into the chain about to be armed (<c>chain().onStreamComplete = …</c> — <c>chain()</c> is
            ///idempotent until the arming, so the imminent <c>stream(…)</c> picks the very same chain; an inner
            ///stream's arming can therefore never clobber an outer stream's hook). The generated <c>Chain</c>
            ///invokes the hook INSTEAD of the default when the stream ends, consuming it.
            ///<para>Second argument: <c>true</c> — the stream completed cleanly (intrinsic source EOF); <c>false</c> —
            ///it was torn down (abort/reset) — e.g. delete the source file ONLY after a successful send.</para>
            ///<para>When no hook is armed, the stream-end default runs — a
            ///<see cref="FileStream"/> source is closed, anything else only unreferenced. To suppress even that (e.g.
            ///keep a caller-owned <see cref="FileStream"/> open), call the parameterless <see cref="OnStreamComplete()"/>.</para>
            ///<para>Overridden by the generated Transmitter (only it knows its <c>Chain</c> machinery); the base has
            ///no chain to plant into.</para>
            ///</summary>
            public virtual void OnStreamComplete(Action<Transmitter, bool>? onStreamComplete) => throw new NotSupportedException("This Transmitter has no stream-chain machinery to plant the hook into.");

            ///<summary>Convenience overload — arms <see cref="OnStreamComplete_None"/>: "do nothing at the stream end",
            ///suppressing the stream-end default for the imminent stream.</summary>
            public void OnStreamComplete() => OnStreamComplete(OnStreamComplete_None);

            ///<summary>No-op hook: arms "do nothing at the stream end", suppressing the stream-end default.</summary>
            private static readonly Action<Transmitter, bool> OnStreamComplete_None = (_, _) =>
            {};

            ///<summary>
            ///A simplified, 'one-shot' transmitter designed to serialize a single, specific packet into a byte stream.
            ///<para>
            ///It acts as a temporary, virtual connection for a single serialization task, similar to `JSON.stringify`. This is ideal for serializing
            ///a known object to a destination like a file or a byte array, or for unit testing the serialization
            ///logic of a packet without the complexity of a network connection.
            ///</para>
            ///</summary>
            public class Virtual : Transmitter
            {
                public override int id => 0;
                public override External? ext_connection => null;
                BytesSrc? src;

                public Virtual() : base(null!) {}

                ///<summary>
                ///Configures the virtual transmitter to serialize a single packet.
                ///This method must be called before invoking the Read() method.
                ///</summary>
                ///<param name="src">The packet object to be serialized.</param>
                public void SetBytesSrc(BytesSrc src) => this.src = src;

                protected override BytesSrc? _OnSerializing() => src;

                protected override void _OnSerialized(BytesSrc transmitted) => src = null;

                public override bool IsIdle() => src == null;

                public void Reset_() => reset();

                protected override void reset()
                {
                    src = null;
                    base.reset();
                }
            }

            ///<summary>
            ///The per-pack serializer contract: one implementation per message type, driven by the
            ///<see cref="Transmitter"/> after it has emitted the packet ID. Generated code implements it to push
            ///each field into the transmitter's staging registers and buffer.
            ///</summary>
            public interface BytesSrc
            {
                ///<summary>
                ///Internal method called by the `Transmitter` to serialize data for a specific message type.
                ///Implementers should write to the `Transmitter`'s buffer using its `put_` methods.
                ///</summary>
                ///<param name="dst">The `Transmitter` instance providing the byte stream and serialization context.</param>
                ///<returns>True if the message part was successfully serialized with available buffer space; false if more buffer space is needed or processing is otherwise incomplete.</returns>
                public bool __get_bytes(Transmitter dst);

                ///<summary>
                ///Gets the unique identifier for this message type or data structure.
                ///</summary>
                int __id { get; }

                ///<summary>
                ///Terminal (leaf) producer — the END of a transmit stream chain. An <see cref="Adapter"/>
                ///bridges a real .NET <see cref="System.IO.Stream"/> (any kind: file, memory, network…) into the
                ///pure-byte <see cref="BytesSrc"/> contract, so it can sit at the bottom of a composed chain.
                ///As the chain leaf it has no inner stage to forward to.
                ///<para>At the stream end — the intrinsic source EOF, or teardown (<c>Chain.Release</c>) — the
                ///generated <c>Chain</c> runs the captured <see cref="Transmitter.OnStreamComplete"/> hook, or —
                ///when none was armed — the default: a <see cref="FileStream"/> source is
                ///closed, anything else only unreferenced. Delete-after-send and other custom policies belong in
                ///the hook.</para>
                ///</summary>
                public class Adapter : BytesSrc
                {
                    //PUBLIC on purpose: codegen re-arms a statically wired endpoint by DIRECT field access (the inline
                    //equivalent of Init minus the maxStreamBytes line) so a cap set once survives per-burst re-arms.
                    public Stream? src;                         //underlying byte source (any System.IO.Stream, incl. FileStream); null while armed as a re-entrant transmitter source
                    public long maxStreamBytes = long.MaxValue; //cap on TOTAL bytes read from src (the IDL [S(N)] limit); set by EVERY Init (unlimited when the overload takes no cap)
                    public long _total;                         //bytes read from src so far — reset by Init / codegen re-arm

                    public int __id => id;

                    public int id = int.MinValue; //endpoint id; reset to the int.MinValue sentinel by every id-less Init, stamped by every id-taking Init

                    //A STRUCTURED streamed datatype produces its bytes by re-entering the Transmitter itself rather than by
                    //reading a byte source. Since src is a System.IO.Stream — which a Transmitter cannot also be — that arming
                    //needs its own field and its own Init(Transmitter) overload.
                    Transmitter? _tx; //re-entrant structured-datatype source; null ⇒ src is a plain byte source

                    //PUBLIC for the same reason as src: codegen re-arms a statically wired endpoint by DIRECT field access.
                    //An application-level source that is neither a System.IO.Stream nor a Transmitter — e.g. a virtual
                    //connection's Internal.BytesSrc. Its Read() has a THREE-way result where Stream.Read has two: >0 bytes,
                    //0 = "nothing available right now but still open" (park), -1 = end of stream. Stream.Read never signals
                    //the middle case, so the two are handled by separate branches in __get_bytes.
                    public AdHoc.BytesSrc? src_; //application-level byte source; null ⇒ not armed as one
//region Init — path family (self-opened file source)

                    ///<summary>PRIMARY (re)configuration with an explicit endpoint <paramref name="id"/>. Opens the source file
                    ///read-only (shared) — the stream-end default closes it; delete-after-send
                    ///belongs in an <see cref="Transmitter.OnStreamComplete"/> hook.
                    ///<paramref name="maxStreamBytes"/> is the IDL <c>[S(N)]</c> cap on TOTAL bytes read; exceeding it makes
                    ///<see cref="__get_bytes"/> throw. Applies to THIS arming only. Returns <c>this</c> for chaining.</summary>
                    public Adapter Init(string src, long maxStreamBytes, int id)
                    {
                        this.id = id;
                        _total = 0;
                        this.src = new FileStream(src, FileMode.Open, FileAccess.Read, FileShare.Read);
                        _tx = null;
                        src_ = null;
                        this.maxStreamBytes = maxStreamBytes;
                        redirect = null;
                        return this;
                    }

                    ///<summary>id overload — <c>Init(src, long.MaxValue, id)</c> (no size cap).</summary>
                    public Adapter Init(string src, int id) => Init(src, long.MaxValue, id);

                    ///<summary>PRIMARY (re)configuration WITHOUT an id — stamps the <see cref="int.MinValue"/> sentinel, then
                    ///delegates to the id-taking primary.</summary>
                    public Adapter Init(string src, long maxStreamBytes) => Init(src, maxStreamBytes, int.MinValue);

                    ///<summary>Convenience overload — <c>Init(src, long.MaxValue)</c> (no size cap).</summary>
                    public Adapter Init(string src) => Init(src, long.MaxValue);
//endregion
//region Init — stream family (caller-supplied source; stream-end policy = the OnStreamComplete hook, else the stream-end default)

                    ///<summary>PRIMARY (re)configuration with a caller-supplied <see cref="System.IO.Stream"/>, read directly.
                    ///What happens to it at the stream end is decided by the <see cref="Transmitter.OnStreamComplete"/> hook the
                    ///supplier may arm, else by the stream-end default. <paramref name="maxStreamBytes"/> is the IDL
                    ///<c>[S(N)]</c> cap, set by EVERY <c>Init</c>. Returns <c>this</c> for chaining.</summary>
                    public Adapter Init(Stream src, long maxStreamBytes, int id)
                    {
                        this.id = id;
                        _total = 0;
                        this.src = src;
                        _tx = null;
                        src_ = null;
                        this.maxStreamBytes = maxStreamBytes;
                        redirect = null;
                        return this;
                    }

                    ///<summary>id overload — <c>Init(src, long.MaxValue, id)</c> (no size cap).</summary>
                    public Adapter Init(Stream src, int id) => Init(src, long.MaxValue, id);

                    ///<summary>PRIMARY (re)configuration with a caller-supplied source WITHOUT an id — stamps the
                    ///<see cref="int.MinValue"/> sentinel, then delegates to the id-taking primary.</summary>
                    public Adapter Init(Stream src, long maxStreamBytes) => Init(src, maxStreamBytes, int.MinValue);

                    ///<summary>Convenience overload — <c>Init(src, long.MaxValue)</c> (no size cap).</summary>
                    public Adapter Init(Stream src) => Init(src, long.MaxValue);
//endregion
//region Init — re-entrant transmitter source (see _tx)

                    ///<summary>Arm as a re-entrant source for a STRUCTURED streamed datatype: bytes are produced by re-entering
                    ///<paramref name="tx"/> instead of by reading a byte source. Clears <see cref="src"/> and the size cap, and
                    ///stamps the <see cref="int.MinValue"/> id sentinel — such a stream is an embedded field, never dispatched by id.</summary>
                    public Adapter Init(Transmitter tx)
                    {
                        id = int.MinValue;
                        _total = 0;
                        src = null;
                        src_ = null;
                        _tx = tx;
                        maxStreamBytes = long.MaxValue;
                        redirect = null;
                        return this;
                    }
//endregion
//region Init — application-source family (caller-supplied AdHoc.BytesSrc; never touched by the stream-end default)

                    ///<summary>PRIMARY (re)configuration with a caller-supplied <see cref="AdHoc.BytesSrc"/> source — an application-level
                    ///byte producer that is neither a <see cref="System.IO.Stream"/> nor a <see cref="Transmitter"/> (e.g. a virtual
                    ///connection's <c>Internal.BytesSrc</c>) — and an explicit endpoint <paramref name="id"/>. Adopts
                    ///<paramref name="src"/>. The stream-end default never closes such a source (it only drops the
                    ///reference); closing belongs to the supplier — via an <see cref="Transmitter.OnStreamComplete"/> hook if wanted.
                    ///<para>End of stream is the explicit <c>-1</c> from <see cref="AdHoc.BytesSrc.Read"/>; a <c>0</c> means "nothing
                    ///available yet, still open" and merely parks. <paramref name="maxStreamBytes"/> is the IDL <c>[S(N)]</c> cap on TOTAL
                    ///bytes read, set by EVERY <c>Init</c>.</para>
                    ///Returns <c>this</c> for chaining.</summary>
                    public Adapter Init(AdHoc.BytesSrc src, long maxStreamBytes, int id)
                    {
                        this.id = id;
                        _total = 0;
                        this.src = null;
                        src_ = src;
                        _tx = null;
                        this.maxStreamBytes = maxStreamBytes;
                        redirect = null;
                        return this;
                    }

                    ///<summary>id overload — <c>Init(src, long.MaxValue, id)</c>: uncapped. This is what a
                    ///generated tunnel endpoint arms its transmit Adapter with: <c>_Adapter.Init(Internal.BytesSrc, id)</c>.
                    ///<para>NOTE the second argument is an <c>int</c> id here, but a <c>long</c> selects the cap overload below — the same
                    ///id/cap split the stream family already has.</para></summary>
                    public Adapter Init(AdHoc.BytesSrc src, int id) => Init(src, long.MaxValue, id);

                    ///<summary>PRIMARY (re)configuration with a caller-supplied source WITHOUT an id — stamps the
                    ///<see cref="int.MinValue"/> sentinel, then delegates to the id-taking primary.</summary>
                    public Adapter Init(AdHoc.BytesSrc src, long maxStreamBytes) => Init(src, maxStreamBytes, int.MinValue);

                    ///<summary>Convenience overload — <c>Init(src, long.MaxValue)</c> (no size cap).</summary>
                    public Adapter Init(AdHoc.BytesSrc src) => Init(src, long.MaxValue);
//endregion

                    public BytesSrc? redirect;

                    ///<summary>
                    ///Reads bytes straight into <c>dst.buffer</c> until the buffer is full or EOF. Returns <c>false</c> on
                    ///buffer-full — the framework's slot.src dispatch keeps driving this instance until EOF, no per-class
                    ///takeover needed. Returns <c>true</c> on EOF; cleanup then runs at the Chain level — the captured
                    ///<see cref="Transmitter.OnStreamComplete"/> hook, else the stream-end default.
                    ///</summary>
                    public virtual bool __get_bytes(Transmitter dst)
                    {
                        var buf = dst.buffer;
                        for (;;)
                        {
                            if (redirect != null)
                            {
                                if (!redirect.__get_bytes(dst))
                                    return false; //nested stream still active
                                redirect = null;  //nested chained stream completed — continue below
                            }

                            if (dst.byte_ >= dst.byte_max)
                                break;

                            if (_tx != null) //structured datatype: re-enter the transmitter
                            {
                                var position = dst.byte_;
                                if (dst.mode == STREAM_PACK)
                                    dst.mode = dst.streaming_mode;
                                var n = _tx.read(dst.buffer!);
                                dst.buffer = buf; //read() nulls buffer at exit; restore for the framer
                                if (n == int.MinValue)
                                    return true; //nested pack fully serialized
                                if (dst.byte_ == position && redirect == null)
                                    break; //no progress → park
                            }
                            else if (src_ != null) //application-level source: Read is three-way (>0 / 0 = park / -1 = EOF)
                            {
                                var n = src_.Read(dst.buffer!, dst.byte_, dst.byte_max - dst.byte_);
                                if (n == 0)
                                    break; //nothing available yet but still open → park, framework re-drives

                                if (n < 0)
                                    return true; //EOF, packet done — cleanup runs at the Chain level: the captured OnStreamComplete hook, else the stream-end default

                                if (maxStreamBytes < (_total += n))
                                    throw new InvalidOperationException("Stream would exceed max size of " + maxStreamBytes + " bytes.");
                                dst.byte_ += n;
                            }
                            else //plain byte source (file/stream)
                            {
                                //Stream.Read returns 0 ONLY at EOF — never as a transient "no data yet" — so a single test
                                //covers the end of the source; there is no separate short-read park to handle.
                                var n = src!.Read(dst.buffer!, dst.byte_, dst.byte_max - dst.byte_);
                                if (n == 0)
                                    return true; //EOF, packet done — cleanup runs at the Chain level: the captured OnStreamComplete hook, else the stream-end default

                                if (maxStreamBytes < (_total += n))
                                    throw new InvalidOperationException("Stream would exceed max size of " + maxStreamBytes + " bytes.");
                                dst.byte_ += n;
                            }
                        }

                        dst.buffer = buf;
                        return false; //buffer full → more may remain (park)
                    }
                }
            }

            ///<summary>
            ///Transmit-side error taxonomy: the codes reported to the <see cref="OnErrorHandler"/> when a pack
            ///cannot be sent (queue overflow, rejected/discarded packs, timeouts).
            ///</summary>
            public enum OnError
            {
                ///<summary>
                ///Transmitting packet was rejected by dataflow or business logic rules.
                ///</summary>
                REJECTED = 0,

                ///<summary>
                ///Buffer overflow occurred, typically because a declared length exceeds
                ///the buffer capacity or a predefined maximum size.
                ///</summary>
                OVERFLOW = 1,

                ///<summary>
                ///Timeout occurred during packet transmission or reception.
                ///</summary>
                TIMEOUT = 2,

                ///<summary>
                ///Generic/unspecified error during packet processing or handling.
                ///</summary>
                ERROR = 3,

                ///<summary>
                ///Unsent packets were discarded because the actor was closed or disposed.
                ///</summary>
                DISCARDED_ONCLOSE = 4,

                ///<summary>
                ///Unsent packets were discarded due to current state rules
                ///or protocol state expectations.
                ///</summary>
                DISCARDED_BYSTATE = 5,

                ///<summary>
                ///Attempted to send a packet by an actor that does not support
                ///transmitting or sending messages (no transmit/send behavior defined).
                ///</summary>
                ACTOR_NOT_TRANSMITTABLE = 6,
            }

            ///<summary>
            ///Process-wide sink for transmit-side errors (queue overflow, rejected/discarded packs, timeouts).
            ///Defaults to a handler that writes to the console; replace it to route errors elsewhere. Shared by
            ///all transmitters, so assign once at startup.
            ///</summary>
            public static OnErrorHandler error_handler = OnErrorHandler.DEFAULT;

            ///<summary>
            ///Defines an interface for handling errors that occur in a `BytesSrc` context.
            ///</summary>
            public interface OnErrorHandler
            {
                ///<summary>
                ///A default `OnErrorHandler` implementation that logs errors to the console.
                ///</summary>
                static OnErrorHandler DEFAULT = new ToConsole();

                ///<summary>
                ///A concrete `OnErrorHandler` that writes error information to the console.
                ///</summary>
                class ToConsole : OnErrorHandler
                {
                    ///<summary>
                    ///Handles a `BytesSrc` error by printing details to the console.
                    ///</summary>
                    ///<param name="src">The `AdHoc.BytesSrc` where the error occurred.</param>
                    ///<param name="arg">Additional data (e.g., the packet being processed/purged).</param>
                    ///<param name="error">The type of error .</param>
                    ///<param name="ex">An optional exception associated with the error.</param>
                    public void error(AdHoc.BytesSrc src, object? arg, OnError error, Exception? ex = null)
                    {
                        switch (error)
                        {
                            case OnError.DISCARDED_ONCLOSE:
                                //arg contains the packet that was left in the queue
                                Console.WriteLine("DISCARDED_ONCLOSE (Connection Closed). Dropped pack: " + arg + " at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                            case OnError.DISCARDED_BYSTATE:
                                Console.WriteLine("DISCARDED (State Rule). Pack: " + arg + " at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                            case OnError.OVERFLOW:
                                Console.WriteLine("OVERFLOW at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                            case OnError.REJECTED:
                                Console.WriteLine("REJECTED at " + src + (ex == null ? "" : ex + Environment.StackTrace));

                                return;
                            case OnError.TIMEOUT:
                                Console.WriteLine("TIMEOUT. Pack: " + arg + " at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                            case OnError.ERROR:
                                Console.WriteLine("ERROR. Pack: " + arg + " at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                            default:
                                Console.WriteLine("Error at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                        }
                    }
                }

                ///<summary>
                ///Handles a `BytesSrc` error.
                ///</summary>
                ///<param name="src">The `AdHoc.BytesSrc` where the error occurred.</param>
                ///<param name="arg"></param>
                ///<param name="error">The type of error.</param>
                ///<param name="ex">An optional exception associated with the error.</param>
                void error(AdHoc.BytesSrc src, object? arg, OnError error, Exception? ex = null);
            }

            ///<summary>
            ///Defines an interface for handling events generated by a `Transmitter`.
            ///</summary>
            public interface EventsHandler
            {
                ///<summary>
                ///Called just before a packet's serialization process begins via its `BytesSrc` handler.
                ///</summary>
                ///<param name="dst">The `Transmitter` instance that is about to send the packet.</param>
                ///<param name="src">The `BytesSrc` instance representing the packet to be serialized.</param>
                void OnSerializing(Transmitter dst, BytesSrc src) {}

                ///<summary>
                ///Called after a complete packet has been successfully serialized and (notionally) sent
                ///from the internal perspective of the `Transmitter`'s processing loop.
                ///The actual transmission to an external sink depends on the `Transmitter.Read` method being called.
                ///</summary>
                ///<param name="dst">The `Transmitter` instance that has completed sending the packet.</param>
                ///<param name="src">The `BytesSrc` in
                ///stance representing the packet that was sent.</param>
                void OnSerialized(Transmitter dst, BytesSrc src) {}
            }

            ///<summary>
            ///The current event handler for this transmitter.
            ///</summary>
            protected EventsHandler? handler;

            ///<summary>
            ///Atomically exchanges the current event handler with a new one.
            ///</summary>
            ///<param name="handler">The new event handler to set.</param>
            ///<returns>The event handler that was previously set.</returns>
            public EventsHandler exchange(EventsHandler handler) => Interlocked.Exchange(ref this.handler, handler);

            ///<summary>
            ///Initializes a new instance of the <see cref="org.unirail.AdHoc.Transmitter.Transmitter"/> class.
            ///</summary>
            ///<param name="handler">The event handler for transmitter events.</param>
            ///<param name="power_of_2_sending_queue_size">The size of the internal sending queues, expressed as a power of 2 (e.g., 5 for a size of 2^5=32). Default is 5.</param>
            public Transmitter(EventsHandler handler, int power_of_2_sending_queue_size = 5) : base(power_of_2_sending_queue_size)
            {
                this.handler = handler;
                root = new Slot(this, null);
            }
#region sending
            //do not forget to  set u8 = sending_out.value;
            protected abstract BytesSrc? _OnSerializing();
            protected abstract void _OnSerialized(BytesSrc bytes);

            public abstract bool IsIdle();

            //No lock for the sending queue: the generated connection keeps it in a RingBuffer - one CAS a put, one a take,
            //and a close from any thread empties it.
#endregion
#region value_pack transfer
            ///<summary>
            ///Sets `u8` to `src`, then calls `put_bytes(handler, next_case)` to serialize a nested message.
            ///This is used when `src` itself is the value to be serialized by `handler`.
            ///</summary>
            ///<param name="src">The `ulong` value to be effectively passed to or used by the `handler`.</param>
            ///<param name="handler">The `BytesSrc` handler for the nested message part.</param>
            ///<param name="next_case">The state to retry at if serialization by `handler` requires more buffer space.</param>
            ///<returns>True if `handler` completed serialization successfully; false if a retry is needed.</returns>
            public bool put_bytes(ulong src, BytesSrc handler, uint next_case)
            {
                u8 = src;
                return put_bytes(handler, next_case);
            }

            ///<summary>
            ///Sets `u8` to `src`, then calls `put_bytes(handler)` to serialize a nested message.
            ///This is used when `src` itself is the value to be serialized by `handler`, assuming no retry is needed.
            ///</summary>
            ///<param name="src">The `ulong` value to be effectively passed to or used by the `handler`.</param>
            ///<param name="handler">The `BytesSrc` handler for the nested message part.</param>
            public void put_bytes(ulong src, BytesSrc handler)
            {
                u8 = src;
                put_bytes(handler);
            }

            ///<summary>
            ///Invokes the `__get_bytes` method on the provided `BytesSrc` instance `src`
            ///to serialize its data using the current transmitter context.
            ///Assumes `src` is part of the current serialization slot, skipping packet ID writing.
            ///</summary>
            ///<param name="src">The `BytesSrc` instance to serialize.</param>
            public void put_bytes(BytesSrc src)
            {
                slot!.state = 1; //skip write id
                src.__get_bytes(this);
            }

            ///<summary>
            ///Serializes a nested object into the byte stream, managing the serialization stack.
            ///The method advances the slot stack and directly invokes the serializer (`__get_bytes`)
            ///for the nested <paramref name="src"/> object.
            ///</summary>
            ///<param name="src">The <see cref="BytesSrc"/> instance (typically a Pack serializer) that will provide the bytes.</param>
            ///<param name="next_case">The state for the parent slot to transition to if serialization is incomplete
            ///(e.g., buffer full) and requires a retry.</param>
            ///<returns><c>true</c> if the entire object was successfully serialized into the current buffer.
            ///Returns <c>false</c> if the buffer became full and a retry is needed.</returns>
            public bool put_bytes(BytesSrc src, uint next_case)
            {
                var O = slot!; //Store current slot to manage the serialization stack.
                //Advance to the next slot in the chain for the nested object.
                slot = O.next ?? (O.next = new Slot(this, O));

                slot.src = src;
                slot.state = 1;

                if (src.__get_bytes(this))
                {
                    slot = O;
                    return true;
                }

                O.state = next_case;
                return false;
            }

            ///<summary><c>int</c> overload of <see cref="put_bytes(BytesSrc,uint)"/> — the generated code passes an <c>int next_case</c>.</summary>
            public bool put_bytes(BytesSrc src, int next_case) => put_bytes(src, (uint)next_case);
#endregion

            ///<summary>
            ///Implements a framing encoder that handles a byte-oriented protocol with 0xFF as a frame start marker,
            ///0x7F-based escaping for 0x7F and 0xFF bytes within the payload, and a 2-byte CRC.
            ///Frame structure: 0xFF (start marker) + encoded_payload + 2_byte_CRC.
            ///It takes raw packet data from an `upper_layer` Transmitter, encodes it, and provides the framed data via its `Read` method.
            ///</summary>
            public class Framing : AdHoc.BytesSrc, EventsHandler
            {
                public bool isOpen() => upper_layer.isOpen(); //Check if the upper layer is open

                ///<summary>
                ///The `Transmitter` instance from which raw, unframed packet data is read.
                ///</summary>
                public Transmitter upper_layer; //Handles transmission of encoded frames

                ///<summary>
                ///Handles events for the encoding process, typically forwarding them from the original handler of the `upper_layer` before it was hooked by this framing instance.
                ///</summary>
                public EventsHandler handler; //Encoding process event handler

                ///<summary>
                ///Atomically exchanges the current event handler with a new one.
                ///</summary>
                ///<param name="handler">New event handler</param>
                ///<returns>Previous event handler</returns>
                public EventsHandler exchange(EventsHandler handler) => Interlocked.Exchange(ref this.handler, handler);

                ///<summary>
                ///Initializes a new instance of the <see cref="Framing"/> class.
                ///</summary>
                ///<param name="upper_layer">The `Transmitter` instance that will provide the raw packets to be framed.</param>
                public Framing(Transmitter upper_layer) => switch_to(upper_layer);

                ///<summary>
                ///Switches the framing layer to operate on a new `upper_layer` transmitter.
                ///This also resets the internal state of the framing encoder and hooks its event handling into the new `upper_layer`.
                ///</summary>
                ///<param name="upper_layer">New `Transmitter` instance to provide raw packets.</param>
                public void switch_to(Transmitter upper_layer)
                {
                    bits = 0;
                    shift = 0;
                    crc = 0;
                    if (this.upper_layer != null)
                    {
                        this.upper_layer.reset();
                        this.upper_layer.exchange(handler);
                    }

                    handler = (this.upper_layer = upper_layer).exchange(this);
                }

                int enc_position; //Current position for writing encoded bytes
                int raw_position; //Current position for reading raw input bytes

                ///<summary>
                ///Estimates the required space in the output buffer (`dst` in `Read` method) to hold
                ///a segment of raw data after encoding, including frame markers and CRC.
                ///This is used to determine how much raw data can be safely read from the `upper_layer`.
                ///</summary>
                ///<param name="limit">The total available size of the current output buffer segment.</param>
                ///<returns>True if sufficient space is estimated to be available in the output buffer for reading more raw data and encoding it; false otherwise.</returns>
                bool allocate_raw_bytes_space(int limit)
                {
                    //Divide free space.
                    raw_position = enc_position +
                                   1 +                          //Space for 0xFF frame start marker
                                   (limit - enc_position) / 8 + //Worst case byte expansion for payload (approx)
                                   CRC_LEN_BYTES + 4;           //CRC plus possible expansion (max 2 extra bytes for 0x7F encoding of CRC)

                    return raw_position < limit;
                }

                public void Close()
                {
                    Reset();
                    upper_layer.Close();
                }

                ///<summary>
                ///Resets the internal state of the framing encoder and the `upper_layer` transmitter.
                ///This prepares it for a new sequence of packets or a new connection.
                ///</summary>
                protected void Reset()
                {
                    upper_layer.reset();
                    bits = 0;
                    shift = 0;
                    crc = 0;
                }

                ///<summary>
                ///Reads raw packet data from the `upper_layer`, encodes it using the framing protocol
                ///(including 0x7F escaping and CRC calculation), and writes the resulting framed bytes into `dst`.
                ///</summary>
                ///<param name="dst">The destination buffer for the encoded, framed data.</param>
                ///<param name="dstByte">The starting offset in `dst` to write to.</param>
                ///<param name="dst_bytes">The maximum number of bytes to write to `dst`.</param>
                ///<returns>
                ///The number of bytes written to `dst`.
                ///Returns 0 if `dst` has insufficient space.
                ///Returns -1 if the `upper_layer` has no more raw packets to provide.
                ///</returns>
                public int Read(byte[] dst, int dstByte, int dst_bytes)
                {
                    enc_position = dstByte;
                    var limit = dstByte + dst_bytes;

                    while (allocate_raw_bytes_space(limit))
                    {
                        var fix = raw_position;
                        var len = upper_layer.Read(dst, raw_position, limit - raw_position);

                        if (len < 1)
                            return dstByte < enc_position ? enc_position - dstByte : len;

                        for (var max = fix + len; raw_position < max;)
                            enc_position = encode(dst[raw_position++], dst, enc_position);
                    }

                    return dstByte < enc_position ? enc_position - dstByte : 0;
                }

                public void OnSerializing(Transmitter dst, BytesSrc src)
                {
                    handler?.OnSerializing(dst, src);
                    dst.buffer![enc_position++] = 0xFF; //write starting frame byte
                }

                ///<summary>
                ///Handles the `OnSerialized` event from the `upper_layer` transmitter.
                ///This signifies that a complete raw packet has been provided by the `upper_layer`.
                ///This method encodes any remaining bytes of that packet, then encodes and appends the CRC checksum.
                ///It finalizes any bit-level encoding for the frame and resets its state for the next packet.
                ///</summary>
                ///<param name="dst">The `upper_layer` transmitter instance.</param>
                ///<param name="src">The `BytesSrc` instance of the packet that was just completed by `upper_layer`.</param>
                public void OnSerialized(Transmitter dst, BytesSrc src)
                {
                    while (raw_position < dst.byte_)
                        enc_position = encode(dst.buffer![raw_position++], dst.buffer, enc_position);

                    //the packet sending completed write crc
                    int fix = crc; //crc will continue counting on  encode() calling , so fix it
                    enc_position = encode(fix & 0xFF, dst.buffer!, encode(fix >> 8 & 0xFF, dst.buffer!, enc_position));
                    if (0 < shift)
                    {
                        dst.buffer![enc_position++] = (byte)bits;
                        if (bits == 0x7F)
                            dst.buffer![enc_position++] = 0;
                    }

                    if (allocate_raw_bytes_space(dst.byte_max))
                        dst.byte_ = raw_position;
                    else
                        dst.byte_max = raw_position = dst.byte_; //no more space. prevent continue

                    bits = 0;
                    shift = 0;
                    crc = 0;
                    handler?.OnSerialized(dst, src);
                }

                ///<summary>
                ///Encodes a single source byte into the destination buffer, applying 0x7F-based escaping
                ///and updating the running CRC. Manages a bit accumulator for byte alignment.
                ///</summary>
                ///<param name="src">The source byte to encode.</param>
                ///<param name="dst">The destination buffer for encoded bytes.</param>
                ///<param name="dst_byte">The current write position in `dst`.</param>
                ///<returns>The updated write position in `dst` after encoding the byte.</returns>
                int encode(int src, byte[] dst, int dst_byte)
                {
                    crc = crc16((byte)src, crc);
                    var v = (bits |= src << shift) & 0xFF;
                    if ((v & 0x7F) == 0x7F)
                    {
                        dst[dst_byte++] = 0x7F;
                        bits >>= 7;
                        if (shift < 7)
                            shift++;
                        else //a full byte in enc_bits
                        {
                            if ((bits & 0x7F) == 0x7F)
                            {
                                dst[dst_byte++] = 0x7F;
                                bits >>= 7;
                                shift = 1;
                                return dst_byte;
                            }

                            dst[dst_byte++] = (byte)bits;
                            shift = 0;
                            bits = 0;
                        }

                        return dst_byte;
                    }

                    dst[dst_byte++] = (byte)v;
                    bits >>= 8;
                    return dst_byte;
                }

                //Internal state variables
                int bits;   //Accumulator for bits during 0x7F-based encoding.
                int shift;  //Current bit shift within the `bits` accumulator.
                ushort crc; //Running CRC16 checksum for the current frame's payload.
            }
#region Slot
            ///<summary>
            ///A journalling transport stage. It hands the transmitter's bytes on unchanged and keeps a copy of the
            ///packs the generated code brackets with <see cref="packStart"/> / <see cref="packEnd"/>, so that a peer
            ///whose socket died can have the stream continued from the position it names.
            ///<para>It is the FIRST stage of a connection's chain and reads straight from the <see cref="Transmitter"/>
            ///(<see cref="Init_"/>). What it journals is what a compressor or cipher standing outside it transforms on
            ///the way out, so a replay is transformed again on the fresh socket.</para>
            ///<para>Inside the stage a position is a byte offset in the journalled stream, counted from the start of the
            ///session. On the wire — the header of a marked pack, <c>Resume_</c>, <c>Ack_</c>, <c>Lost_</c> — a position is
            ///two fields: <c>pos</c>, the low 32 bits of the offset, and <c>time</c>, the low <see cref="TIME_BITS"/> of the
            ///unix seconds the pack is sent at. The offset is resolved back against <see cref="next_"/> by a signed 32-bit
            ///difference, so a session's positions must stay within 2 GB of each other: <see cref="capacity"/> is capped at
            ///half that. The seconds tell a position of an earlier session apart: one older than the oldest byte the journal
            ///holds is not this session's. Offsets:
            ///<see cref="base_"/> — the first byte still held;
            ///<see cref="acked_"/> — acknowledged by the peer, what lies below it is given back: files whole, the buffer in memory on every acknowledgement;
            ///<see cref="sent_"/> — handed to the transport, <see cref="resume"/> moves it;
            ///<see cref="next_"/> — produced so far, and the position the next marked pack gets.
            ///Invariant: <c>base &lt;= acked &lt;= sent &lt;= next</c>.</para>
            ///<para>Storage: the journal lives in segment files under <see cref="dir"/>, <see cref="segment"/> bytes each, the
            ///last one still being written; a <see cref="HOT"/>-byte buffer, allocated once for the life of the stage, holds the
            ///newest bytes until it is full and written out. A replay reads the files straight into the transport buffer, the
            ///tail from that buffer. Files entirely below the acknowledged position are deleted on every <see cref="ack"/>; once
            ///everything is acknowledged nothing is held.
            ///<see cref="capacity"/> caps the journal; at the cap <see cref="Read"/> produces nothing until an <see cref="ack"/>
            ///frees room. The peer acknowledges when asked: <see cref="packEnd"/> tells the generated code when to send that
            ///ask, behind the data it refers to.</para>
            ///<para>Lifecycle: from creation, and after <see cref="Close"/> finds <see cref="External.resumable"/>
            ///unexpired, the stage is <see cref="awaiting"/>: unmarked packs leave it, so that the peer can be identified
            ///and can name its position, while marked packs are journalled only, until that position arrives through
            ///<see cref="resume"/>. A session ends when <c>Close()</c> finds the deadline
            ///expired, or when a file operation fails: the files are deleted, the positions are re-seeded and, on a
            ///failure, the socket is aborted.</para>
            ///<para><see cref="resume"/> and <see cref="ack"/> may be called from any thread. They post to the
            ///transport thread, which applies them at the start of its next <see cref="Read"/>, and wake it.</para>
            ///</summary>
            public class Resumable : AdHoc.BytesSrc
            {
#region clock
                ///<summary>
                ///Unix time in MINUTES, truncated to an int. About 29.6 million today — some 25 bits — so the whole
                ///value fits with millennia to spare and plain signed comparison holds. 0 is 1970 and never a real
                ///reading, which leaves it free as the "not set" marker of every <c>resumable</c> field.
                ///</summary>
                public static int now() => (int)(DateTimeOffset.UtcNow.ToUnixTimeSeconds() / 60);

                ///<summary>True when <paramref name="deadline"/> is 0 or already passed.</summary>
                public static bool expired(int deadline) => deadline == 0 || deadline <= now();
#endregion
#region segment files
                ///<summary>
                ///Root of the segment files. Every process writes into its own subdirectory, named by its pid;
                ///Read on the first flush; the subdirectories of processes that are gone are left for the host to clean.
                ///</summary>
                public static string dir = Path.Combine(Path.GetTempPath(), "AdHoc", "journal");

                private static string? pid_dir;

                private static string pidDir()
                {
                    return pid_dir ??= Directory.CreateDirectory(Path.Combine(dir, Environment.ProcessId.ToString())).FullName; //idempotent: two threads create the same directory
                }

                private static bool alive(int pid)
                {
                    try
                    {
                        using var p = System.Diagnostics.Process.GetProcessById(pid);
                        return !p.HasExited;
                    }
                    catch (Exception e) when (e is ArgumentException or InvalidOperationException)
                    {
                        return false;
                    }
                }

                private static void delete (string file)
                {
                    try
                    {
                        System.IO.File.Delete(file);
                    }
                    catch (Exception e) when (e is IOException or UnauthorizedAccessException)
                    {
                    }
                }
#endregion

                ///<summary>Default <see cref="segment"/>: 256 KB.</summary>
                private const int SEGMENT = 1 << 18;

                ///<summary>The buffer in memory: 2 KB, allocated once and kept for the life of the stage.</summary>
                private const int HOT = 1 << 11;

                ///<summary>Bits of unix seconds in the <c>time</c> of a position on the wire: 21, wrapping every 24 days.</summary>
                private const int TIME_BITS = 21;

                private const long TIME_MASK = (1L << TIME_BITS) - 1;

                private static long seconds() => DateTimeOffset.UtcNow.ToUnixTimeSeconds();

                private static uint stamp() => (uint)(seconds() & TIME_MASK);

                ///<summary>Seconds from <paramref name="since"/> to <paramref name="time"/>, both <see cref="TIME_BITS"/> wide.</summary>
                private static long since(uint time, long since) => (time - since) << 64 - TIME_BITS >> 64 - TIME_BITS;

                ///<summary>The offset a <c>pos</c> on the wire names: the one nearest to <see cref="next_"/> with those low 32 bits.</summary>

                ///<summary>The seconds the oldest byte the journal holds was journalled at, <see cref="TIME_BITS"/> wide.</summary>
                private long baseTime() => 0 < files.Count ? file_times[0] : hot_time;

                ///<summary>
                ///The least room the transmitter makes progress in: it writes a fixed 8-byte value or a bits transaction whole or
                ///not at all, so under the cap the stage offers at least this much, or nothing.
                ///</summary>
                private const int ROOM = 16;

                ///<summary>
                ///An acknowledgement is asked for at least this often, in seconds, while anything is unacknowledged: a peer that
                ///restarts names the oldest unacknowledged position, and what lies above it is replayed to it again.
                ///</summary>
                private const int ASK_SECONDS = 60;

                ///<summary>The largest backlog held, in bytes: the files plus the segment in memory.</summary>
                private readonly long capacity;

                ///<summary>Size of one segment, in bytes: the memory this stage keeps and the size of every file it writes.</summary>
                private readonly int segment;

                private Transmitter? src_; //null once the session is over

                ///<summary>The transmitter this stage journals; null once the session is over.</summary>
                public Transmitter? transmitter => src_;

                //The positions belong to the transmit runner: no other thread reads them. What the receive thread needs
                //for resume()/ack() is published once per pull — see publish().
                private long base_, acked_, sent_, next_;
                private long base_pub, next_pub, boundary_pub, base_time_pub; //Volatile.Read/Write only

                //the files hold [base, hotBase()), hot holds [hotBase(), next); every file but the last is one full segment
                private readonly List<string> files = new();
                private readonly List<long> file_times = new(); //the seconds each file's first byte was journalled at, TIME_BITS wide
                private FileStream? ch;                         //the last file, open while it is still being written
                private int written;                            //bytes in the last file
                private readonly byte[] hot = new byte[HOT];
                private int hot_len;
                private long hot_time;         //the seconds hot's first byte was journalled at, TIME_BITS wide
                private FileStream? replay_ch; //open on the file a replay is reading
                private int replay_index = -1; //its index in files

                //the marked pack in progress
                private bool open;
                private long open_start; //its stream position
                private int mark;        //where its unjournalled bytes start in the transmitter's buffer

                private bool awaiting_ = true, swallow; //transmit runner only; Close() runs while no runner is active
                private long asked_at = NONE;           //the journal position the last ask for an acknowledgement went out at, NONE once answered
                private uint time_;                     //the time header of this pull's marked packs, stamped once per pull
                private uint asked_time;                //the time the last ask went out at
                private bool pulling;                   //inside src_.Read()
                //Who pulls the transmitter. OFFLINE (parked) — no socket: the application thread that queues a pack pulls it
                //straight into the journal, see wake()/drain(). ONLINE — the transmit runner pulls, see Read(). The switch
                //is thrown by online() from resume(connection) and back by Close() while the session is kept. `draining`
                //is the drain's eventcount: 0 idle, the increment 0→1 owns the drain; online() waits for it to reach 0.
                private volatile bool parked_ = true, closing;
                private int draining;
                //What the receive thread posts for the runner. `posted` is the only word the runner reads per pull; the
                //commands themselves are exchanged only once it is set, so a pull that has nothing to apply costs one
                //volatile read.
                private volatile bool posted, post_swallow;
                private long cmd_resume = NONE, cmd_ack = NONE;
                private long resume_at = NONE; //the position the peer named, waiting for a pack boundary
                private long replaying = NONE; //where the replay in progress started, NONE while none is
                private IOException? failure;  //set by fail(), thrown by the Read() in progress

                private const long NONE = -1;

                ///<param name="capacity">the largest backlog held, in bytes.</param>
                public Resumable(long capacity)
                {
                    if (1L << 31 < capacity)
                        throw new ArgumentOutOfRangeException(nameof(capacity), capacity, "The positions of a session must stay within a signed 32-bit offset of each other");
                    this.capacity = capacity;
                    this.segment = SEGMENT;
                    hot_time = seconds() & TIME_MASK;
                }

                ///<summary>
                ///Binds the stage to the transmitter it reads from. The positions and the journal survive the call,
                ///so the generated <c>Init()</c> re-binds on every connect without losing the backlog.
                ///</summary>
                public Resumable Init_(Transmitter src_)
                {
                    this.src_ = src_;
                    return this;
                }

                private void wakeRunner() => src_?.ext_connection?.WakeTransmit();

                ///<summary>
                ///A pack was queued on the transmitter: hands it to whoever pulls — the transmit runner while ONLINE, or this
                ///very thread while OFFLINE, which then journals every pack the queue holds. Called by the generated
                ///<c>sending_put0</c> on the queue's empty → non-empty edge, in place of <see cref="External.WakeTransmit"/>.
                ///</summary>
                public void wake()
                {
                    if (parked_)
                        drain();
                    else
                        wakeRunner();
                }

                ///<summary>
                ///ONLINE: the transmit runner owns the transmitter from here on. Called by the generated
                ///<c>resume(connection)</c> — on the thread the transport connects the session on, before it hands the
                ///connection a transmit buffer — after <c>ext_connection</c> has been set. Waits for an offline pull in
                ///progress to finish its pack, so the runner finds the transmitter free.
                ///</summary>
                public void online()
                {
                    parked_ = false;
                    var spin = new SpinWait();
                    while (Volatile.Read(ref draining) != 0)
                        spin.SpinOnce();
                }

                private void drain()
                {
                    if (Interlocked.Increment(ref draining) != 1)
                        return; //the drain in progress sees the count changed and pulls again
                    drain_();
                }

                ///<summary>
                ///Owns <see cref="draining"/>: runs a deferred <see cref="Close"/>, then journals the queue while OFFLINE — one
                ///pack per pull, so <see cref="online"/> never waits for more — until the count it saw is released. A pack
                ///queued meanwhile bumped the count: the release fails and the loop pulls again.
                ///</summary>
                private void drain_()
                {
                    for (;;)
                    {
                        var seen = Volatile.Read(ref draining); //what was posted before this read is served by this pass; a later post fails the release below
                        try
                        {
                            if (closing)
                            {
                                closing = false;
                                close_();
                            }
                            while (parked_ && src_ != null && journal())
                                ;
                        }
                        catch (IOException e)
                        {
                            Transmitter.error_handler.error(src_, null, OnError.ERROR, e);
                        }
                        if (Interlocked.CompareExchange(ref draining, 0, seen) == seen)
                            break;
                    }
                    if (!parked_)
                        wakeRunner(); //went ONLINE under us: what is queued is the runner's now
                }

                ///<summary>
                ///One offline pull: the transmitter serializes straight into the free tail of <see cref="hot"/>;
                ///<see cref="packEnd"/> commits the marked pack in place, unmarked bytes are left uncommitted and overwritten
                ///by the next pull. The generated <c>_OnSerializing</c> skips unmarked packs while <see cref="Transmitter.journal_only"/>.
                ///</summary>
                ///<returns><c>false</c> when the transmitter is dry or the journal is at <see cref="capacity"/>.</returns>
                private bool journal()
                {
                    time_ = stamp();
                    var free = capacity - (next_ - base_);
                    if (free < ROOM)
                        return false;
                    if (HOT - hot_len < ROOM)
                        flush();
                    var start = hot_len;
                    var room = (int)Math.Min(HOT - start, free);
                    if (open)
                        mark = start; //the pack parked mid-serialization continues here
                    src_!.journal_only = true;
                    try
                    {
                        var n = src_.Read(hot, start, room);
                        if (open && 0 < n)
                            append(hot, mark, start + n - mark); //the part of the open pack this pull produced, committed in place
                        if (failure != null)
                            throw takeFailure();
                        publish();
                        return 0 < n;
                    }
                    finally
                    {
                        src_.journal_only = false;
                    }
                }

                ///<summary>The position of the first byte in <see cref="hot"/>: past every file, the last one as far as it is written.</summary>
                private long hotBase() => files.Count == 0 ? base_ : base_ + (files.Count - 1) * (long)segment + written;

                ///<summary>Stops the pull in progress right where the transmitter is: it sees no room left and returns.</summary>
                private void cut()
                {
                    var src_ = this.src_!;
                    src_.byte_max = src_.byte_;
                }

                ///<summary>
                ///Snapshots what the receive thread reads in <see cref="resume"/> and <see cref="ack"/>. Once per pull, and
                ///only the words that changed.
                ///</summary>
                private void publish()
                {
                    if (base_pub != base_)
                        Volatile.Write(ref base_pub, base_);
                    if (next_pub != next_)
                        Volatile.Write(ref next_pub, next_);
                    var b = open ? open_start : next_;
                    if (boundary_pub != b)
                        Volatile.Write(ref boundary_pub, b);
                    var t = baseTime();
                    if (base_time_pub != t)
                        Volatile.Write(ref base_time_pub, t);
                }

                ///<summary>
                ///Marks the start of a pack to journal. Called by the generated <c>_OnSerializing</c> before the pack
                ///id is written.
                ///</summary>
                ///<returns>The pack's stream position — the value of its <c>pos</c> header; its <c>time</c> header is <see cref="time()"/>.</returns>
                public int packStart()
                {
                    if (src_ == null)
                        return 0;
                    if (src_.journal_only)
                        src_.byte_ = hot_len; //an offline pull: whatever an unmarked pack left uncommitted is overwritten
                    open = true;
                    mark = src_.byte_;
                    open_start = next_;
                    boundary(next_);
                    return (int)next_;
                }

                ///<summary>
                ///Marks the end of the pack started by <see cref="packStart"/> and copies its bytes into the journal.
                ///Called by the generated <c>_OnSerialized</c>.
                ///</summary>
                public bool packEnd()
                {
                    if (!open)
                        return false;
                    open = false;
                    var src_ = this.src_!;
                    append(src_.buffer!, mark, src_.byte_ - mark);
                    if (swallow || awaiting_ || resume_at != NONE)
                        cut(); //one marked pack per pull, at its end: Read() drops it from the buffer, or switches to the journal there
                    var half = segment >> 1;
                    if (next_ <= acked_ || next_ - acked_ < half && since(time_, baseTime()) < ASK_SECONDS)
                        return false;
                    if (asked_at != NONE && next_ - asked_at < half && since(time_, asked_time) < ASK_SECONDS)
                        return false; //an ask is out, and neither much nor long ago
                    asked_at = next_;
                    asked_time = time_;
                    return true;
                }

                ///<summary>The <c>time</c> header of the marked packs of this pull: the low <see cref="TIME_BITS"/> of the unix seconds it started at.</summary>
                public uint time => time_;
#region datagram transport
                //Over a stream a lost byte takes the connection with it; over datagrams it is lost alone, and what arrives after
                //it can be parsed only from the start of a pack. So the stage says where the first pack in the bytes of each
                //Read starts, for fresh packs from the transmitter and for replayed ones from the journal's own record of starts.
                //And a datagram transport has what a stream does not: a timer, with which it asks again for an acknowledgement
                //that did not come - see probe(). All of it runs on the transmit runner, as the positions do.

                ///<summary>Where the journalled packs start, oldest first: a ring, trimmed as <see cref="base_"/> moves up.</summary>
                private long[] starts = new long[64];

                private int starts_head, starts_n;

                private void boundary(long at)
                {
                    if (starts_n == starts.Length)
                    {
                        var grown = new long[starts.Length * 2];
                        for (var i = 0; i < starts_n; i++)
                            grown[i] = starts[starts_head + i & starts.Length - 1];
                        starts = grown;
                        starts_head = 0;
                    }
                    starts[starts_head + starts_n++ & starts.Length - 1] = at;
                }

                private void trimStarts()
                {
                    while (0 < starts_n && starts[starts_head] < base_)
                    {
                        starts_head = starts_head + 1 & starts.Length - 1;
                        starts_n--;
                    }
                }

                ///<summary>The first recorded start in [<paramref name="from"/>, <paramref name="to"/>), or -1.</summary>
                private long startIn(long from, long to)
                {
                    int lo = 0, hi = starts_n;
                    while (lo < hi)
                    {
                        var mid = lo + hi >> 1;
                        if (starts[starts_head + mid & starts.Length - 1] < from)
                            lo = mid + 1;
                        else
                            hi = mid;
                    }
                    if (lo == starts_n)
                        return -1;
                    var s = starts[starts_head + lo & starts.Length - 1];
                    return s < to ? s : -1;
                }

                ///<summary>
                ///Where the first pack that starts in the bytes of the last <see cref="Read"/> begins, as an index into its
                ///<c>dst</c>; <c>-1</c> - none starts there. A value at or past the end of what Read returned means none as well.
                ///</summary>
                public int first { get; private set; } = -1;

                ///<summary>The four positions, for the transport that runs this stage: acknowledged, handed out, produced, asked about.</summary>
                public long acked => acked_;

                public long sent => sent_;
                public long next => next_;

                ///<summary>How many replays began, and how many bytes they sent: a measure of what the losses cost.</summary>
                public long replays, replayed;

                ///<summary>For a log line: the positions, relative to <see cref="base_"/>, and the state.</summary>
                public override string ToString() => $"replays={replays}/{replayed}B journal base={base_} acked=+{acked_ - base_} sent=+{sent_ - base_} next=+{next_ - base_} asked={(asked_at < 0 ? "-" : "+" + (asked_at - base_))}{(parked_ ? " OFFLINE" : "")}{(awaiting_ ? " awaiting" : "")}{(swallow ? " swallow" : "")}{(resume_at != NONE ? " resume_at=" + resume_at : "")}{(posted ? " posted" : "")}";

                ///<summary>The position the last ask for an acknowledgement went out at: what the generated code puts in <c>Ask_</c>.</summary>
                public long asked => asked_at;

                ///<summary>Queues an <c>Ask_</c> - set by the generated connection, called by <see cref="probe"/>; <c>false</c> - the
                ///transmitter queue is full, nothing was queued.</summary>
                public Func<bool>? asker;

                ///<summary>
                ///The transport's timer ran out with bytes unacknowledged: the ask that should have answered for them, or the
                ///answer, is lost - or the last packs are, and nothing behind them can show the gap. Asks again, at the current
                ///position; the receiver answers with <c>Ack_</c>, and with <c>Resume_</c> when it has not got that far.
                ///</summary>
                ///<returns><c>false</c> when no ask was queued: everything is acknowledged, nobody can send it, or the queue is full -
                ///then the ask is not counted as out.</returns>
                public bool probe()
                {
                    if (asker == null || next_ <= acked_)
                        return false;
                    long at = asked_at;
                    var t = asked_time;
                    asked_at = next_;
                    asked_time = stamp();
                    if (asker())
                        return true;
                    asked_at = at;
                    asked_time = t;
                    return false;
                }

                ///<summary>Where the journal bytes the last <see cref="Read"/> returned begin: it returned journal bytes when <see cref="sent"/> is past it.</summary>
                public long readAt { get; private set; }

                ///<summary>
                ///The transport took the bytes it sent from <paramref name="pos"/> on for lost: the stream goes back to the pack
                ///that holds <paramref name="pos"/>, at the next pack boundary - as the peer's <c>Resume_</c> would make it, but
                ///without the round trip, and without depending on the <c>Resume_</c> arriving. Packs the peer has already are
                ///dropped by it as duplicates. On the transmit runner.
                ///</summary>
                ///<returns>The position the stream goes back to, or -1 - nothing to go back to.</returns>
                public long rewind(long pos)
                {
                    if (swallow || awaiting_ || post_swallow || parked_ || src_ == null || pos < acked_ || sent_ <= pos)
                        return -1;
                    var at = Math.Max(acked_, startAtOrBelow(pos));
                    if (resume_at == NONE || at < resume_at)
                        resume_at = at;
                    return at;
                }

                ///<summary>The last recorded pack start at or below <paramref name="pos"/>; <see cref="NONE"/> when none is held.</summary>
                private long startAtOrBelow(long pos)
                {
                    int lo = 0, hi = starts_n;
                    while (lo < hi)
                    {
                        var mid = lo + hi >> 1;
                        if (starts[starts_head + mid & starts.Length - 1] <= pos)
                            lo = mid + 1;
                        else
                            hi = mid;
                    }
                    return lo == 0 ? NONE : starts[starts_head + lo - 1 & starts.Length - 1];
                }
#endregion

                ///<summary>Nobody to wait for: the stream continues from the current position, as if the peer had named it.</summary>
                public void resume()
                {
                    Volatile.Write(ref cmd_resume, Volatile.Read(ref next_pub));
                    posted = true;
                    wakeRunner();
                }

                ///<summary>
                ///The peer names the position it wants the stream continued from: the one just past the last pack it committed,
                ///with the <c>time</c> that pack was sent at. Applied by the transport thread at the next pack boundary its
                ///<see cref="Read"/> reaches - so that the stream switches to the journal between two packs, never inside one -
                ///which this call wakes.
                ///</summary>
                ///<returns>
                ///-1 when the journal holds the position and the stream continues from it. Otherwise the <c>pos</c> the peer has
                ///to be told, with <see cref="time()"/> — <see cref="base_"/> when the position is below the journal or of an
                ///earlier session, the start of the pack in progress, or <see cref="next_"/>, when it is above. Until then nothing marked leaves the stage: marked
                ///packs the transmitter produces are journalled only, and the caller announces the returned position with an
                ///unmarked pack and, once that pack has been serialized, calls <c>resume</c> with the position.
                ///</returns>
                public long resume(uint time, int pos)
                {
                    long lo = Volatile.Read(ref base_pub), hi = Volatile.Read(ref next_pub);
                    var at = hi + (pos - (int)hi);
                    var held = -1 <= since(time, Volatile.Read(ref base_time_pub)) && lo <= at && at <= hi;
                    if (held)
                        Volatile.Write(ref cmd_resume, at);
                    else
                        post_swallow = true;
                    posted = true;
                    wakeRunner();
                    return held ? -1 : hi < at ? (uint)Volatile.Read(ref boundary_pub)
                                               : (uint)lo;
                }

                ///<summary>
                ///The peer has committed everything below the position, with the <c>time</c> the pack there was sent at. Applied
                ///by the transport thread at its next <see cref="Read"/>, which this call wakes; the files entirely below the
                ///position are deleted there. A position of an earlier session is ignored.
                ///</summary>
                public void ack(uint time, int pos)
                {
                    if (since(time, Volatile.Read(ref base_time_pub)) < -1)
                        return;
                    var hi = Volatile.Read(ref next_pub);
                    var at = hi + (pos - (int)hi);
                    for (var cur = Volatile.Read(ref cmd_ack); cur < at; cur = Volatile.Read(ref cmd_ack))
                        if (Interlocked.CompareExchange(ref cmd_ack, at, cur) == cur)
                            break;
                    posted = true;
                    wakeRunner();
                }

                public bool isOpen()
                {
                    var src_ = this.src_;
                    return src_ != null && src_.isOpen();
                }

                ///<summary>
                ///A parked connection (<see cref="External.parked"/> &gt;= 0) keeps the journal and every unacknowledged
                ///byte: <see cref="sent_"/> rewinds to <see cref="acked_"/> and the stage waits for the peer to name its
                ///position on reconnect, while the transmitter below is left untouched so the journal can replay what it
                ///produced. A connection that is not parked ends the session: the journal is dropped, the positions
                ///re-seeded, and the close goes on to the transmitter.
                ///</summary>
                public void Close()
                {
                    closing = true;
                    if (Interlocked.Increment(ref draining) != 1)
                        return; //the offline pull in progress closes when its pack is done
                    drain_();
                }

                ///<summary>
                ///The close itself, under <see cref="draining"/>: no runner is alive (the transport closes the codecs once
                ///every operation has reported) and no offline pull is. Either way the stage goes OFFLINE: the runner is
                ///gone, and the next <see cref="online"/> comes with the socket the session continues on.
                ///</summary>
                private void close_()
                {
                    var src_ = this.src_;
                    if (src_ == null)
                        return;
                    parked_ = true;
                    awaiting_ = true;
                    swallow = false;
                    asked_at = NONE;
                    sent_ = acked_;
                    resume_at = replaying = NONE;
                    Volatile.Write(ref cmd_resume, NONE);
                    closeReplay();
                    var ext = src_.ext_connection;
                    if (ext != null && 0 <= ext.parked)
                        return;
                    this.src_ = null;
                    drop();
                    publish();
                    src_.Close();
                }

                ///<summary>
                ///Serves the replay backlog <c>[sent, next)</c> first. Only when it is empty does it pull fresh bytes
                ///from the transmitter, with the room limited to what is left under <see cref="capacity"/>, and journal
                ///the packs the generated code marks on the way past.
                ///</summary>
                ///<returns>
                ///Bytes written; 0 at the cap or when the transmitter made no progress; -1 when the session is over or
                ///the transmitter is dry.
                ///</returns>
                ///<exception cref="IOException">
                ///The failure that ended the session — the journal is already gone and the socket aborted by then.
                ///</exception>
                public int Read(byte[] dst, int dst_byte, int dst_bytes)
                {
                    first = -1;
                    try
                    {
                        return read_(dst, dst_byte, dst_bytes);
                    }
                    finally
                    {
                        publish();
                    }
                }

                private int read_(byte[] dst, int dst_byte, int dst_bytes)
                {
                    if (src_ == null)
                        return -1;
                    time_ = stamp();
                    if (swallow || awaiting_)
                        sent_ = next_; //nothing is replayed until the position the peer named is applied, or the peer has been told it
                    apply();
                    readAt = sent_;
                    if (!(swallow || awaiting_) && sent_ < next_)
                        return replay(dst, dst_byte, dst_bytes);

                    var limit = dst_byte + dst_bytes;
                    for (var pos = dst_byte;;)
                    {
                        var before = next_;
                        var n = pull(dst, pos, limit);
                        if (n < 1)
                            return pos == dst_byte ? n : pos - dst_byte;
                        pos += n;
                        sent_ = next_;
                        if ((swallow || awaiting_) && before < next_)
                            pos = mark; //the marked pack this pull produced is journalled only; it ends the buffer — see packEnd()
                        if (dst_byte < pos)
                            return pos - dst_byte;
                    } //a pull that produced nothing for the wire pulls again: the transmitter has more queued
                }

                ///<summary>
                ///One <c>src_.Read</c> into <c>[pos, limit)</c>, with the room limited to what is left under
                ///<see cref="capacity"/> and the marked bytes it produced journalled.
                ///</summary>
                ///<returns>What the transmitter returned.</returns>
                private int pull(byte[] dst, int pos, int limit)
                {
                    var room = limit - pos;
                    if (!swallow)
                    { //the announcement of a lost position must get out even at the cap
                        var free = capacity - (next_ - base_);
                        if (free < ROOM)
                            return 0; //an ack() wakes the transmit loop
                        if (free < room)
                            room = (int)free;
                    }
                    if (open)
                        mark = pos; //the pack parked mid-serialization continues here
                    pulling = true;
                    int n;
                    try
                    {
                        n = src_!.Read(dst, pos, room);
                    }
                    finally
                    {
                        pulling = false;
                    }
                    if (first < 0 && 0 <= src_!.first_pack)
                        first = src_.first_pack;
                    if (open && 0 < n)
                        append(dst, mark, pos + n - mark); //the part of the open pack this pull produced
                    if (failure != null)
                        throw takeFailure();
                    return n;
                }

                ///<summary>
                ///Applies what <see cref="resume"/> and <see cref="ack"/> posted. A resume waits for a pack boundary: no replay in
                ///progress and no pack mid-serialization in the transmitter; a request for the position the replay in progress
                ///started from is already being served.
                ///</summary>
                private void apply()
                {
                    if (posted)
                    {
                        posted = false; //cleared BEFORE the commands are taken: one posted after this is seen next time
                        var from = Interlocked.Exchange(ref cmd_resume, NONE);
                        if (from != NONE && (from != replaying || sent_ == next_)) //a repeated request is served only while its replay is really under way
                            resume_at = from;
                        var upto = Interlocked.Exchange(ref cmd_ack, NONE);
                        if (upto != NONE)
                        {
                            asked_at = NONE; //the peer answered
                            if (upto > sent_)
                                upto = startAtOrBelow(sent_); //a replay is behind what the peer holds: acked stays on a pack start, where the stream may go back to
                            if (acked_ < upto)
                            {
                                acked_ = upto;
                                release();
                            }
                        }
                    }
                    //The stream switches only between two packs, never inside one - a pack mid-serialization is finished first:
                    //swallowing from the middle of a pack would leave the peer with its head and no tail. A replay under way is
                    //cut at a pack start for a position behind it; one ahead of it the replay reaches anyway.
                    if (sent_ == next_ && !src_!.isOpen())
                    {
                        if (post_swallow)
                        {
                            post_swallow = false;
                            swallow = true;
                            awaiting_ = false;
                            replaying = NONE;
                        }
                    }
                    else if (sent_ < next_ && resume_at != NONE && !post_swallow)
                    {
                        if (sent_ <= resume_at)
                        {
                            resume_at = NONE;
                            return;
                        }
                        if (startIn(sent_, sent_ + 1) != sent_)
                            return; //replay() stops at the next pack start
                    }
                    else
                        return;
                    if (resume_at != NONE)
                    {
                        if (resume_at < base_)
                            resume_at = acked_; //posted before an ack that released it: the peer holds more than it asked for then
                        sent_ = replaying = resume_at;
                        replays++;
                        if (resume_at < acked_)
                            acked_ = resume_at;
                        resume_at = NONE;
                        awaiting_ = false;
                        swallow = false;
                    }
                }

                ///<summary>
                ///Copies journalled bytes from <see cref="sent_"/> into <paramref name="dst"/>: from the file that holds
                ///them, or from the segment in memory.
                ///</summary>
                private int replay(byte[] dst, int dst_byte, int dst_bytes)
                {
                    long p = sent_, hot_base = hotBase();
                    if (resume_at != NONE)
                    { //a switch is waiting for a pack start: the replay stops at the next one
                        var s = startIn(p + 1, p + dst_bytes);
                        if (s != -1)
                            dst_bytes = (int)(s - p);
                    }
                    var n = p < hot_base ? replayFile(dst, dst_byte, dst_bytes, p) : replayHot(dst, dst_byte, dst_bytes, p, hot_base);
                    if (first < 0)
                    {
                        var s = startIn(p, p + n);
                        if (s != -1)
                            first = dst_byte + (int)(s - p);
                    }
                    sent_ = p + n;
                    replayed += n;
                    if (sent_ == next_)
                    {
                        replaying = NONE;
                        closeReplay();
                    }
                    return n;
                }

                private int replayHot(byte[] dst, int dst_byte, int dst_bytes, long p, long hot_base)
                {
                    int off = (int)(p - hot_base), n = Math.Min(dst_bytes, hot_len - off);
                    Array.Copy(hot, off, dst, dst_byte, n);
                    return n;
                }

                private int replayFile(byte[] dst, int dst_byte, int dst_bytes, long p)
                {
                    int index = (int)((p - base_) / segment), off = (int)((p - base_) % segment);
                    var last = index == files.Count - 1;
                    var n = Math.Min(dst_bytes, (last ? written : segment) - off);
                    try
                    {
                        FileStream src;
                        if (last && ch != null)
                            src = ch; //still being written: read it in place
                        else
                        {
                            if (replay_index != index)
                            {
                                closeReplay();
                                replay_ch = new FileStream(files[index], FileMode.Open, FileAccess.Read, FileShare.ReadWrite, 1);
                                replay_index = index;
                            }
                            src = replay_ch!;
                        }
                        for (var got = 0; got < n;)
                        {
                            var r = RandomAccess.Read(src.SafeFileHandle, dst.AsSpan(dst_byte + got, n - got), off + got);
                            if (r < 1)
                                throw new IOException("Journal segment " + files[index] + " is shorter than " + segment + " bytes");
                            got += r;
                        }
                    }
                    catch (Exception e) when (e is IOException or UnauthorizedAccessException)
                    {
                        fail(e as IOException ?? new IOException(e.Message, e));
                        throw takeFailure();
                    }
                    return n;
                }

                ///<summary>
                ///Copies <paramref name="count"/> bytes at <paramref name="offset"/> of <paramref name="buf"/> into the buffer
                ///in memory, writing it out to the segment file whenever it fills. A failed write ends the session — see <see cref="fail"/>.
                ///</summary>
                private void append(byte[] buf, int offset, int count)
                {
                    if (count < 1 || failure != null)
                        return;
                    if (hot_len == 0)
                        hot_time = seconds() & TIME_MASK;
                    if (src_!.journal_only)
                    { //the offline pull serialized into hot itself — see journal() and packStart(): commit in place
                        hot_len += count;
                        next_ += count;
                        return;
                    }
                    try
                    {
                        while (0 < count)
                        {
                            if (hot_len == HOT)
                                flush();
                            var n = Math.Min(HOT - hot_len, count);
                            Array.Copy(buf, offset, hot, hot_len, n);
                            offset += n;
                            hot_len += n;
                            count -= n;
                            next_ += n;
                        }
                    }
                    catch (Exception e) when (e is IOException or UnauthorizedAccessException)
                    {
                        fail(e as IOException ?? new IOException(e.Message, e));
                    }
                }

                ///<summary>Writes the full segment at the head of the buffer in memory to a new file; what lies above it moves down.</summary>
                private void flush()
                {
                    if (ch == null)
                    {
                        var file = Path.Combine(pidDir(), Path.GetRandomFileName() + ".seg");
                        try
                        {
                            ch = new FileStream(file, FileMode.CreateNew, FileAccess.ReadWrite, FileShare.None, 1);
                        }
                        catch (Exception e) when (e is IOException or UnauthorizedAccessException)
                        {
                            delete (file);
                            throw;
                        }
                        files.Add(file);
                        file_times.Add(hot_time);
                        written = 0;
                    }
                    var n = Math.Min(hot_len, segment - written);
                    ch.Write(hot, 0, n);
                    written += n;
                    if (written == segment)
                    {
                        ch.Dispose();
                        ch = null;
                    }
                    hot_len -= n;
                    if (0 < hot_len)
                        Array.Copy(hot, n, hot, 0, hot_len);
                    hot_time = seconds() & TIME_MASK;
                }

                ///<summary>Lets go of everything held: the files, the file being written, the buffer in memory.</summary>
                private void discard()
                {
                    closeReplay();
                    if (ch != null)
                    {
                        try
                        {
                            ch.Dispose();
                        }
                        catch (IOException)
                        {
                        }
                        ch = null;
                    }
                    foreach (var f in files)
                        delete (f);
                    files.Clear();
                    file_times.Clear();
                    written = 0;
                    hot_len = 0;
                    hot_time = seconds() & TIME_MASK;
                }

                ///<summary>
                ///Gives back what lies below <see cref="acked_"/>: the files entirely below it, then — once no file is left —
                ///the acknowledged head of the buffer in memory, the whole buffer when everything is acknowledged.
                ///<see cref="base_"/> moves up to the first byte kept.
                ///</summary>
                private void release()
                {
                    if (acked_ == next_)
                    { //everything is acknowledged: hold nothing
                        discard();
                        base_ = next_;
                        trimStarts();
                        return;
                    }
                    while (0 < files.Count && (ch == null || 1 < files.Count) && base_ + segment <= acked_)
                    { //the full files below the acknowledged position; the one still being written stays
                        if (replay_index == 0)
                            closeReplay(); //an open file cannot be deleted on Windows
                        delete (files[0]);
                        files.RemoveAt(0);
                        file_times.RemoveAt(0);
                        base_ += segment;
                        if (0 < replay_index)
                            replay_index--;
                    }
                    trimStarts();
                    if (0 < files.Count || acked_ <= base_)
                        return;
                    var drop = (int)(acked_ - base_);
                    hot_len -= drop;
                    Array.Copy(hot, drop, hot, 0, hot_len);
                    base_ = acked_;
                    trimStarts();
                }

                private void closeReplay()
                {
                    if (replay_ch == null)
                        return;
                    try
                    {
                        replay_ch.Dispose();
                    }
                    catch (IOException)
                    {
                    }
                    replay_ch = null;
                    replay_index = -1;
                }

                ///<summary>Empties the journal; the offsets go on above everything the peer may hold of this session.</summary>
                private void drop()
                {
                    discard();
                    open = false;
                    base_ = acked_ = sent_ = next_ = next_ + 1;
                    starts_n = 0;
                }

                ///<summary>
                ///Ends the session on a failed file operation: the journal is emptied, the positions are re-seeded and
                ///the socket is aborted, so the peer reconnects and is told that its position is gone. The exception is
                ///thrown by the <see cref="Read"/> in progress.
                ///</summary>
                private void fail(IOException e)
                {
                    failure ??= e;
                    drop();
                    src_?.ext_connection?.Abort();
                }

                private IOException takeFailure()
                {
                    var e = failure!;
                    failure = null;
                    return e;
                }
            }

            ///<summary>
            ///One frame on the serialization stack — the transmit-side mirror of <see cref="Receiver.Slot"/>. Each
            ///nested pack/collection being written gets its own slot; the slots form a reused doubly-linked chain
            ///(<see cref="prev"/>/<see cref="next"/>) so the transmitter can descend and pop without per-pack
            ///allocation. A slot carries the in-progress <see cref="src"/> source, the resume <c>state</c>, and the
            ///<see cref="fields_nulls"/> null-field bitmap for its level.
            ///</summary>
            internal sealed class Slot : Base_.Transmitter.Slot
            {

                ///<summary>
                ///The packet/field source currently producing bytes at this nesting level.
                ///</summary>
                internal BytesSrc src;

                public BytesSrc src_(BytesSrc src)
                {
                    state = 1; //Start at state 1: state 0 emits the [Pack id] header, which the nested src skips
                    return this.src = src;
                }

                ///<summary>
                ///Bitmap of which optional fields at this level are present, emitted up front so the reader can skip
                ///absent ones. See <c>init_fields_nulls</c>/<c>flush_fields_nulls</c>.
                ///</summary>
                internal int fields_nulls;

                internal Slot? next;
                internal readonly Slot? prev;

                ///<summary>
                ///Initializes a new instance of the <see cref="Slot"/> class.
                ///</summary>
                ///<param name="src">The `Transmitter` associated with this slot chain.</param>
                ///<param name="prev">The previous slot in the chain, or null if this is the root slot.</param>
                public Slot(Transmitter src, Slot? prev) : base(src)
                {
                    this.prev = prev;
                    if (prev != null)
                        prev.next = this;
                }
            }

            ///<summary>Root of the slot chain — see <see cref="Receiver.root"/>.</summary>
            internal readonly Slot root;
            internal Slot? slot;
            internal Slot? streaming_slot; //completion boundary for Read
            internal uint streaming_mode;  //the pre-park mode saved on entering STREAM_PACK

            ///<summary>
            ///<c>true</c> while the <see cref="Resumable"/> stage pulls with no socket: only marked packs are wanted, the
            ///generated <c>_OnSerializing</c> skips the rest.
            ///</summary>
            public bool journal_only;

            ///<summary>
            ///Where the first pack that STARTED in the last <see cref="Read"/> begins, as an index into its <c>dst</c>; <c>-1</c>
            ///- none started there, the bytes all continue a pack. A datagram transport sends it along: a receiver that lost
            ///the datagram before resumes parsing there. One compare per pack.
            ///</summary>
            public int first_pack = -1;

            ///<summary>
            ///Resumes the stream parked in STREAM_PACK mode and tells how it went. Negative: still parked, more bytes
            ///needed. 0: the stream ended and the pack around it goes on. Positive: the stream was the packet itself
            ///(its slot is the root), which is now complete - it is sent. Only the generated chain knows which: the answer is
            ///the slot of the stream it drives, neither the current <c>slot</c> (where the pack inside the stream
            ///stopped) nor <c>streaming_slot</c> (the innermost of nested streams, while the outer one is what ends here).
            ///</summary>
            public virtual int unpark() => 1;
#endregion

            ///<summary>
            ///Initializes the `fields_nulls` bitmask in the current slot with a starting bit.
            ///Also allocates 1 byte in the buffer for storing this bitmask later via `flush_fields_nulls`.
            ///</summary>
            ///<param name="field0_bit">The initial bit value for the nulls bitmask (e.g., representing the first field).</param>
            ///<param name="this_case">The state to retry at if buffer allocation fails.</param>
            ///<returns>True if allocation is successful and bitmask initialized; false if a retry is needed.</returns>
            public bool init_fields_nulls(int field0_bit, uint this_case)
            {
                if (!Allocate(1, this_case))
                    return false;
                slot!.fields_nulls = field0_bit;
                return true;
            }

            ///<summary>
            ///Sets a specific bit in the `fields_nulls` bitmask of the current slot.
            ///This is used to mark a field as non-null (by convention, a set bit means non-null).
            ///</summary>
            ///<param name="field">The bit corresponding to the field to mark (e.g., a power of 2).</param>
            public void set_fields_nulls(int field) => slot!.fields_nulls |= field;

            ///<summary>
            ///Writes the `fields_nulls` bitmask from the current slot as a single byte into the buffer.
            ///Assumes space was previously allocated by `init_fields_nulls`.
            ///</summary>
            public void flush_fields_nulls() => put((byte)slot!.fields_nulls);

            ///<summary>
            ///Checks if a specific field is marked as null based on the `fields_nulls` bitmask in the current slot.
            ///</summary>
            ///<param name="field">The bit representing the field to check (e.g., a power of 2).</param>
            ///<returns>True if the field's corresponding bit is NOT set in `fields_nulls` (meaning it is null, by convention where 0 means null); false otherwise.</returns>
            public bool is_null(int field) => (slot!.fields_nulls & field) == 0;

            public bool isOpen() => slot?.src != null; //a packet is being serialized right now

            ///<summary>
            ///Ends the session: leaves nothing of the connection that just died behind — neither the string staged
            ///for a stream, nor the generator's registers, which on this side alias the application's pack data.
            ///Runs unconditionally, like <see cref="Receiver.Close"/>.
            ///</summary>
            public virtual void Close()
            {
                drop();
                clear(); //Generator-emitted registers
                for (var s = root; s != null; s = s.next)
                    s.clear();
            }

            ///<summary>
            ///Drops the pack in flight, and only it: the queue behind it stays, and so does the session. For a connection
            ///that outlives its link — a virtual one, whose tunnel packet died with the physical link. No-op between packs.
            ///<para>
            ///Why drop rather than continue or replay: the peer has already thrown away the part it received (its
            ///<see cref="Receiver.Abandon"/> runs when its link dies, or when the relay ends the packet with
            ///<see cref="Chunked.ABORT"/>), so it expects a pack id next. Continuing would hand it the tail of this pack as
            ///if it were the start of a new one. Replaying is impossible: serialization reads the application's live
            ///objects and is not rewindable, and keeping a copy of every pack until the far end has it is what the journal
            ///does for guaranteed packs — a tunnel carries none. So the pack is lost, as a datagram would be.
            ///</para>
            ///<para>Overridden by the generated transmitter to also release the queue entry the pack came from
            ///(<c>sending_out</c>), which only it knows.</para>
            ///</summary>
            public virtual void Abandon()
            {
                if (isOpen())
                    drop();
            }

            ///<summary>What <see cref="Close"/> and <see cref="Abandon"/> share: forget the pack in flight and every
            ///per-pack register.</summary>
            void drop()
            {
                reset();

                if (bytesCopy != null)
                {
                    bytesCopy.fail(this);
                    bytesCopy = null;
                }

                mode = OK;
                u4 = 0;
                bytes_left = 0;
                buffer = null;
                str = null;  //A string abandoned mid-stream, up to STR_LEN_MAX chars
                strs = null; //Drop a string-fragment supplier abandoned mid-transfer

                streaming_slot = null;
                streaming_mode = OK;
            }

            ///<summary>
            ///Rewinds the packet in flight and releases the borrowed buffer. Error and session path.
            ///<para>Overridable: a generated streaming transmitter overrides it to release its active chain first,
            ///then calls <c>base.reset()</c>.</para>
            ///</summary>
            protected virtual void reset()
            {
                if (slot == null)
                    return;
                if (bytesCopy != null)
                {
                    bytesCopy.fail(this);
                    bytesCopy = null;
                }

                for (var s = slot; s != null; s = s.next)
                    s.src = null;
                slot = null;
                buffer = null;
                mode = OK;
            }

            ///<summary>
            ///Defines an interface for intercepting raw bytes from the stream as they are generated by the <see cref="Transmitter"/>.
            ///<para>
            ///This is primarily used for logging outgoing traffic, calculating checksums on the fly, or mirroring the output stream.
            ///</para>
            ///</summary>
            public interface BytesCopy : Broadcastable
            {
                ///<summary>
                ///Called when the <see cref="Transmitter.Read"/> method is about to return because the destination buffer is full,
                ///but the packet is not yet fully serialized.
                ///This provides a chunk of raw bytes that have been generated so far.
                ///</summary>
                ///<param name="t">The transmitter instance.</param>
                ///<param name="offset">The offset in the provided destination buffer where this chunk starts.</param>
                ///<param name="count">The number of bytes in this chunk.</param>
                void pass(Transmitter t, int offset, int count);

                ///<summary>
                ///Called when the packet has fully serialized.
                ///This provides the final chunk of raw bytes for the packet.
                ///After this call, the <see cref="Transmitter.bytesCopy"/> is automatically cleared (set to null).
                ///</summary>
                ///<param name="t">The transmitter instance.</param>
                ///<param name="offset">The offset in the provided destination buffer where this chunk starts.</param>
                ///<param name="count">The number of bytes in this chunk.</param>
                void done(Transmitter t, int offset, int count);

                ///<summary>
                ///Called if the transmitter is reset (due to error or connection close) before the packet completes serialization.
                ///Implementations should discard any partially captured data.
                ///After this call, the <see cref="Transmitter.bytesCopy"/> is automatically cleared.
                ///</summary>
                ///<param name="t">The transmitter instance.</param>
                void fail(Transmitter t);
            }

            ///<summary>
            ///The active read hook. Set this property to capture raw bytes for the *current* packet being serialized.
            ///<para>
            ///<b>Lifecycle:</b><br/>
            ///1. Assign this field inside <see cref="EventsHandler.OnSerializing"/>.<br/>
            ///2. The hook receives data via <see cref="BytesCopy.pass"/> (partial) or <see cref="BytesCopy.done"/> (final).<br/>
            ///3. Upon <see cref="BytesCopy.done"/> or <see cref="BytesCopy.fail"/>, this field is automatically reset to <c>null</c>.
            ///</para>
            ///<para>
            ///<b>Note on Packet IDs:</b><br/>
            ///Unlike the Receiver, if you set this hook within <see cref="EventsHandler.OnSerializing"/>, it <b>will</b>
            ///capture the Packet ID bytes, because the Transmitter generates the ID immediately <i>after</i> the event is fired.
            ///</para>
            ///</summary>
            public BytesCopy? bytesCopy;

            ///<summary>
            ///Main outbound entry point: serialize queued packs into <paramref name="dst"/> until it is full or the
            ///send queue drains. Dequeues the next pack when starting fresh, emits its ID then body, resumes any
            ///value parked by an earlier call (per <see cref="mode"/>), and fires <c>OnSerializing</c>/<c>OnSerialized</c>
            ///as packs begin and finish. A pack whose serialization overruns <paramref name="dst"/> simply parks and
            ///continues on the next call. This is the core of the <see cref="BytesSrc"/> implementation for <see cref="Transmitter"/>.
            ///</summary>
            ///<param name="dst">The destination byte array where serialized data will be written.</param>
            ///<param name="dst_byte">The starting offset in `dst`.</param>
            ///<param name="dst_bytes">The maximum number of bytes to write into `dst`.</param>
            ///<returns>
            ///The number of bytes written to `dst`.
            ///Returns 0 if `dst` has insufficient space to write even a part of the next packet segment.
            ///Returns -1 if there are no more packets in the sending queue to process.
            ///Returns int.MinValue if a streaming source completes serialization.
            ///</returns>
            public int Read(byte[] dst, int dst_byte, int dst_bytes)
            {
                var bytesCopyOffset = dst_byte;
                first_pack = -1;
                for (buffer = dst, byte_max = (byte_ = dst_byte) + dst_bytes; byte_ < byte_max;)
                {
                    if (slot?.src == null)
                    {
                        //A value pack carries its payload in u8 — the party that queues it stages the value
                        //there (the generated DataPass.OnSerializing does), so there is nothing to arm here.
                        var src = _OnSerializing(); //Get next BytesSrc from sending queue

                        if (src == null)
                            goto exit; //Send queue drained. Not an error and not the end of the session, so
                                       //nothing is torn down here: reset() is where the generated override
                                       //releases the stream chain, and that chain has to survive between
                                       //drains (it is released in Close(), or when it is evicted).

                        if (slot == null)
                            slot = root;

                        stream_byte = 0; //Byte cursor of the raw-copy sources (BytesCopy.InMemory)
                        slot.src = src;
                        slot.state = 0; //write id request
                        bytesCopyOffset = byte_;
                        if (first_pack < 0)
                            first_pack = byte_;
                        handler?.OnSerializing(this, src);
                        if (slot == null)
                            return -1; //sending event handler has reset this
                    }
                    else
                        switch (mode) //the packet transmission was interrupted, recall where we stopped
                        {
                            case STREAM_PACK:
                            {
                                mode = streaming_mode;
                                var done = unpark();
                                if (done < 0)
                                    goto exit;
                                if (0 < done)
                                    goto dispatched;
                                break;
                            }
                            case STR:
                                if (slot.state == (uint)bit)
                                    break;

                                if (!varint())
                                    goto exit;

                                if (u4 == uint.MaxValue)
                                    u4 = 0;

                                while (u4 < str!.Length)
                                    if (!varint(str[(int)u4++]))
                                        goto exit;

                                str = null;
                                break;
                            case STR_UTF8:
                                //Chain-string leaf park (see UTFStream) → SKIP, the leaf completes it.
                                if (slot.state == (uint)bit)
                                    break;

                                //No length prefix on this wire — a park always stages char-phase state
                                //(split-sequence bytes in u8_ / bytes_left), which putting_utf resumes itself.
                                if (!putting_utf())
                                    goto exit;
                                break; //putting_utf cleared str
                            case VAL4:
                                if (byte_max - byte_ < bytes_left)
                                    goto exit;
                                put_val(u4, bytes_left);
                                break;
                            case VAL8:
                                if (byte_max - byte_ < bytes_left)
                                    goto exit;
                                put_val(u8, bytes_left);
                                break;
                            case BITS_BYTES:
                                if (byte_max - byte_ < bits_transaction_bytes_)
                                    goto exit;     //space for one full transaction
                                bits_byte = byte_; //preserve space for bits info
                                byte_++;
                                put_val(u8, bytes_left);
                                break;
                            case VARINT:
                                if (varint())
                                    break;
                                goto exit;
                            case BITS:
                                if (byte_max - byte_ < bits_transaction_bytes_)
                                    goto exit;     //space for one full transaction
                                bits_byte = byte_; //preserve space for bits info
                                byte_++;
                                break;
                        }

                    mode = OK; //Restore mode to OK after resuming transmission

                    //Get bytes from byte source and put into buffer
                    for (;;)
                        if (slot!.src!.__get_bytes(this))
                        {
                            if (slot == streaming_slot)
                                return int.MinValue; //streamed body complete → hand control back to the re-entrant caller (Adapter); the framer's [0] finishes the stream
                            if (slot.prev == null)
                                break;        //top-level packet complete → finish
                            slot = slot.prev; //pop one level
                        }
                        else
                            goto exit;

                dispatched:
                    if (bytesCopy != null)
                    {
                        bytesCopy.done(this, bytesCopyOffset, byte_ - bytesCopyOffset);
                        bytesCopy = null;
                    }
                    _OnSerialized(slot.src);
                    handler?.OnSerialized(this, slot.src);

                    if (slot == null)
                        return -1;   //sent event handler has reset this
                    slot.src = null; //sing of the request next packet
                }

            exit:
                bytesCopy?.pass(this, bytesCopyOffset, byte_ - bytesCopyOffset);
                buffer = null;
                //Nothing written is NOT end-of-stream while a pack is parked mid-serialization (e.g. the next value does not
                //fit the space left): that is 0 = "no progress this call, more to come", exactly as the Java and TS runtimes
                //report it. A caller that distinguishes the two — BytesSrc.Adapter over a tunnel endpoint's transmitter —
                //would otherwise end the chunked tunnel packet mid-pack and strand the rest until an unrelated send.
                return dst_byte < byte_ ? byte_ - dst_byte : slot?.src != null ? 0
                                                                               : -1; //no more packets left
            }

            ///<summary>Re-entrant entry (used by a streaming <see cref="BytesSrc.Adapter"/>): drive Read over the current window; returns <see cref="int.MinValue"/> when the streamed body completes.</summary>
            public int read(byte[] buffer) => Read(buffer, byte_, byte_max - byte_);

            ///<summary>
            ///Checks if a specified number of bytes can be allocated in the current output buffer.
            ///If not, sets the transmitter to retry mode at `this_case`.
            ///</summary>
            ///<param name="bytes">The number of bytes required in the buffer.</param>
            ///<param name="this_case">The state to set for retry if allocation fails due to insufficient space.</param>
            ///<returns>True if `bytes` are available in the remaining buffer; false if not and retry mode is set.</returns>
            public bool Allocate(uint bytes, uint this_case)
            {
                slot!.state = this_case;
                if (bytes <= remaining)
                    return true;
                mode = RETRY;
                return false;
            }

            ///<summary>
            ///Puts a boolean value into the buffer, encoded as a single bit (1 for true, 0 for false),
            ///using the bitwise serialization mechanism.
            ///<para>
            ///Uses <see cref="Unsafe.As{TFrom,TTo}(ref TFrom)"/> to reinterpret the <c>bool</c>'s
            ///single-byte storage directly as a byte, skipping the JIT's defensive <c>cmp; setne; movzx</c>
            ///normalization. Safe because managed C# code always stores <c>bool</c> as exactly 0 or 1.
            ///Benchmarked at ~2x faster than <c>src ? 1 : 0</c> in inlined hot loops on .NET 10 RyuJIT.
            ///</para>
            ///</summary>
            ///<param name="src">The boolean value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(bool src) => put_bits(Unsafe.As<bool, byte>(ref src), 1);

            ///<summary>
            ///Puts a nullable boolean value into the buffer, encoded as two bits:
            ///00 for null, 10 for false, 11 for true.
            ///Uses the bitwise serialization mechanism.
            ///</summary>
            ///<param name="src">The nullable boolean value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(bool? src) => put_bits(src.HasValue ? src.Value ? 3 : //11 binary
                                                                      2
                                                                : //10 binary
                                                       0,
                                                   2); //00 binary
#region bits
            int bits_byte = -1;
            uint bits_transaction_bytes_;

            ///<summary>
            ///Initializes a bitwise transaction, ensuring `transaction_bytes` are available.
            ///This version is typically called to *continue* a bitwise operation after a retry.
            ///</summary>
            ///<param name="transaction_bytes">Minimum number of bytes that should be available in the buffer for this transaction segment.</param>
            ///<param name="this_case">The state to retry at if `transaction_bytes` are not available.</param>
            ///<returns>True if sufficient bytes are available; false if a retry is needed (mode set to BITS).</returns>
            public bool init_bits_(uint transaction_bytes, uint this_case)
            {
                if ((bits_transaction_bytes_ = transaction_bytes) <= byte_max - byte_)
                    return true;
                slot!.state = this_case;
                byte_ = bits_byte; //trim byte at bits_byte index
                mode = BITS;
                return false;
            }

            ///<summary>
            ///Initializes a bitwise transaction. Allocates one byte in the buffer to start accumulating bits
            ///and ensures at least `transaction_bytes` are available for the whole operation.
            ///Resets `bits` accumulator and `bit` pointer.
            ///</summary>
            ///<param name="transaction_bytes">Minimum number of bytes that should be available in the buffer for this transaction. This includes the initial byte allocated here.</param>
            ///<param name="this_case">The state to retry at if `transaction_bytes` are not available.</param>
            ///<returns>True if sufficient bytes are available and bitwise context is initialized; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool init_bits(uint transaction_bytes, uint this_case)
            {
                if (byte_max - byte_ < (bits_transaction_bytes_ = transaction_bytes))
                {
                    slot!.state = this_case;
                    mode = RETRY;
                    return false;
                }

                bits = 0;
                bit = 0;
                bits_byte = byte_++; //Allocate space for the first byte of bits
                return true;
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put_bits(bool src) => put_bits(src ? 1 : 0, 1);

            ///<summary>
            ///Puts a specified number of bits from `src` into the bit accumulator (`bits`).
            ///If the accumulator fills a byte, that byte is written to `buffer[bits_byte]`,
            ///`bits_byte` is advanced, and the accumulator is updated.
            ///</summary>
            ///<param name="src">The integer containing the bits to put (in its lower `len_bits`).</param>
            ///<param name="len_bits">The number of bits from `src` to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put_bits(int src, int len_bits)
            {
                bits |= (uint)src << bit;
                if ((bit += len_bits) < 9)
                    return; //yes 9! not 8!  to avoid allocating the next byte after the current one is full. it might be redundant
                buffer![bits_byte] = (byte)bits;
                bits >>= 8;
                bit -= 8;
                bits_byte = byte_;
                if (byte_ < byte_max)
                    byte_++;
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put_bits(bool src, uint continue_at_case) => put_bits(src ? 1 : 0, 1, continue_at_case);

            ///<summary>
            ///Puts a specified number of bits from `src` into the bit accumulator, with retry capability.
            ///If writing a filled byte requires more buffer space than `bits_transaction_bytes_` allows from current `byte_`,
            ///it sets up a retry.
            ///</summary>
            ///<param name="src">The integer containing the bits to put.</param>
            ///<param name="len_bits">The number of bits from `src` to put.</param>
            ///<param name="continue_at_case">The state to retry at if buffer space runs out.</param>
            ///<returns>True if bits were put successfully (or partially, with more buffer available); false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put_bits(int src, int len_bits, uint continue_at_case)
            {
                bits |= (uint)src << bit;
                if ((bit += len_bits) < 9)
                    return true; //yes 9! not 8!  to avoid allocating the next byte after the current one is full. it might be redundant
                buffer![bits_byte] = (byte)bits;
                bits >>= 8;
                bit -= 8;
                if (byte_max - byte_ < bits_transaction_bytes_)
                {
                    slot!.state = continue_at_case;
                    return false;
                }

                bits_byte = byte_++;
                return true;
            }

            ///<summary>
            ///Finalizes the current bitwise transaction. If any bits are remaining in the `bits` accumulator
            ///(i.e., `0 ᐸ bit`), they are written to `buffer[bits_byte]`. If no bits were written to the
            ///current `bits_byte` (i.e. `bit == 0`), `byte_` is trimmed back to `bits_byte`, effectively
            ///de-allocating the unused byte.
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void end_bits()
            {
                if (0 < bit)
                    buffer![bits_byte] = (byte)bits;
                else
                    byte_ = bits_byte; //trim byte at bits_byte index. allocated, but not used
            }

            ///<summary>
            ///Puts a nulls bitmask using `put_bits`. If `put_bits` requires a retry,
            ///this method sets the mode to `BITS` for continuation.
            ///</summary>
            ///<param name="nulls">The nulls bitmask value.</param>
            ///<param name="nulls_bits">The number of bits in the `nulls` bitmask.</param>
            ///<param name="continue_at_case">The state to retry at if putting bits fails.</param>
            ///<returns>True if the nulls bitmask was put successfully; false if a retry is needed.</returns>
            public bool put_nulls(int nulls, int nulls_bits, uint continue_at_case)
            {
                if (put_bits(nulls, nulls_bits, continue_at_case))
                    return true;

                mode = BITS;
                return false;
            }

            ///<summary>
            ///Sets up a retry for a bitwise operation that was interrupted.
            ///Resets `byte_` to `bits_byte` (start of current bit-holding byte) and sets mode to `BITS`
            ///and state to `continue_at_case`.
            ///</summary>
            ///<param name="continue_at_case">The state to resume the bitwise operation at.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void continue_bits_at(uint continue_at_case)
            {
                slot!.state = continue_at_case;
                byte_ = bits_byte;
                mode = BITS;
            }

            ///<summary>
            ///Items of a bit array straight from its list: while the bit stream stands on a byte boundary, whole chunks -
            ///as many groups of 8 items (<c>bitsPerItem</c> bytes each) as one ulong takes - go to the buffer in one read of
            ///the list and one write. The pending bit byte is written first; a fresh one is reserved after. The items before
            ///the next boundary and the tail go one by one, as before.
            ///</summary>
            ///<returns>The items sent: a multiple of 8, and 0 when the stream is not on a byte boundary.</returns>
            public int put_bits<T>(org.unirail.collections.BitsList<T>.R src, int item, int items)
                where T : struct
            {
                if ((bit & 7) != 0)
                    return 0;
                if (BitConverter.IsLittleEndian) //the list's words are LSB first: its bytes are the wire's - all whole groups in one copy
                {
                    int bl = src.bitsPerItem, pl = bits_flush(), gl = Math.Min(items >> 3, (byte_max - pl) / bl);
                    if (gl != 0)
                        src.Bytes(item, gl << 3).CopyTo(buffer.AsSpan(pl));
                    bits_reserve(pl + gl * bl);
                    return gl << 3;
                }
                int b = src.bitsPerItem, K = 8 / b, pos = bits_flush(), got = 0;
                for (int g; 0 < (g = Math.Min(Math.Min(K, items - got >> 3), (byte_max - pos) / b)); got += g << 3, pos += g * b)
                    store(buffer!, pos, src.Raw(item + got, g << 3), g * b, byte_max);
                bits_reserve(pos);
                return got;
            }

            ///<summary><see cref="put_bits{T}(org.unirail.collections.BitsList{T}.R, int, int)"/> of one-bit items, 64 at a time.</summary>
            public int put_bits(org.unirail.collections.BitList.R src, int item, int items)
            {
                if ((bit & 7) != 0)
                    return 0;
                int pos = bits_flush(), got = 0;
                for (int g; 0 < (g = Math.Min(Math.Min(8, items - got >> 3), byte_max - pos)); got += g << 3, pos += g)
                    store(buffer!, pos, src.Raw(item + got, g << 3), g, byte_max);
                bits_reserve(pos);
                return got;
            }

            int bits8_at; //where the chunk `bits8` made room for goes

            ///<summary>
            ///Room for a chunk of a bit array an abstract pack hands item by item: while the bit stream stands on a byte
            ///boundary, up to <paramref name="items"/> items of <paramref name="bits_per_item"/> bits - as many as one ulong
            ///and the buffer take, whole bytes. The codec packs them into a ulong and writes it at once with <see cref="bits8_put"/>.
            ///</summary>
            ///<returns>The items the chunk takes, 0 when the stream is not on a byte boundary or no chunk fits.</returns>
            public int bits8(int items, int bits_per_item)
            {
                if ((bit & 7) != 0)
                    return 0;
                var pos = bits_flush();
                var n = Math.Min(Math.Min(items, 64 / bits_per_item), (byte_max - pos << 3) / bits_per_item);
                n -= n % (8 >> System.Numerics.BitOperations.TrailingZeroCount(bits_per_item)); //whole bytes
                if (n <= 0)
                {
                    bits_reserve(pos);
                    return 0;
                }
                bits8_at = pos;
                return n;
            }

            ///<summary>Writes the chunk <see cref="bits8"/> made room for: <paramref name="n"/> items of <paramref name="bits_per_item"/> bits, item 0 in the lowest.</summary>
            public void bits8_put(ulong items, int n, int bits_per_item)
            {
                var bytes = n * bits_per_item >> 3;
                store(buffer!, bits8_at, items, bytes, byte_max);
                bits_reserve(bits8_at + bytes);
            }

            //the bit stream on a byte boundary: the pending full byte written to its place. returns where the next byte goes
            int bits_flush()
            {
                if (bit == 0)
                    return bits_byte; //the reserved byte holds nothing yet: it is the next
                buffer![bits_byte] = (byte)bits;
                return byte_;
            }

            //a fresh bit byte reserved at `pos`, as `put_bits` does after a full byte
            void bits_reserve(int pos)
            {
                bits = 0;
                bit = 0;
                bits_byte = pos;
                byte_ = pos < byte_max ? pos + 1 : pos;
            }
#endregion

            public bool put_bits_bytes(int info, int info_bits, double value, int value_bytes, uint continue_at_case) => put_bits_bytes(info, info_bits, Unsafe.As<double, ulong>(ref value), value_bytes, continue_at_case);
            public bool put_bits_bytes(int info, int info_bits, float value, int value_bytes, uint continue_at_case) => put_bits_bytes(info, info_bits, Unsafe.As<float, uint>(ref value), value_bytes, continue_at_case);

            ///<summary>
            ///Puts a sequence of `info_bits` followed by `value_bytes` representing `value`.
            ///This is a common pattern for length-prefixed or type-prefixed fields.
            ///If `put_bits` for `info` requires retry, sets mode to `BITS_BYTES` and stores `value` and `value_bytes`
            ///in `u8` and `bytes_left` respectively for continuation.
            ///</summary>
            ///<param name="info">The integer containing the information bits (e.g., length or type).</param>
            ///<param name="info_bits">The number of bits to take from `info`.</param>
            ///<param name="value">The `ulong` value to write after the info bits.</param>
            ///<param name="value_bytes">The number of bytes to use for serializing `value`.</param>
            ///<param name="continue_at_case">The state to retry at if operation fails.</param>
            ///<returns>True if both info bits and value bytes were put successfully; false if a retry is needed.</returns>
            public bool put_bits_bytes(int info, int info_bits, ulong value, int value_bytes, uint continue_at_case)
            {
                if (put_bits(info, info_bits, continue_at_case))
                {
                    put_val(value, value_bytes);
                    return true;
                }

                u8 = value;
                bytes_left = value_bytes;
                mode = BITS_BYTES;
                return false;
            }
#region varint
            ///<summary>
            ///Minimum number of bytes (1..<paramref name="min"/>) needed to represent
            ///<paramref name="src"/>, capped at the caller-supplied <paramref name="min"/>.
            ///Computed in two instructions on x64 (<c>lzcnt + shift</c>) plus a single CMOV for
            ///the cap. Replaces the chained-ternary <c>bytes1..bytes5</c> family. Returns 1 for
            ///<c>src == 0</c> (since <c>BitOperations.Log2(0) == 0</c> in .NET).
            ///<para>The <paramref name="min"/> parameter is the second argument to
            ///<see cref="Math.Min(int, int)"/> — it acts as an <em>upper bound</em> on the
            ///return value. Each varint type's info-field width determines the cap (2/3/4/7/8
            ///for VarInt21/32/42/73/83 respectively).</para>
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            static int byte_count(ulong src, int min) => Math.Min((BitOperations.Log2(src) >> 3) + 1, min);

            ///<summary>VarInt21: 1 length-bit (0=1B, 1=2B) then 1-2 payload bytes.</summary>
            public bool put_varint21(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 2);
                return put_bits_bytes(bytes - 1, 1, src, bytes, continue_at_case);
            }

            ///<summary>VarInt21 with nulls_bits prefix.</summary>
            public bool put_varint21(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 2);
                return put_bits_bytes(bytes - 1 << nulls_bits | nulls, nulls_bits + 1, src, bytes, continue_at_case);
            }

            ///<summary>VarInt32: 2 length-bits (1..3 = byte count) then 1-3 payload bytes.</summary>
            public bool put_varint32(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 3);
                return put_bits_bytes(bytes, 2, src, bytes, continue_at_case);
            }

            ///<summary>VarInt32 with nulls_bits prefix.</summary>
            public bool put_varint32(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 3);
                return put_bits_bytes(bytes << nulls_bits | nulls, nulls_bits + 2, src, bytes, continue_at_case);
            }

            ///<summary>VarInt42: 2 length-bits (0..3 = byte count - 1) then 1-4 payload bytes.</summary>
            public bool put_varint42(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 4);
                return put_bits_bytes(bytes - 1, 2, src, bytes, continue_at_case);
            }

            ///<summary>VarInt42 with nulls_bits prefix.</summary>
            public bool put_varint42(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 4);
                return put_bits_bytes(bytes - 1 << nulls_bits | nulls, nulls_bits + 2, src, bytes, continue_at_case);
            }

            ///<summary>VarInt73: 3 length-bits (1..7 = byte count) then 1-7 payload bytes.</summary>
            public bool put_varint73(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 7);
                return put_bits_bytes(bytes, 3, src, bytes, continue_at_case);
            }

            ///<summary>VarInt73 with nulls_bits prefix.</summary>
            public bool put_varint73(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 7);
                return put_bits_bytes(bytes << nulls_bits | nulls, nulls_bits + 3, src, bytes, continue_at_case);
            }

            ///<summary>VarInt83: 3 length-bits (0..7 = byte count - 1) then 1-8 payload bytes.</summary>
            public bool put_varint83(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 8);
                return put_bits_bytes(bytes - 1, 3, src, bytes, continue_at_case);
            }

            ///<summary>VarInt83 with nulls_bits prefix.</summary>
            public bool put_varint83(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 8);
                return put_bits_bytes(bytes - 1 << nulls_bits | nulls, nulls_bits + 3, src, bytes, continue_at_case);
            }

            ///<summary>VarInt84: 4 length-bits (1..8 = byte count) then 1-8 payload bytes.</summary>
            public bool put_varint84(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 8);
                return put_bits_bytes(bytes, 4, src, bytes, continue_at_case);
            }

            ///<summary>VarInt84 with nulls_bits prefix.</summary>
            public bool put_varint84(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 8);
                return put_bits_bytes(bytes << nulls_bits | nulls, nulls_bits + 4, src, bytes, continue_at_case);
            }

            ///<summary>
            ///Puts a standard varint-encoded `ulong` value into the buffer.
            ///If not enough buffer space, sets mode to `VARINT` and state to `next_case` for retry,
            ///storing `src` in `u8_` for continuation.
            ///</summary>
            ///<param name="src">The ulong value to varint-encode and put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the varint was put successfully; false if a retry is needed.</returns>
            public bool put_varint(ulong src, uint next_case)
            {
                if (varint(src))
                    return true;

                slot!.state = next_case;
                mode = VARINT;
                return false;
            }

            ///<summary>
            ///Puts the varint-encoded value currently stored in `u8_` into the buffer.
            ///This is used for retrying a `put_varint` operation.
            ///</summary>
            ///<returns>True if the varint was put successfully; false if more buffer space is needed.</returns>
            internal bool varint() => varint(u8_);

            ///<summary>
            ///Writes a `ulong` value into the buffer using standard varint encoding.
            ///Each byte written has its MSB set if more bytes follow; the last byte has MSB clear.
            ///Only 7 bits per byte are used for data.
            ///<para>
            ///Hot path stages 1&ndash;9 bytes into a single <see cref="ulong"/> register and emits them
            ///with one <see cref="Unsafe.WriteUnaligned{T}(ref byte, T)"/> when the buffer has &gt;= 9 bytes
            ///of headroom (varint of a 56-bit value fits in 8 bytes; the 9th byte is the &lt;=8-bit terminator).
            ///The 10-byte case (top bit set on a full ulong) falls through to the slow per-byte loop.
            ///</para>
            ///</summary>
            ///<param name="src">The `ulong` value to encode and write.</param>
            ///<returns>True if the entire varint value was written to the buffer; false if the buffer ran out of space, in which case `u8_` stores the remaining part of `src` to be encoded.</returns>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            internal bool varint(ulong src)
            {
                var buf = buffer!;
                var pos = byte_;
                var max = byte_max;
                ref var bufRef = ref MemoryMarshal.GetArrayDataReference(buf);

                //Fast path: src fits in 1..8 varint bytes (i.e. value < 2^56) AND we have >= 8 bytes
                //headroom in the buffer for an 8-byte unaligned store. Stage all bytes into one ulong,
                //emit them in a single store, then advance byte_ by exactly the varint byte count.
                //Bytes written past the actual varint length are scratch (they'll be overwritten before
                //any transmit, since the transmitter only reads up to byte_).
                if (src < (1UL << 56) && max - pos >= 8)
                {
                    //Lay out continuation-bit bytes into staged: each 7-bit group with MSB set,
                    //except the terminator. Loop is fully unrolled below; the compiler will collapse
                    //the per-iteration branch since the upper bound is a small constant range.
                    ulong staged = 0;
                    var shift = 0;
                    while (src >= 0x80)
                    {
                        staged |= ((src & 0x7FUL) | 0x80UL) << shift;
                        src >>= 7;
                        shift += 8;
                    }

                    staged |= src << shift; //terminator (MSB clear)
                    Unsafe.WriteUnaligned(ref Unsafe.Add(ref bufRef, pos), staged);
                    byte_ = pos + (shift >> 3) + 1;
                    return true;
                }

                //Slow path: per-byte with bounds.
                while (pos < max)
                {
                    if (src < 0x80)
                    {
                        Unsafe.Add(ref bufRef, pos) = (byte)src;
                        byte_ = pos + 1;
                        return true;
                    }

                    Unsafe.Add(ref bufRef, pos++) = (byte)(0x80 | src);
                    src >>= 7;
                }

                byte_ = pos;
                u8_ = src;
                return false;
            }

            ///<summary>
            ///Encodes a signed long value using ZigZag encoding.
            ///This maps signed integers to unsigned integers so that numbers with a small absolute value
            ///(i.e., close to zero, positive or negative) have a small varint encoded value.
            ///</summary>
            ///<param name="src">The signed long value to encode.</param>
            ///<param name="right">The number of bits to right-shift `src` in the XOR operation (typically 63 for Int64).</param>
            ///<returns>The ZigZag-encoded unsigned long value.</returns>
            public static ulong zig_zag(long src, int right) => (ulong)(src << 1 ^ src >> right);
#endregion

            ///<summary>
            ///Puts a `ulong` value `src` into the buffer using a fixed number of `bytes`.
            ///If not enough buffer space, sets up a retry.
            ///</summary>
            ///<param name="src">The `ulong` value to put.</param>
            ///<param name="bytes">The number of bytes to use for `src` (1 to 8).</param>
            ///<param name="next_field_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put_val(ulong src, int bytes, uint next_field_case)
            {
                if (remaining < bytes)
                {
                    put(src, bytes, next_field_case);
                    return false;
                }

                put_val(src, bytes);
                return true;
            }

            ///<summary>
            ///Puts a `ulong` value `src` into the buffer using a fixed number of `bytes`,
            ///respecting endianness. Advances buffer position.
            ///Assumes sufficient space is available.
            ///</summary>
            ///<param name="src">The `ulong` value to put.</param>
            ///<param name="bytes">The number of bytes to use for `src` (1 to 8).</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put_val(ulong src, int bytes)
            {
                put_val(src, bytes, buffer, byte_);
                byte_ += bytes;
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            static void put_val(ulong src, int srcBytes, byte[] dst, int dstOffset)
            {
                switch (srcBytes)
                {
                    case 8:
                        Endianness.OK.UInt64(src, dst, dstOffset);
                        break;
                    case 7:
                        Endianness.OK.UInt32((uint)src, dst, dstOffset);
                        Endianness.OK.UInt16((ushort)(src >> 32), dst, dstOffset + 4);
                        dst[dstOffset + 6] = (byte)(src >> 48);
                        break;
                    case 6:
                        Endianness.OK.UInt32((uint)src, dst, dstOffset);
                        Endianness.OK.UInt16((ushort)(src >> 32), dst, dstOffset + 4);
                        break;
                    case 5:
                        Endianness.OK.UInt32((uint)src, dst, dstOffset);
                        dst[dstOffset + 4] = (byte)(src >> 32);
                        break;
                    case 4:
                        Endianness.OK.UInt32((uint)src, dst, dstOffset);
                        break;
                    case 3:
                        Endianness.OK.UInt16((ushort)src, dst, dstOffset);
                        dst[dstOffset + 2] = (byte)(src >> 16);
                        break;
                    case 2:
                        Endianness.OK.UInt16((ushort)src, dst, dstOffset);
                        break;
                    case 1:
                        dst[dstOffset] = (byte)src;
                        break;
                    default:
                        throw new ArgumentOutOfRangeException(nameof(srcBytes),
                                                              $"Invalid byte count: {srcBytes}. Must be between 1 and 8.");
                }
            }

            ///<summary>
            ///Puts a `uint` value `src` into the buffer using a fixed number of `bytes`.
            ///If not enough buffer space, sets up a retry.
            ///</summary>
            ///<param name="src">The `uint` value to put.</param>
            ///<param name="bytes">The number of bytes to use for `src` (1 to 4).</param>
            ///<param name="next_field_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put_val(uint src, int bytes, uint next_field_case)
            {
                if (remaining < bytes)
                {
                    put(src, bytes, next_field_case);
                    return false;
                }

                put_val(src, bytes);
                return true;
            }

            ///<summary>
            ///Puts a `uint` value `src` into the buffer using a fixed number of `bytes`,
            ///respecting endianness. Advances buffer position.
            ///Assumes sufficient space is available.
            ///</summary>
            ///<param name="src">The `uint` value to put.</param>
            ///<param name="bytes">The number of bytes to use for `src` (1 to 4).</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put_val(uint src, int bytes)
            {
                byte_ += bytes;
                switch (bytes)
                {
                    case 4:
                        Endianness.OK.UInt32(src, buffer!, byte_ - 4);
                        return;
                    case 3:
                        Endianness.OK.UInt16((ushort)src, buffer!, byte_ - 3);
                        buffer![byte_ - 1] = (byte)(src >> 16);
                        return;
                    case 2:
                        Endianness.OK.UInt16((ushort)src, buffer!, byte_ - 2);
                        return;
                    case 1:
                        buffer![byte_ - 1] = (byte)src;
                        return;
                }
            }

            ///<summary>
            ///Puts a string into the buffer using varint encoding for its length and for each character.
            ///If not enough buffer space, sets mode to `STR` and state to `next_case` for retry,
            ///storing `src` in the `str` field for continuation.
            ///</summary>
            ///<param name="src">The string to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the string was put successfully; false if a retry is needed.</returns>
            ///<summary>
            ///Writes <paramref name="src"/> to the buffer as a length-prefixed varint sequence.
            ///Hot path: 8 ASCII chars per iteration packed into a single <see cref="ulong"/> and emitted via
            ///<see cref="Unsafe.WriteUnaligned{T}(ref byte, T)"/>. Detects ASCII via the OR-mask
            ///<c>(c0|c1|...|c7) &amp; ~0x7F == 0</c>; on hit, writes 8 bytes in one store.
            ///<para>
            ///Falls back to per-char <see cref="varint(ulong)"/> for &lt; 8-char tails, any non-ASCII char,
            ///or when fewer than 8 buffer bytes remain. The slow path uses the same <c>varint()</c> the
            ///<c>case STR:</c> resume dispatcher uses, so partial-buffer interruptions store remaining
            ///bits in <c>u8_</c> and resume transparently on the next call.
            ///</para>
            ///<para>
            ///Length sentinel: <c>u4 = uint.MaxValue</c> at entry signals "length-phase". On length-varint
            ///partial, <c>u4</c> stays at <c>uint.MaxValue</c> and the resume path knows to finish the
            ///length first via <c>varint()</c>.
            ///</para>
            ///</summary>
            ///<param name="src">The string to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the string was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            public bool put(string src, uint next_case)
            {
                bit = ~(int)next_case; //string-leaf park discriminator seed: for a PLAIN field park slot.state == next_case
                //while bit == ~next_case — never equal; only a chain leaf's flip makes slot.state == (uint)bit

                //=== Length phase ===
                u4 = uint.MaxValue; //length-phase sentinel for the case STR resume
                if (!varint((ulong)src.Length))
                {
                    slot!.state = next_case;
                    str = src;
                    mode = STR;
                    return false;
                }
                return put_chars(src, next_case);
            }

            ///<summary>
            ///Writes <paramref name="src"/> to the buffer as varint-encoded characters with NO length prefix —
            ///the wire <see cref="Receiver.try_get_str"/> reads. Works exactly like <see cref="put(string, uint)"/>
            ///minus the varint character-count prefix. Without a count the receiver cannot know where the string
            ///ends, so this wire only works where an enclosing framer bounds it (the string ends WITH the stream,
            ///at the framer's terminator): the canonical user is the <see cref="StringStream"/> chain leaf; a
            ///plain field should use <see cref="put(string, uint)"/>.
            ///</summary>
            ///<param name="src">The string to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the string was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public bool put_str(string src, uint next_case)
            {
                bit = ~(int)next_case; //string-leaf park discriminator seed — see put(string, uint)
                return put_chars(src, next_case);
            }

            ///<summary>
            ///Emits <paramref name="src"/>'s characters as varints from index 0 — the shared char-phase body of
            ///<see cref="put(string, uint)"/> (after its length prefix) and <see cref="put_str"/>. Every entry
            ///starts at char 0: a park is resumed by the <c>case STR:</c> dispatcher / the
            ///<see cref="StringStream"/> leaf (varint() + char loop), never by re-entering here.
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            bool put_chars(string src, uint next_case)
            {
                var buf = buffer!;
                var pos = byte_;
                var limit = byte_max;
                var len = src.Length;
                uint u4_ = 0;

                ref var bufRef = ref MemoryMarshal.GetArrayDataReference(buf);

                //=== Fast path: 8 ASCII chars per Unsafe.WriteUnaligned ===
                while ((int)u4_ + 8 <= len && pos + 8 <= limit)
                {
                    var c0 = src[(int)u4_];
                    var c1 = src[(int)u4_ + 1];
                    var c2 = src[(int)u4_ + 2];
                    var c3 = src[(int)u4_ + 3];
                    var c4 = src[(int)u4_ + 4];
                    var c5 = src[(int)u4_ + 5];
                    var c6 = src[(int)u4_ + 6];
                    var c7 = src[(int)u4_ + 7];
                    if (((c0 | c1 | c2 | c3 | c4 | c5 | c6 | c7) & ~0x7F) != 0)
                        break;
                    var packed = c0 | (long)c1 << 8 | (long)c2 << 16 | (long)c3 << 24 | (long)c4 << 32 | (long)c5 << 40 | (long)c6 << 48 | (long)c7 << 56;
                    Unsafe.WriteUnaligned(ref Unsafe.Add(ref bufRef, pos), packed);
                    u4_ += 8;
                    pos += 8;
                }

                //Sync byte_/u4 so varint() (which advances byte_ internally) sees the right cursor.
                byte_ = pos;
                u4 = u4_;

                //=== Slow path: per-char varint, resume-compatible ===
                //varint() either fully writes the char or stores remaining bits in u8_ and returns
                //false. The resume path (transmitter case STR) calls varint() to finish, then loops.
                while (u4 < len)
                    if (!varint(src[(int)u4++]))
                    {
                        slot!.state = next_case;
                        str = src;
                        mode = STR;
                        return false;
                    }
                return true;
            }

            ///<summary>
            ///Writes <paramref name="src"/> to the buffer as raw <b>UTF-8</b> bytes with NO length prefix —
            ///the wire format <see cref="Receiver.try_get_utf"/> reads.
            ///If not enough buffer space, sets mode to <c>STR_UTF8</c> and state to <paramref name="next_case"/>
            ///for retry, storing <paramref name="src"/> in the <c>str</c> field for continuation.
            ///<para>
            ///Without a count the receiver cannot know where the string ends, so this wire only works where an
            ///enclosing framer bounds it (the string ends WITH the stream, at the framer's terminator): the
            ///canonical user is the <see cref="UTFStream"/> chain leaf.
            ///</para>
            ///<para>
            ///CONTRACT — the caller supplies well-formed UTF-16: NO unpaired surrogates (they have no UTF-8
            ///encoding). The encoder does NOT validate — feeding a malformed string is a caller bug with
            ///unspecified wire effects (a mid-transmission failure, or a silently different value on the peer).
            ///A caller unsure of its data must validate or sanitize it FIRST, with the standard library:
            ///<c>Encoding.UTF8.GetByteCount(src)</c> throws under
            ///<c>new UTF8Encoding(false, throwOnInvalidBytes: true)</c>, or sanitize explicitly with
            ///<c>Encoding.UTF8.GetString(Encoding.UTF8.GetBytes(src))</c> (an unpaired surrogate becomes U+FFFD)
            ///— and be explicit about the substitution.
            ///</para>
            ///</summary>
            ///<param name="src">The string to put — well-formed UTF-16, per the CONTRACT above.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the string was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            public bool put_utf(string src, uint next_case)
            {
                bit = ~(int)next_case; //string-leaf park discriminator seed — see put(string, uint)

                //No length prefix on this wire — straight to the char phase.
                u4 = 0;
                bytes_left = 0; //no split sequence pending
                str = src;

                if (putting_utf())
                {
                    u8_ = 0;
                    return true; //putting_utf already cleared str
                }

                slot!.state = next_case;
                mode = STR_UTF8;
                return false;
            }

            ///<summary>
            ///Encodes <c>str</c>'s characters as UTF-8 from index <c>u4</c> on, until the source is exhausted or
            ///the buffer is full.
            ///<para>
            ///Register roles while in this phase: <c>u4</c> = next char to encode;
            ///<c>bytes_left</c> = count of bytes of a sequence split by the previous fill, packed little-endian in
            ///<c>u8_</c> and drained before anything else — so the tail bytes of every buffer are used, matching
            ///<c>put(string)</c>'s partial-varint behavior. A surrogate met in the loop is assumed a PAIR lead —
            ///<see cref="put_utf"/>'s CONTRACT puts UTF-16 well-formedness on the caller.
            ///</para>
            ///<para>
            ///Bulk path: on ASCII, UTF-8 is the identity, so the encoder reuses the varint codec's SIMD ASCII
            ///shape — 16 chars per <see cref="Vector256"/> narrow-store, 8 per <see cref="Vector128"/>,
            ///with the same short-run backoff. Non-ASCII falls to a scalar path that builds the 2..4-byte
            ///sequence ONCE in registers and only decides where it goes: straight out when it fits whole,
            ///split-staged otherwise.
            ///</para>
            ///</summary>
            ///<returns>True if the string was encoded completely (<c>str</c> is cleared); false if the buffer
            ///filled up and the resume state was committed to <c>u4</c> / <c>u8_</c> / <c>bytes_left</c>.</returns>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            internal bool putting_utf()
            {
                var buf = buffer!;
                var src = str!;
                var pos = byte_;
                var limit = byte_max;
                var i = (int)u4;
                var len = src.Length;

                ref var bufRef = ref MemoryMarshal.GetArrayDataReference(buf);

                //Drain a sequence split by the previous fill.
                if (0 < bytes_left)
                {
                    var p = u8_;
                    var n = bytes_left;
                    do
                    {
                        if (pos == limit) //still unfinished, but bytes went out
                        {
                            byte_ = pos;
                            u4 = (uint)i;
                            u8_ = p;
                            bytes_left = n;
                            return false;
                        }

                        Unsafe.Add(ref bufRef, pos++) = (byte)p;
                        p >>= 8;
                    } while (0 < --n);

                    bytes_left = 0;
                }

                ref var srcRef = ref MemoryMarshal.GetReference(src.AsSpan());
                ref var srcU = ref Unsafe.As<char, ushort>(ref srcRef); //vector ops are not defined over `char`

                var skip = 0;

                while (i < len && pos < limit)
                {
                    //An ASCII run cannot start on a non-ASCII character, so one compare gates the whole bulk block.
                    if (Unsafe.Add(ref srcRef, i) < 0x80)
                    {
                        if (0 < skip)
                            skip--;
                        else if (Vector256.IsHardwareAccelerated && 16 <= len - i && 16 <= limit - pos)
                        {
                            var v = Vector256.LoadUnsafe(ref srcU, (uint)i);

                            //16 bytes of room are guaranteed, so this store is in bounds even when only the
                            //leading `run` of them are meaningful - the rest is overwritten next round.
                            Vector256.Narrow(v, v).GetLower().StoreUnsafe(ref bufRef, (uint)pos);

                            if ((v & VARINT_NON_ASCII_256) == Vector256<ushort>.Zero) //cheap any-test, the common case
                            {
                                i += 16;
                                pos += 16;
                                continue;
                            }

                            var run = BitOperations.TrailingZeroCount(Vector256.GreaterThan(v, VARINT_ASCII_MAX_256).ExtractMostSignificantBits());
                            i += run; //>= 1: element 0 was ASCII
                            pos += run;
                            if (run < 8)
                                skip = VARINT_BACKOFF; //runs this short cost more in vector work than they save
                        }
                        else if (8 <= len - i && 8 <= limit - pos)
                        {
                            var v = Vector128.LoadUnsafe(ref srcU, (uint)i);

                            Unsafe.WriteUnaligned(ref Unsafe.Add(ref bufRef, pos), Vector128.Narrow(v, v).AsUInt64().GetElement(0));

                            if ((v & VARINT_NON_ASCII_128) == Vector128<ushort>.Zero)
                            {
                                i += 8;
                                pos += 8;
                                continue;
                            }

                            var run = BitOperations.TrailingZeroCount(Vector128.GreaterThan(v, VARINT_ASCII_MAX_128).ExtractMostSignificantBits());
                            i += run;
                            pos += run;
                            if (run < 8)
                                skip = VARINT_BACKOFF;
                        }
                    }

                    int c0 = Unsafe.Add(ref srcRef, i); //the interrupting, or room-limited, character
                    if (c0 < 0x80)
                    {
                        Unsafe.Add(ref bufRef, pos++) = (byte)c0; //loop head guarantees pos < limit
                        i++;
                        continue;
                    }

                    //ONE place computes the sequence; the branch below only decides where to put it.
                    int b0, b1, b2 = 0, b3 = 0, n;
                    if (c0 < 0x800)
                    {
                        b0 = 0xC0 | c0 >> 6;
                        b1 = 0x80 | c0 & 0x3F;
                        n = 2;
                        i++;
                    }
                    else if ((c0 & 0xF800) == 0xD800) //a validated surrogate PAIR — two chars, one code point
                    {
                        var point = 0x1_0000 + ((c0 - 0xD800) << 10) + (Unsafe.Add(ref srcRef, i + 1) - 0xDC00);
                        b0 = 0xF0 | point >> 18;
                        b1 = 0x80 | point >> 12 & 0x3F;
                        b2 = 0x80 | point >> 6 & 0x3F;
                        b3 = 0x80 | point & 0x3F;
                        n = 4;
                        i += 2;
                    }
                    else
                    {
                        b0 = 0xE0 | c0 >> 12;
                        b1 = 0x80 | c0 >> 6 & 0x3F;
                        b2 = 0x80 | c0 & 0x3F;
                        n = 3;
                        i++;
                    }

                    if (n <= limit - pos) //fits whole — straight out, the staging is never touched
                    {
                        Unsafe.Add(ref bufRef, pos++) = (byte)b0;
                        Unsafe.Add(ref bufRef, pos++) = (byte)b1;
                        if (2 < n)
                            Unsafe.Add(ref bufRef, pos++) = (byte)b2;
                        if (3 < n)
                            Unsafe.Add(ref bufRef, pos++) = (byte)b3;
                        continue;
                    }

                    //Does not fit whole: emit what fits, pack the rest for the next fill.
                    var pend = (ulong)(uint)(b0 | b1 << 8 | b2 << 16 | b3 << 24);
                    var left = n;
                    while (pos < limit)
                    {
                        Unsafe.Add(ref bufRef, pos++) = (byte)pend;
                        pend >>= 8;
                        left--;
                    }

                    byte_ = pos;
                    u4 = (uint)i;
                    u8_ = pend;
                    bytes_left = left;
                    return false;
                }

                byte_ = pos;
                u4 = (uint)i;
                if (i < len)
                    return false; //buffer full on a char boundary — nothing staged (bytes_left == 0)

                //=== Success ===
                str = null;
                return true;
            }

            ///<summary>
            ///OPTIONAL string-fragment supplier for a chain-string transmission — the streaming answer to
            ///"my content is produced in pieces". A generator that yields text in fragments (a document
            ///renderer, a report builder) would otherwise have to concatenate them into one big <c>string</c>
            ///just to send it; instead, set this field (alongside staging the FIRST fragment as <see cref="str"/>)
            ///and <see cref="StringStream"/>/<see cref="UTFStream"/> will pull fragment after fragment from it
            ///once the current one is fully emitted — until it returns <c>null</c>, which ends the transfer. The
            ///fragments concatenate ON THE WIRE: the prefix-less stream carries just their characters back to
            ///back, so the receiver assembles them into ONE string, indistinguishable from sending the
            ///pre-concatenated whole (bit-identical wire).
            ///<para>
            ///Fragments may be empty. For the <see cref="UTFStream"/> wire, <see cref="put_utf"/>'s CONTRACT
            ///applies to EACH fragment: well-formed UTF-16 — in particular, a surrogate pair must not be split
            ///across two fragments.
            ///</para>
            ///<para>
            ///Consulted ONLY by the chain leaves; plain <c>put*(string, …)</c> fields ignore it. Cleared when
            ///the supplier is drained and by <see cref="reset"/>.
            ///</para>
            ///</summary>
            public Func<string?>? strs;

            ///<summary>
            ///Stages <paramref name="src"/> for a transform-chain transmission and hands back the matching
            ///stateless string LEAF, ready to be embedded with <c>datatype(chain_id, leaf, next_case)</c>.
            ///The string rides the <see cref="str"/> register — otherwise idle for the whole span of a string
            ///transfer — which is what lets the leaf itself stay a shared, stateless singleton. To stream content
            ///produced in pieces without concatenating it first, ALSO set <see cref="strs"/> — the leaf will pull
            ///and send the following fragments after <paramref name="src"/> completes.
            ///</summary>
            ///<param name="src">The string the chain will carry.</param>
            ///<param name="utf">Leaf codec: <c>true</c> — UTF-8 (<see cref="put_utf"/> wire, the
            ///directional-string case), <c>false</c> — varint (<see cref="put(string, uint)"/> wire, the plain
            ///<c>[Zstd] string</c> case).</param>
            ///<param name="next_case">The field's retry case — the SAME value the pack passes to
            ///<c>datatype(chain_id, leaf, next_case)</c>. Seeded as <c>bit = ~next_case</c>: unique to this field
            ///within the pack's switch, so the leaf's park state can never collide with any other
            ///<c>slot.state</c> in flight, and every string transfer re-seeds <c>bit</c> so it is never stale.</param>
            ///<returns>The shared leaf singleton to pass into the chain.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public BytesSrc put(string src, bool utf, uint next_case)
            {
                str = src;
                bit = ~(int)next_case; //discriminator seed: slot.state == (uint)bit only after the leaf's FIRST park flips it
                return utf ? UTFStream.ONE : StringStream.ONE;
            }

            ///<summary>
            ///Sets up a retry operation for putting a `uint` value.
            ///Stores `src`, `bytes`, and `next_case` in `u4`, `bytes_left`, and `slot.state` respectively.
            ///Sets mode to `VAL4`.
            ///</summary>
            ///<param name="src">The `uint` value that needs to be written.</param>
            ///<param name="bytes">The number of bytes `src` should occupy (1 to 4).</param>
            ///<param name="next_case">The state to resume at when more buffer space is available.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            void put(uint src, int bytes, uint next_case)
            {
                slot!.state = next_case;
                bytes_left = bytes;
                u4 = src;
                mode = VAL4;
            }

            ///<summary>
            ///Sets up a retry operation for putting a `ulong` value.
            ///Stores `src`, `bytes`, and `next_case` in `u8`, `bytes_left`, and `slot.state` respectively.
            ///Sets mode to `VAL8`.
            ///</summary>
            ///<param name="src">The `ulong` value that needs to be written.</param>
            ///<param name="bytes">The number of bytes `src` should occupy (1 to 8).</param>
            ///<param name="next_case">The state to resume at when more buffer space is available.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            void put(ulong src, int bytes, uint next_case)
            {
                slot!.state = next_case;
                bytes_left = bytes;
                u8 = src;
                mode = VAL8;
            }

            ///<summary>
            ///Sets the transmitter's current processing mode to `RETRY` and records `the_case` as the state
            ///to resume from when more buffer space is available (or operation can be retried).
            ///</summary>
            ///<param name="the_case">The specific state or step in the serialization logic to resume at.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void retry_at(uint the_case)
            {
                slot!.state = the_case;
                mode = RETRY;
            }

            ///<summary>
            ///Calculates the minimum number of bytes required to represent an integer value.
            ///0 requires 0 bytes (by some conventions, not universally).
            ///1-255 requires 1 byte.
            ///256-65535 requires 2 bytes.
            ///65536-16777215 requires 3 bytes.
            ///Larger values up to Int32.MaxValue require 4 bytes.
            ///</summary>
            ///<param name="value">The integer value.</param>
            ///<returns>The number of bytes required (0-4).</returns>
            public int bytes4value(int value) => value < 0xFFFF     ? value < 0xFF ? value == 0 ? 0 : 1 : 2
                                                 : value < 0xFFFFFF ? 3
                                                                    : 4;

            ///<summary>
            ///Puts a boolean value into the buffer as a single byte (1 for true, 0 for false).
            ///If not enough buffer space, sets up a retry.
            ///</summary>
            ///<param name="src">The boolean value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the byte was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(bool src, uint next_case) => put(Unsafe.As<bool, byte>(ref src), next_case);

            ///<summary>
            ///Puts a signed byte value into the buffer. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The signed byte value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(sbyte src) => buffer![byte_++] = (byte)src;

            ///<summary>
            ///Puts a nullable signed byte value into the buffer. Assumes the value is not null and sufficient space is available.
            ///</summary>
            ///<param name="src">The nullable signed byte value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(sbyte? src) => buffer![byte_++] = (byte)src!.Value;

            ///<summary>
            ///Puts a signed byte value into the buffer. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The signed byte value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the byte was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(sbyte src, uint next_case) => put((byte)src, next_case);

            ///<summary>
            ///Puts a nullable signed byte value into the buffer. Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable signed byte value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the byte was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(sbyte? src, uint next_case) => put((byte)src!.Value, next_case);

            ///<summary>
            ///Puts an unsigned byte value into the buffer. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The unsigned byte value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(byte src) => buffer![byte_++] = src;

            ///<summary>
            ///Puts a nullable unsigned byte value into the buffer. Assumes the value is not null and sufficient space is available.
            ///</summary>
            ///<param name="src">The nullable unsigned byte value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(byte? src) => buffer![byte_++] = src!.Value;

            ///<summary>
            ///Puts a nullable unsigned byte value into the buffer. Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable unsigned byte value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the byte was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(byte? src, uint next_case) => put(src!.Value, next_case);

            ///<summary>
            ///Puts an unsigned byte value into the buffer. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The unsigned byte value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the byte was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(byte src, uint next_case)
            {
                if (byte_ < byte_max)
                {
                    put(src);
                    return true;
                }

                put(src, 1, next_case);
                return false;
            }

            ///<summary>
            ///Closes the window of a one-byte array <see cref="AdHoc.window"/> opened, and sets the retry when it held fewer
            ///bytes than asked: the buffer is full.
            ///</summary>
            public int window_done(int asked, uint retry_case)
            {
                var n = window_close();
                if (n < asked)
                    retry_at(retry_case);
                return n;
            }

            ///<summary>
            ///Writes a sequence of bytes from a source array into the internal output buffer.
            ///If the data exceeds available space, it performs a partial write and sets a retry state.
            ///</summary>
            ///<param name="src">The source byte array to read from.</param>
            ///<param name="src_byte">The starting index (offset) in the source array.</param>
            ///<param name="src_bytes">The number of bytes to attempt to write.</param>
            ///<param name="retry_case">The state identifier to transition to if the buffer becomes full.</param>
            ///<returns>The number of bytes actually written to the buffer.</returns>
            public int put(ReadOnlySpan<byte> src, int src_byte, int src_bytes, uint retry_case)
            {
                if (remaining < src_bytes)
                {
                    src_bytes = remaining;
                    retry_at(retry_case);
                }

                src.Slice(src_byte, src_bytes).CopyTo(buffer!.AsSpan(byte_));
                byte_ += src_bytes;
                return src_bytes;
            }

            ///<inheritdoc cref="put(ReadOnlySpan{byte}, int, int, uint)"/>
            public int put(byte[] src, int src_byte, int src_bytes, uint retry_case)
            {
                if (remaining < src_bytes)
                {
                    src_bytes = remaining;
                    retry_at(retry_case);
                }

                Array.Copy(src, src_byte, buffer, byte_, src_bytes);
                byte_ += src_bytes;
                return src_bytes;
            }

            ///<summary>
            ///Puts a nullable short (Int16) value into the buffer. Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable short value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(short? src, uint next_case) => put((ushort)src!.Value, next_case);

            ///<summary>
            ///Puts a short (Int16) value into the buffer. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The short value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(short src, uint next_case) => put((ushort)src, next_case);

            ///<summary>
            ///Puts a nullable unsigned short (UInt16) value into the buffer. Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable unsigned short value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(ushort? src, uint next_case) => put(src!.Value, next_case);

            ///<summary>
            ///Puts an unsigned short (UInt16) value into the buffer. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The unsigned short value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(ushort src, uint next_case)
            {
                if (remaining < 2)
                {
                    put(src, 2, next_case);
                    return false;
                }

                put(src);
                return true;
            }

            ///<summary>
            ///Puts a short (Int16) value into the buffer. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The short value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(short src) => put((ushort)src);

            ///<summary>
            ///Puts a nullable short (Int16) value into the buffer. Assumes value is not null and sufficient space.
            ///</summary>
            ///<param name="src">The nullable short value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(short? src) => put((ushort)src!.Value);

            ///<summary>
            ///Puts a nullable unsigned short (UInt16) value into the buffer. Assumes value is not null and sufficient space.
            ///</summary>
            ///<param name="src">The nullable unsigned short value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(ushort? src) => put(src!.Value);

            ///<summary>
            ///Puts an unsigned short (UInt16) value into the buffer using appropriate endianness. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The unsigned short value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(ushort src)
            {
                Endianness.OK.UInt16(src, buffer!, byte_);
                byte_ += 2;
            }

            ///<summary>
            ///Puts an integer (Int32) value into the buffer. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The integer value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(int src, uint next_case) => put((uint)src, next_case);

            ///<summary>
            ///Puts a nullable integer (Int32) value into the buffer. Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable integer value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(int? src, uint next_case) => put((uint)src!.Value, next_case);

            ///<summary>
            ///Puts a float value into the buffer (as its UInt32 bit representation). If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The float value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(float src, uint next_case) => put(Unsafe.As<float, uint>(ref src), next_case);

            ///<summary>
            ///Puts a nullable float value into the buffer (as its UInt32 bit representation). Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable float value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(float? src, uint next_case)
            {
                var f = src!.Value;
                return put(Unsafe.As<float, uint>(ref f), next_case);
            }

            ///<summary>
            ///Puts a nullable unsigned integer (UInt32) value into the buffer. Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable unsigned integer value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(uint? src, uint next_case) => put(src!.Value, next_case);

            ///<summary>
            ///Puts an unsigned integer (UInt32) value into the buffer. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The unsigned integer value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(uint src, uint next_case)
            {
                if (remaining < 4)
                {
                    put(src, 4, next_case);
                    return false;
                }

                put(src);
                return true;
            }

            ///<summary>
            ///Puts an integer (Int32) value into the buffer. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The integer value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(int src) => put((uint)src);

            ///<summary>
            ///Puts a nullable integer (Int32) value into the buffer. Assumes value is not null and sufficient space.
            ///</summary>
            ///<param name="src">The nullable integer value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(int? src) => put((uint)src!.Value);

            ///<summary>
            ///Puts a nullable float value into the buffer (as its UInt32 bit representation). Assumes value is not null and sufficient space.
            ///</summary>
            ///<param name="src">The nullable float value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(float? src)
            {
                var f = src!.Value;
                put(Unsafe.As<float, uint>(ref f));
            }

            ///<summary>
            ///Puts a float value into the buffer (as its UInt32 bit representation). Assumes sufficient space.
            ///</summary>
            ///<param name="src">The float value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(float src) => put(Unsafe.As<float, uint>(ref src));

            ///<summary>
            ///Puts a nullable unsigned integer (UInt32) value into the buffer. Assumes value is not null and sufficient space.
            ///</summary>
            ///<param name="src">The nullable unsigned integer value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(uint? src) => put(src!.Value);

            ///<summary>
            ///Puts an unsigned integer (UInt32) value into the buffer using appropriate endianness. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The unsigned integer value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(uint src)
            {
                Endianness.OK.UInt32(src, buffer!, byte_);
                byte_ += 4;
            }

            ///<summary>
            ///Puts a long (Int64) value into the buffer. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The long value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(long src, uint next_case) => put((ulong)src, next_case);

            ///<summary>
            ///Puts a nullable long (Int64) value into the buffer. Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable long value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(long? src, uint next_case) => put((ulong)src!.Value, next_case);

            ///<summary>
            ///Puts a double value into the buffer (as its UInt64 bit representation). If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The double value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(double src, uint next_case) => put(Unsafe.As<double, ulong>(ref src), next_case);

            ///<summary>
            ///Puts a nullable double value into the buffer (as its UInt64 bit representation). Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable double value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(double? src, uint next_case)
            {
                var d = src!.Value;
                return put(Unsafe.As<double, ulong>(ref d), next_case);
            }

            ///<summary>
            ///Puts a nullable unsigned long (UInt64) value into the buffer. Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable unsigned long value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(ulong? src, uint next_case) => put(src!.Value, next_case);

            ///<summary>
            ///Puts an unsigned long (UInt64) value into the buffer. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The unsigned long value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(ulong src, uint next_case)
            {
                if (remaining < 8)
                {
                    put(src, 8, next_case);
                    return false;
                }

                put(src);
                return true;
            }

            ///<summary>
            ///Puts a double value into the buffer (as its UInt64 bit representation). Assumes sufficient space.
            ///</summary>
            ///<param name="src">The double value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(double src) => put(Unsafe.As<double, ulong>(ref src));

            ///<summary>
            ///Puts a nullable double value into the buffer (as its UInt64 bit representation). Assumes value is not null and sufficient space.
            ///</summary>
            ///<param name="src">The nullable double value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(double? src)
            {
                var d = src!.Value;
                put(Unsafe.As<double, ulong>(ref d));
            }

            ///<summary>
            ///Puts a long (Int64) value into the buffer. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The long value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(long src) => put((ulong)src);

            ///<summary>
            ///Puts a nullable long (Int64) value into the buffer. Assumes value is not null and sufficient space.
            ///</summary>
            ///<param name="src">The nullable long value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(long? src) => put((ulong)src!.Value);

            ///<summary>
            ///Puts a nullable unsigned long (UInt64) value into the buffer. Assumes value is not null and sufficient space.
            ///</summary>
            ///<param name="src">The nullable unsigned long value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(ulong? src) => put(src!.Value);

            ///<summary>
            ///Puts an unsigned long (UInt64) value into the buffer using appropriate endianness. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The unsigned long value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(ulong src)
            {
                Endianness.OK.UInt64(src, buffer, byte_);
                byte_ += 8;
            }

            public override string ToString()
            {
                if (slot == null)
                    return "";
                var s = slot;
                while (s.prev != null)
                    s = s.prev;
                var str = "";
                var offset = "";
                for (; s != slot; s = s.next, offset += "\t")
                    str += $"{offset}{s.src?.GetType()}\t{s.state}\n";

                str += $"{offset}{slot.src?.GetType()}\t{s.state}\n";

                return str;
            }

            ///<summary>
            ///Infrastructure base class for one-to-many message broadcasting (publisher → multiple subscribers pattern) -
            ///without a lock.
            ///<para>
            ///This is an internal infrastructure component. It is **not** meant to be used directly
            ///by application code. Concrete implementations are typically generated by source generators
            ///as part of the connection/messaging infrastructure.
            ///</para>
            ///<para>
            ///The subscribers are an array replaced whole on every change - copy on write, published with a CAS. A broadcast
            ///reads it once and walks it without a lock: broadcasts from any number of threads run side by side, and a
            ///subscription that changes meanwhile is seen by the next broadcast. A change copies the array - O(subscribers) -
            ///which is the right trade where broadcasts are many and subscriptions change seldom. Nothing is allocated on the
            ///path of a broadcast.
            ///</para>
            ///</summary>
            ///<typeparam name="DST">Type of subscriber/destination. Must be a concrete subtype
            ///of <see cref="Transmitter"/>. Usually represents a connection or client proxy.</typeparam>
            public abstract class Broadcaster<DST>
                where DST : Transmitter
            {
                ///<summary>
                ///The subscribers, unique by reference: never changed in place - a change publishes a new array.
                ///</summary>
                DST[] _subscribers = [];

                ///<summary>The subscribers at this moment - a snapshot, not to be changed.</summary>
                public DST[] Subscribers => Volatile.Read(ref _subscribers);

                ///<summary>How many subscribers there are at this moment.</summary>
                public int Count => Volatile.Read(ref _subscribers).Length;

                public bool IsEmpty => Volatile.Read(ref _subscribers).Length == 0;

                ///<summary>Drops every subscriber.</summary>
                public void Reset() => Volatile.Write(ref _subscribers, []);

                ///<summary>
                ///Implements the logic to enqueue the captured data into the transmission queue of one subscriber.
                ///<para>
                ///Called with no lock held. It may subscribe and unsubscribe, this broadcaster included - the walk in progress
                ///goes on over the array it started with. It should be fast and not block: it runs once per subscriber.
                ///</para>
                ///</summary>
                protected abstract bool Broadcasting(Broadcastable src, DST dst);

                ///<summary>
                ///Broadcasts the pack the receiver has captured and gives the reference of the capture back: the pack
                ///returns to its pool once the last subscriber has sent it - at once, when there is none.
                ///</summary>
                public void Broadcast(Receiver bytes_src)
                {
                    Broadcastable? src = bytes_src.bytesCopy;
                    if (src == null)
                        return;
                    bytes_src.bytesCopy = null;
                    try
                    {
                        Broadcast(src);
                    }
                    finally
                    {
                        src.Release();
                    }
                }

                public void PrepareBroadcastIfAnySubscriber(Receiver bytes_src, int pack_id)
                {
                    if (0 < Count)
                        Receiver.BytesCopy.InMemory.Acquire(pack_id, bytes_src);
                }

                ///<summary>
                ///Broadcasts the captured packet to all subscribers of this moment. No lock: the array read at the start is
                ///walked, whatever changes meanwhile. A subscriber whose <see cref="Broadcasting"/> throws is unsubscribed after
                ///the walk; one whose queue is full stays - a transient full queue is not grounds for dropping it.
                ///Allocates nothing, but for the list of the broken ones when there are any.
                ///<para>
                ///The references: the caller holds one of its own for the time of the call. Every subscriber gets one with
                ///the pack and gives it back once the pack is out, or discarded. They are taken in one atomic step for all
                ///the subscribers, before the first of them can send the pack and give its reference back; those of the
                ///subscribers that did not take the pack are given back in one step after the walk. So a broadcast costs
                ///one atomic step, whatever the number of subscribers, and a second one only when a subscriber refused.
                ///</para>
                ///</summary>
                ///<param name="src">The raw byte source captured by a <see cref="Receiver"/>.</param>
                public void Broadcast(Broadcastable? src)
                {
                    if (src == null)
                        return;
                    var all = Volatile.Read(ref _subscribers);
                    if (all.Length == 0)
                        return;
                    DST[]? broken = null;
                    int nb = 0, back = 0, i = 0;
                    src.Acquire(all.Length);
                    try
                    {
                        for (; i < all.Length; i++)
                            try //a problem with a subscriber should not influence to others
                            {
                                if (!Broadcasting(src, all[i]))
                                    back++; //not queued (queue full)
                            }
                            catch (Exception)
                            {
                                back++;
                                (broken ??= new DST[all.Length])[nb++] = all[i]; //unsubscribe the problematic, after the walk
                            }
                    }
                    finally
                    {
                        if (0 < (back += all.Length - i)) //a walk cut short: those not reached
                            src.Release(back);
                    }

                    for (i = 0; i < nb; i++)
                        Unsubscribe(broken![i]);
                }

                ///<summary>
                ///Adds a subscriber; any thread, no lock.
                ///</summary>
                ///<param name="dst">The subscriber to add.</param>
                ///<returns><c>false</c>: it was subscribed already.</returns>
                public bool Subscribe(DST dst)
                {
                    for (;;)
                    {
                        var was = Volatile.Read(ref _subscribers);
                        foreach (var s in was)
                            if (ReferenceEquals(s, dst))
                                return false;
                        var now = new DST[was.Length + 1];
                        Array.Copy(was, now, was.Length);
                        now[was.Length] = dst;
                        if (ReferenceEquals(Interlocked.CompareExchange(ref _subscribers, now, was), was))
                            return true;
                    }
                }

                ///<summary>
                ///Removes a subscriber; any thread, no lock. Nothing is made when it is not subscribed.
                ///</summary>
                ///<param name="dst">The subscriber to remove.</param>
                ///<returns><c>false</c>: it was not subscribed.</returns>
                public bool Unsubscribe(DST dst)
                {
                    for (;;)
                    {
                        var was = Volatile.Read(ref _subscribers);
                        var at = -1;
                        for (var i = 0; i < was.Length; i++)
                            if (ReferenceEquals(was[i], dst))
                            {
                                at = i;
                                break;
                            }

                        if (at < 0)
                            return false;
                        DST[] now = was.Length == 1 ? [] : new DST[was.Length - 1];
                        Array.Copy(was, 0, now, 0, at);
                        Array.Copy(was, at + 1, now, at, was.Length - at - 1);
                        if (ReferenceEquals(Interlocked.CompareExchange(ref _subscribers, now, was), was))
                            return true;
                    }
                }

                ///<summary>
                ///Removes every subscriber <paramref name="which"/> accepts; any thread, no lock. <paramref name="which"/> may
                ///be asked again for a subscriber, when another change came in between.
                ///</summary>
                ///<returns>How many were removed.</returns>
                public int RemoveWhere(Predicate<DST> which)
                {
                    for (;;)
                    {
                        var was = Volatile.Read(ref _subscribers);
                        var keep = new DST[was.Length];
                        var n = 0;
                        foreach (var s in was)
                            if (!which(s))
                                keep[n++] = s;
                        if (n == was.Length)
                            return 0;
                        if (n == 0)
                            keep = [];
                        else
                            Array.Resize(ref keep, n);
                        if (ReferenceEquals(Interlocked.CompareExchange(ref _subscribers, keep, was), was))
                            return was.Length - n;
                    }
                }
            }

            ///<summary>
            ///Defines a reference-counted resource optimized for zero-allocation broadcasting.
            ///</summary>
            public interface Broadcastable : BytesSrc
            {
                ///<summary>
                ///Increments the reference counter to signal active use.
                ///</summary>
                ///<returns>The updated reference count after the increment.</returns>
                int Acquire();

                ///<summary>
                ///Takes <paramref name="n"/> references at once - those of all the subscribers of a broadcast. An
                ///implementation makes it one atomic step.
                ///</summary>
                ///<returns>The updated reference count.</returns>
                int Acquire(int n)
                {
                    var count = State();
                    while (0 < n--)
                        count = Acquire();
                    return count;
                }

                ///<summary>
                ///Gives <paramref name="n"/> references back at once, as <see cref="Release()"/> does one.
                ///</summary>
                ///<returns>The updated reference count, or -1 if more is given back than is held.</returns>
                int Release(int n)
                {
                    var count = State();
                    while (0 < n-- && -1 < count)
                        count = Release();
                    return count;
                }

                ///<summary>
                ///Returns the current instantaneous reference count.
                ///</summary>
                ///<remarks>
                ///In multi-threaded environments, this value is an "at-the-moment" snapshot
                ///and may change immediately after the call returns.
                ///</remarks>
                ///<returns>The current reference count.</returns>
                int State();

                ///<summary>
                ///Decrements the reference counter. If the counter reaches zero, the object is recycled.
                ///</summary>
                ///<returns>
                ///The updated reference count, or -1 if called on an already-released resource.
                ///</returns>
                int Release();
            }

            ///<summary>
            ///Chunked-stream <b>producer</b> — the transmit half of a streamed packet. Emits
            ///<c>[id][len][data]…[len][data][0x0000]</c>: the stream's id, then 2-byte little-endian
            ///length-prefixed chunks (payload ≤ <see cref="MAX"/> bytes each) pulled from a pluggable inner
            ///<see cref="Transmitter.BytesSrc"/> src, closed by a <c>0x0000</c> terminator. The serializer owns the
            ///framing: it reserves the prefix, fills the chunk, then back-patches the real length; the
            ///terminator is written once the src signals end (<c>__get_bytes</c> returns <c>true</c>).
            ///Resumable across transmit-buffer fills via the standard <c>true</c>/<c>false</c> contract;
            ///all chunk state is per-instance; src is a pure-byte producer (writes only buffer/byte_/byte_max — never the slot).
            ///</summary>
            public class Chunked : BytesSrc
            {
                ///<summary>
                ///The largest chunk payload. A chunk length is two bytes, and two of its values are not lengths:
                ///<c>0x0000</c> ends the stream and <see cref="ABORT"/> ends it as void. So a chunk carries at most
                ///<c>0xFFFE</c> bytes, and every producer of chunks (this class, <see cref="Tunnel.Relay"/>) honours it.
                ///</summary>
                public const int MAX = 0xFFFE;

                ///<summary>
                ///Chunk length that ends the stream as VOID: whatever the receiver got of it after its last complete pack
                ///is to be discarded, and nothing more of it will come. A relay writes it when the source of the packet it
                ///is forwarding disappears mid-way (a closed Observer tab during an upload, a dropped link): the receiving
                ///end resets only the virtual connection this stream belonged to, and the physical connection — shared
                ///by every tunnel on it — keeps running. The same shape as HTTP/2 RST_STREAM or QUIC RESET_STREAM: a
                ///chunked stream has no other way to stop part-way, and closing the connection is what we avoid.
                ///</summary>
                public const int ABORT = 0xFFFF;

                protected BytesSrc src = null!;      //inner stage — pure-byte (cipher/compressor/leaf) or a structured endpoint
                protected BytesSrc datatype = null!; //the chained structured pack, or null for a raw stream

                int idBytes = 1; //leading id width on the wire (bytes); 0 ⇒ id-less (a field stream / the enqueuing DataPass wrote it)
                int _state;      //PRIVATE chunk state machine (0 = chunk, 1 = terminator); the [id][tunnel_id] prelude rides dst.slot.state

                //--- tunnel_id prelude (asTunnel only) ----------------------------------------------------------
                //A tunnel endpoint emits a fixed-width little-endian tunnel_id field right after the pack id (the
                //many-to-one routing discriminator) and before the chunked body. Wire: [id][tunnel_id][chunks][0].
                public int tunnelId; //discriminator emitted on the wire (set via asTunnel); the RECEIVE side spells it tunnel_id
                int tunnelIdBytes;   //tunnel_id width on the wire: 0 = plain stream / one-to-one (nothing emitted); 1..4 = many-to-one. Zeroed once emitted

                public int __id => datatype != null ? datatype.__id : src.__id; //raw Stream (no datatype): fall back to the endpoint id

                ///<summary>(Re)configure with a chained STRUCTURED <paramref name="datatype"/>: the chunk body carries the
                ///serialized <paramref name="datatype"/> pack. Arms as an id-less stream (<c>idBytes == 0</c> — see
                ///<see cref="asStream"/>); the inner <paramref name="src"/> is the pure-byte codec stage, and it also supplies
                ///<see cref="__id"/> for a raw stream (<paramref name="datatype"/> <c>null</c>). Returns <c>this</c> for chaining.</summary>
                public Chunked Init(BytesSrc src, BytesSrc datatype)
                {
                    this.datatype = datatype;
                    this.src = src;
                    return asTunnel(0, 0, 0);
                }

                ///<summary>Convenience arming — the chain's own <see cref="_Adapter"/> serves as BOTH the inner byte
                ///stage and the datatype (its id identifies the stream): shorthand for <c>Init(_Adapter, _Adapter)</c>.</summary>
                public Chunked Init()
                {
                    datatype = _Adapter;
                    src = _Adapter;
                    return asTunnel(0, 0, 0);
                }

                ///<summary>Arm as a plain stream with an <paramref name="idBytes"/>-wide leading id (0 ⇒ id-less field stream).
                ///The id itself is <see cref="__id"/> (delegated to the chained datatype when present). Clears the private
                ///state. Returns <c>this</c> for chaining.</summary>
                public Chunked asStream(int idBytes) => asTunnel(idBytes, 0, 0);

                ///<summary>Arm as a tunnel endpoint: after the <paramref name="idBytes"/>-wide pack id, emits a
                ///<paramref name="tunnelIdBytes"/>-wide (0..4, little-endian) <paramref name="tunnelId"/> field before the
                ///chunk body (<c>tunnelIdBytes == 0</c> ⇒ plain stream — identical to <see cref="asStream"/>). Clears the
                ///private state. Returns <c>this</c> for chaining.</summary>
                public Chunked asTunnel(int idBytes, int tunnelId, int tunnelIdBytes)
                {
                    //NOTE: onStreamComplete is deliberately NOT cleared here — Transmitter.OnStreamComplete(hook)
                    //plants it into this chain BEFORE the arming Init runs; it is consumed by invokeOnStreamComplete
                    //at the stream end (source EOF or teardown), which always runs.
                    this.idBytes = idBytes;
                    _state = 0;
                    this.tunnelId = tunnelId;
                    this.tunnelIdBytes = tunnelIdBytes;
                    return this;
                }

                ///<summary>The per-stream hook, planted DIRECTLY by the generated <c>Transmitter.OnStreamComplete(hook)</c>
                ///override (<c>chain().onStreamComplete = hook</c>) right before this chain is armed. One-shot and
                ///nesting-safe by construction: <c>chain()</c> hands an inner stream a DIFFERENT (free) chain than the
                ///already-armed outer one. Consumed by <see cref="complete"/>.</summary>
                public Action<Transmitter, bool>? onStreamComplete;

                ///<summary>The chain's terminal (leaf) Adapter — framer and leaf travel as ONE aggregate, so the
                ///stream-end default always has its target. Generated arming wires it (<c>_Adapter.Init(…)</c>);
                ///codec stages may sit between the framer and this leaf.</summary>
                public readonly BytesSrc.Adapter _Adapter = new();

                ///<summary>Stream-boundary cleanup — the single call the generated <c>Chain</c> makes at BOTH ends of a
                ///stream's life: the completion branch (<paramref name="completed"/> <c>true</c>) and <c>Chain.Release</c>
                ///(<c>false</c>). Runs-and-consumes the armed hook; with no hook, a <see cref="FileStream"/> source is
                ///closed. Either way every per-stream reference on <see cref="_Adapter"/> is dropped.</summary>
                public void complete(Transmitter dst, bool completed)
                {
                    if (onStreamComplete != null)
                    {
                        onStreamComplete(dst, completed);
                        onStreamComplete = null;
                    }
                    else if (_Adapter.src is FileStream)
                        try
                        {
                            _Adapter.src.Dispose();
                        }
                        catch
                        {
                        }

                    _Adapter.src = null;
                    _Adapter.src_ = null;
                    _Adapter.redirect = null;
                }

                ///<summary>
                ///Framework entry. Emits <c>[id][tunnel_id]</c> through the transmitter's own retry machinery
                ///(<c>put_val(…, dst.slot.state = 1)</c> — parks in <c>mode</c> and resumes at the slot state), then
                ///length-prefixed chunks from <see cref="src"/> (each ≤ 65535 bytes, the prefix reserved up front and
                ///back-patched after the fill) on the PRIVATE <c>_state</c> machine, then a <c>0x0000</c> terminator
                ///once the src signals end. Returns <c>true</c> once the whole stream is written, <c>false</c> to park —
                ///including after every non-final chunk, so one drive emits at most one chunk.
                ///</summary>
                public virtual bool __get_bytes(Transmitter dst)
                {
                    switch (dst.slot!.state)
                    {
                        case 0:
                            //idBytes == 0 writes nothing and returns true (put_val(uint, 0) is a no-op), but the eagerly
                            //evaluated argument still advances the slot state past the id.
                            if (!dst.put_val((uint)__id, idBytes, dst.slot.state = 1))
                                return false;
                            goto case 1;
                        case 1:
                        {
                            if (tunnelIdBytes == 0)
                                break;
                            var bytes = tunnelIdBytes;
                            tunnelIdBytes = 0; //emitted once per arming
                            if (!dst.put_val((uint)tunnelId, bytes, 1))
                                return false;
                            break;
                        }
                    }

                    for (;;)
                        switch (_state)
                        {
                            case 0: //one length-prefixed chunk of pure bytes pulled from src
                            {
                                if (dst.remaining < 3)
                                    return false; //room for the 2-byte prefix + ≥1 payload byte

                                var lenPos = dst.byte_;
                                dst.byte_ = lenPos + 2; //reserve the length prefix
                                var byte_max = dst.byte_max;
                                var cap = lenPos + 2 + MAX; //clamp this chunk to ≤ MAX payload bytes (0xFFFF is ABORT)
                                if (cap < dst.byte_max)
                                    dst.byte_max = cap;
                                var done = get_bytes(dst);
                                dst.byte_max = byte_max;

                                var n = dst.byte_ - (lenPos + 2);
                                if (n == 0)
                                {
                                    dst.byte_ = lenPos; //nothing produced → rewind the empty reservation

                                    //`done` must be tested BEFORE treating n == 0 as a park: done-with-nothing-produced is
                                    //reachable — it is exactly the case where the PREVIOUS chunk consumed the source's last
                                    //byte, so this call hits EOF before producing anything. Parking here would re-drive an
                                    //already-completed (closed) source forever; the terminator ends the stream correctly.
                                    if (!done)
                                        return false; //src alive but produced nothing now → park
                                    _state = 1;
                                    break;
                                }

                                Endianness.OK.UInt16((ushort)n, dst.buffer!, lenPos); //back-patch the real length
                                if (!done)
                                    return false;
                                _state = 1;
                                break;
                            }
                            case 1: //2-byte zero terminator → end of stream
                                if (dst.remaining < 2)
                                    return false;
                                Endianness.OK.UInt16(0, dst.buffer!, dst.byte_);
                                dst.byte_ += 2;
                                return true;
                        }
                }

                ///<summary>Pulls the next chunk payload from the inner stage. Overridable seam for a framer subclass.</summary>
                public virtual bool get_bytes(Transmitter dst) => src.__get_bytes(dst);
            }

            ///<summary>Named alias only: a transmit-side tunnel endpoint is just a <see cref="Chunked"/> armed as a tunnel
            ///via <see cref="Chunked.asTunnel(int,int,int)"/> — all behavior lives in <see cref="Chunked"/>.</summary>
            public abstract class Tunnel : Chunked
            {
            }

            ///<summary>
            ///Known-size file <b>producer</b> — the transmit half of a <c>File</c> packet. Emits
            ///<c>[id][len][data…]</c>: the file's id, a single varint-encoded total-length header
            ///(supplied up front via <see cref="Init"/>), then exactly that many payload bytes pulled from a
            ///pluggable pure-byte inner <see cref="Transmitter.BytesSrc"/> <c>src</c> — no chunk framing, no terminator.
            ///Resumable across transmit-buffer fills via the standard true/false contract; all state is
            ///per-instance, src writes only buffer/byte_/byte_max (never the slot).
            ///</summary>
            public class File : BytesSrc
            {
                protected Stream src = null!; //direct byte source (any System.IO.Stream) — overridable

                //Application-level source alternative to src, armed by the AdHoc.BytesSrc Init overloads: a byte producer that
                //is not a System.IO.Stream (e.g. a virtual connection's Internal.BytesSrc). Its Read() is three-way: >0 bytes,
                //0 = "nothing available yet, still open" (park), -1 = end of stream.
                protected AdHoc.BytesSrc? src_; //non-null ⇒ payload is pulled from here instead of src
                protected int _id, _idBytes = 1;
                protected uint _state; //resume cursor across parks
                protected long _rem, maxStreamBytes = long.MaxValue;

                public int __id => _id;

                ///<summary>Convenience overload — <c>Init(src, maxStreamBytes, int.MinValue, 0)</c>: no dispatch id written (id-less) —
                ///the stream serves an EMBEDDED FIELD data type of an outer pack (the field, not this framer, identifies it).</summary>
                public File Init(string src, long maxStreamBytes) => Init(src, maxStreamBytes, int.MinValue, 0);

                ///<summary>(Re)configure: a built-in direct-file source opened from <paramref name="src"/> for reading + the <c>[S(N)]</c>
                ///cap + dispatch id + id width — the stream serves a dedicated TOP-LEVEL transmittable pack. Payload length taken from the file.</summary>
                public File Init(string src, long maxStreamBytes, int id, int idBytes) => Init(new FileStream(src, FileMode.Open, FileAccess.Read, FileShare.Read), maxStreamBytes, id, idBytes);

                ///<summary>Convenience overload — <c>Init(src, maxStreamBytes, int.MinValue, 0)</c>: no dispatch id written (id-less) —
                ///embedded field. Payload length taken from the SEEKABLE <paramref name="src"/>.</summary>
                public File Init(Stream src, long maxStreamBytes) => Init(src, maxStreamBytes, int.MinValue, 0);

                ///<summary>(Re)configure from a SEEKABLE source: the payload length is taken from <c>src.Length</c>.
                ///A non-seekable stream has no declarable size, so it reaches the primary overload as <c>-1</c> and
                ///throws — pass the size explicitly instead.</summary>
                public File Init(Stream src, long maxStreamBytes, int id, int idBytes) => Init(src, maxStreamBytes, id, idBytes, src.CanSeek? src.Length: -1);

                ///<summary>PRIMARY (re)configuration: a caller-supplied byte source (any <see cref="System.IO.Stream"/>)
                ///+ the <c>[S(N)]</c> cap + dispatch id (<see cref="int.MinValue"/> = id-less: embedded
                ///field) + id width + the total payload length declared up front. A negative <paramref name="size"/> (unknown) throws, as
                ///does a <paramref name="size"/> above <paramref name="maxStreamBytes"/>. Returns <c>this</c> for chaining.</summary>
                public File Init(Stream src, long maxStreamBytes, int id, int idBytes, long size)
                {
                    _id = id;
                    _idBytes = idBytes;
                    this.src = src;
                    src_ = null;
                    if (size < 0)
                        throw new InvalidOperationException("File size unknown: " + size);
                    if (maxStreamBytes < size)
                        throw new InvalidOperationException("File size " + size + " exceeds max " + maxStreamBytes);
                    this.maxStreamBytes = maxStreamBytes;
                    _rem = size;
                    _state = 0;
                    return this;
                }

                ///<summary>Convenience overload — <c>Init(src, maxStreamBytes, int.MinValue, 0, size)</c>: no dispatch id written
                ///(id-less) — embedded field.</summary>
                public File Init(AdHoc.BytesSrc src, long maxStreamBytes, long size) => Init(src, maxStreamBytes, int.MinValue, 0, size);

                ///<summary>PRIMARY (re)configuration from an application-level <see cref="AdHoc.BytesSrc"/> source — a byte producer that
                ///is not a <see cref="System.IO.Stream"/> (e.g. a virtual connection's <c>Internal.BytesSrc</c>) + the <c>[S(N)]</c> cap +
                ///dispatch id (<see cref="int.MinValue"/> = id-less: embedded field) + id width + the total payload length declared up front.
                ///A negative <paramref name="size"/> (unknown) throws, as does a <paramref name="size"/> above
                ///<paramref name="maxStreamBytes"/>.
                ///<para>Such a source has no declarable length of its own — there is no <c>Length</c> to fall back on, which is why
                ///<paramref name="size"/> has no defaulting overload here. Returns <c>this</c> for chaining.</para></summary>
                public File Init(AdHoc.BytesSrc src, long maxStreamBytes, int id, int idBytes, long size)
                {
                    _id = id;
                    _idBytes = idBytes;
                    this.src = null!;
                    src_ = src;
                    if (size < 0)
                        throw new InvalidOperationException("File size unknown: " + size);
                    if (maxStreamBytes < size)
                        throw new InvalidOperationException("File size " + size + " exceeds max " + maxStreamBytes);
                    this.maxStreamBytes = maxStreamBytes;
                    _rem = size;
                    _state = 0;
                    return this;
                }

                ///<summary>
                ///Framework entry. Writes the dispatch id and the varint total-length header through the transmitter's own
                ///retry machinery, then produces exactly <c>_rem</c> payload bytes read DIRECTLY from <see cref="src"/>
                ///(clamped to the remaining count). Closes the source and returns <c>true</c> once the full payload is
                ///written, <c>false</c> to park when the transmit buffer fills.
                ///</summary>
                public virtual bool __get_bytes(Transmitter dst)
                {
                    for (;;)
                        switch (_state)
                        {
                            case 0:
                                if (dst.slot!.state == 0 && _idBytes > 0 && !dst.put_val((uint)_id, _idBytes, _state = dst.slot.state = 1))
                                    return false;
                                goto case 1;
                            case 1:
                                if (!dst.put_varint((ulong)_rem, _state = 2))
                                    return false;
                                goto case 2;
                            case 2:
                                for (int n; 0 < _rem;)
                                {
                                    var room = dst.byte_max - dst.byte_;
                                    if (room == 0)
                                        return false;
                                    if (_rem < room)
                                        room = (int)_rem; //clamp the read to the declared remainder
                                    if (src_ != null)
                                    {
                                        n = src_.Read(dst.buffer!, dst.byte_, room);
                                        //The declared length is the end-authority, so a source that reports EOF (-1) while payload
                                        //is still outstanding can never satisfy it. Parking would stall the pack forever, so fail loudly.
                                        if (n < 0)
                                            throw new InvalidOperationException("File source signalled end of stream with " + _rem + " payload bytes still undelivered.");
                                    }
                                    else
                                        n = src.Read(dst.buffer!, dst.byte_, room);

                                    if (n <= 0)
                                        return false; //nothing produced this turn → park
                                    dst.byte_ += n;
                                    _rem -= n;
                                }

                                close();
                                return true;
                        }
                }

                ///<summary>Close the source and drop the reference — runs at payload completion; teardown code may call it
                ///early so an aborted send doesn't leak the handle. Idempotent.</summary>
                public void close()
                {
                    try
                    {
                        src_?.Close();
                    }
                    catch
                    {
                    }
                    try
                    {
                        src?.Dispose();
                    }
                    catch
                    {
                    }
                    src_ = null;
                    src = null!;
                }
            }
        }

        ///<summary>VirtuallyConnects tunnel machinery: the zero-copy <see cref="Tunnel.Relay"/> (the schema-blind
        ///PATH-host forwarder) and the <see cref="Tunnel.EndPoint"/> bridge bases (tunnel endpoints).</summary>
        public interface Tunnel
        {
            ///<summary>
            ///Chunked-stream relay: forwards one inbound tunnel packet <c>[id][tunnel_id][len][data]…[0]</c> to the
            ///outbound connection that serves its tunnel_id, without parsing the packs inside and without holding the
            ///whole packet.
            ///<para>
            ///<b>Receive side.</b> It installs as the inbound packet's inner <see cref="Receiver.BytesDst"/> and turns every
            ///buffer the transport delivers into a <i>region</i> handed to the transmit side through a one-place slot. A
            ///region that holds the packet's end is copied; one that does not is taken over whole when the transport
            ///allows it (<see cref="Connection.External.swapReceive"/>, raw TCP): the relay becomes the transport's
            ///top-level sink and later buffers arrive at <see cref="Write"/>. A transport that decodes frames inside its
            ///buffer (a WebSocket) cannot hand it over, and then every region is copied.
            ///</para>
            ///<para>
            ///<b>Own framing.</b> The source's chunk headers and terminator are NOT passed through. The scan notes where they
            ///sit in a region ("holes"; the bytes are not moved), and the transmit side writes each region as a chunk of its
            ///own, <c>[len][payload]</c>, stepping over the holes. The reason is failure, not taste: a region ends wherever a
            ///socket read ended — usually inside a source chunk. With the source's framing passed through, an outbound stream
            ///whose source vanishes stops inside a chunk, and the peer parses whatever comes next on its connection as the
            ///rest of that chunk; the only way back to a consistent stream is to close that connection, which on a shared
            ///link (Monitoring → Server) drops every tunnel on it. With its own framing the relay is on a chunk boundary after
            ///every region, so it ends such a packet with <see cref="Transmitter.Chunked.ABORT"/> and the peer resets that one
            ///virtual connection (HTTP/2 RST_STREAM, QUIC RESET_STREAM: the same answer to the same problem). The cost is two
            ///bytes per region; the payload is still copied exactly once, in <see cref="__get_bytes"/>.
            ///</para>
            ///<para>
            ///<b>tunnel_id routing.</b> Many-to-one links carry a fixed-width little-endian <see cref="tunnel_id"/> right
            ///after the pack id; <see cref="__put_bytes"/> reads it (from the bytes the receiver already took with the id
            ///when its id field is wider than the pack id, else from the wire), and <see cref="OutboundSrc.outbound"/>
            ///resolves and enqueues the target. The outbound prefix <c>[id][tunnel_id]</c> is written afresh.
            ///</para>
            ///<para>
            ///<b>Failures.</b> No target, or the target refused the enqueue: the packet is consumed and dropped whole — a
            ///packet ends only between packs (a burst closes when its virtual connection has nothing in flight), so the
            ///peer merely misses whole packs. The target dies holding our pack (<see cref="Close(Transmitter)"/>): the
            ///receive drops the rest of that packet. The source dies mid-packet (<see cref="InboundLost"/>): the transmit
            ///finishes the region it holds and writes ABORT; if nothing of the packet reached the wire yet, it vanishes.
            ///</para>
            ///</summary>
            public class Relay : BytesDst, BytesSrc, Receiver.BytesDst, Transmitter.IDataPass, Transmitter.BytesSrc
            {
                public interface OutboundSrc
                {
                    ///<summary>
                    ///Resolves the outbound connection for <paramref name="tunnel_id"/>: enqueues <paramref name="dst"/> on the
                    ///returned connection's transmitter (the generated <c>sending_put</c>) and may rewrite <c>dst.tunnel_id</c>
                    ///before that. Returns <c>null</c> when there is no live target or the enqueue was refused — the relay
                    ///then drops the current packet.
                    ///</summary>
                    External? outbound(Relay dst, int tunnel_id);
                }

                //--- Transmitter.IDataPass lifecycle ---------------------------------------------------
                public Transmitter.BytesSrc? OnSerializing(Transmitter transmitter) => this;

                public void OnSerialized(Transmitter transmitter, Transmitter.BytesSrc transmitted)
                {
                    //Outbound pack fully serialized → this single instance is free to forward the next
                    //packet. Clear the per-pack transmit state and release the enqueue gate, then wake the inbound
                    //receive so a packet that was parked on the gate (see __put_bytes) can proceed.
                    _prefixDone = false;
                    _enqueued = false;
                    Inbound?.WakeReceive();
                }

                ///<summary>
                ///The OUTBOUND connection is being torn down while this pack is queued or in flight on it. Runs on that
                ///teardown, after its transmit has stopped but concurrently with the INBOUND receive, so it touches only
                ///transmit-local state: the receive owns the parse state and learns of the loss from
                ///<see cref="_outboundLost"/> — it then drops the rest of the current packet and empties the slot.
                ///The flag is raised BEFORE the gate is released, so a receive that passes the gate always sees it.
                ///</summary>
                public void Close(Transmitter transmitter)
                {
                    _txBuf = _txDrained = null;
                    _txLen = _txPayload = _txChunkLeft = 0;
                    _txState = TX_BETWEEN;
                    _prefixDone = false;
                    _outboundLost = true;
                    _enqueued = false;
                    Inbound?.WakeReceive(); //it may be parked on the gate or on the full slot
                }

                ///<summary>
                ///The INBOUND connection died (called from its teardown once no receive runs any more — the receiver's
                ///reset for a packet dispatched by id, the transport for a promoted one). The partly received packet is
                ///abandoned: the parse state is cleared, so a resumed session starts clean at a packet id. If its
                ///outbound pack is queued or in flight it can never be completed, so <see cref="_lostSeq"/> tells the
                ///transmit to end it (see <see cref="__get_bytes"/>).
                ///</summary>
                public void InboundLost()
                {
                    var mid = _outboundResolved || _rxStaged; //the packet's end has not been published yet
                    _scanState = _prefixGot = _chunkLen = _payloadLeft = 0;
                    _tidGot = _overGot = _overread = 0;
                    _outboundResolved = _rxStaged = _drop = false;
                    _rxBuf = _rxSwapBuf = null; //may be the dead transport's buffer, which it returns to its pool
                    if (_enqueued)
                    {
                        if (!mid)
                            return; //the whole packet is published: the transmit finishes it normally
                        //Tagged with the packet's number, not a plain flag: if the outbound dies concurrently the tag goes
                        //stale on its own, instead of ending whatever pack is routed next.
                        _lostSeq = _seq;
                        Outbound?.WakeTransmit();
                    }
                    else
                    {
                        _outboundLost = false;
                        discardSlot();
                    }
                }

                ///<summary>Empties the shared slot: its region was meant for an outbound that will never take it. Only
                ///the receive side or a teardown calls it, when no live transmit can hold the lock for more than a moment.</summary>
                void discardSlot()
                {
                    var spin = new SpinWait();
                    while (Interlocked.CompareExchange(ref _lock, 1, 0) != 0)
                        spin.SpinOnce();
                    _sBuf = null;
                    Volatile.Write(ref _lock, 0);
                }

                const int PREFIX_BYTES = 2; //chunk length prefix width (little-endian).
                //MUST equal the protocol's chunk_length_store_bytes; kept as a local const
                //to stay usable in the hot scan loop — update both together if the width changes.

                External Inbound = null!;         //inbound (source) connection — NEVER null once Init() runs (set there, never cleared); Wake calls in the hot paths need no null check
                External Outbound = null!;        //outbound (target) connection — resolved per packet by outbound(). Non-null in the publish/take/__get_bytes hot paths (they run only AFTER outbound() resolved it to a live target), so those Wake calls need no null check. null while a packet is dropped (see _drop) and before the first packet — Close()/teardown guard accordingly
                OutboundSrc _outboundSrc = null!; //router callback: tunnel_id → outbound External (and it enqueues us)
                int _outId;                       //the full id arg the inbound receiver parsed (low _idBytes = pure pack id, high bits = over-read [tunnel_id][body-lead])
                int _idBytes;                     //PURE pack-id width (bytes), set once in Init
                int _overread;                    //over-read bytes sitting in _outId past the pure id (= src.id_bytes - _idBytes)
                int _overGot;                     //over-read bytes consumed so far for the current packet (0.._overread)

                //--- tunnel_id: parsed from the inbound right after the pack id, re-emitted on the outbound ---------
                int _tidBytes;                       //tunnel_id width on the wire: 0 = one-to-one (no tunnel_id); 1..4 = many-to-one (little-endian)
                int _tidGot;                         //tunnel_id bytes read so far for the current packet (0.._tidBytes)
                bool _outboundResolved;              //outbound() already called for the current packet (tunnel_id fully read)
                volatile bool _enqueued;             //an outbound pack for this instance is queued / in flight → hold the next inbound packet
                bool _prefixDone;                    //[id][tunnel_id] prefix already written for the current outbound pack
                bool _drop;                          //no live target for the current packet → its body is consumed and forwarded nowhere
                readonly byte[] _lead = new byte[1]; //one over-read body byte, fed to scan() while dropping
                volatile bool _outboundLost;         //Close(Transmitter): the outbound died holding our pack → the receive drops the rest of that packet
                volatile int _seq;                   //number of the packet currently routed, bumped by every resolve
                volatile int _lostSeq = -1;          //InboundLost(): _seq of a packet whose inbound died mid-way → the transmit ends its pack

                //=== Lock-free work, try-lock handoff in EXACTLY TWO places ============================
                volatile int _lock; //0 = free, 1 = held

                //A region travels with the positions of the source's framing bytes inside it ("holes": [start, length]
                //pairs relative to the region start, ascending, adjacent ones merged) and its payload size. The hole
                //arrays are swapped between staging, slot and transmit instead of copied; they grow only when a region
                //holds more source chunk boundaries than ever before.

                //--- shared (touched ONLY inside publish()/take(), under _lock) ---
                byte[]? _sBuf;
                int _sOff, _sLen, _sPayload, _sHoleCount;
                bool _sLast, _sAbort;
                int[] _sHoles = new int[8];
                int _sTid;     //the body slot (+ tunnel_id snapshot)
                byte[]? _free; //a free buffer handed back by the transmit

                //--- receive-local (staging; no lock) ---
                byte[]? _rxWork;
                bool _rxStaged;
                byte[]? _rxBuf;
                int _rxOff, _rxLen;
                bool _rxLast;
                bool _rxAbort; //the source itself ended the packet with ABORT: forwarded as such
                int[] _rxHoles = new int[8];
                int _rxHoleCount, _rxHoleBytes;
                int _rxSwap;
                byte[]? _rxSwapBuf;
                //Bytes of the offered window the staged region takes, counted from where it was staged — a count, not a
                //position. A region that failed to publish is offered again from where the receiver stopped, which is
                //where it was staged; but a region made only of bytes over-read into the pack id takes nothing from the
                //window, the receiver reports that window consumed, and the retry arrives with a different one. A stored
                //position would then skip bytes of the new window unscanned and desynchronize the chunk parse.
                int _rxTake;
                int _rxRet;
                //_rxSwap: 0 = no swap (copied), 1 = swapReceive(this,_rxSwapBuf) promote, 2/3 = swapReceive(null,_rxSwapBuf) EOS

                //--- transmit-local (touched only by __get_bytes; no lock) ---
                const int TX_BETWEEN = 0, TX_PREFIX = 1, TX_REGION = 2, TX_END = 3;
                int _txState; //TX_BETWEEN: no region in hand; TX_PREFIX: [id][tunnel_id] due; TX_REGION: a region in hand; TX_END: the terminator due
                byte[]? _txBuf;
                int _txOff, _txLen; //the region in hand: _txBuf[_txOff .. _txOff+_txLen), holes included
                int _txRel;         //next region byte to look at, relative to _txOff
                int _txPayload;     //payload bytes of the region not yet written
                int _txChunkLeft;   //payload bytes still owed to the chunk header already written
                int[] _txHoles = new int[8];
                int _txHoleCount, _txHoleAt;
                int _txEnd; //TX_END writes this: 0 (end) or ABORT
                bool _txLast, _txAbort;
                int _txTid, _txOutId, _txIdBytes, _txTidBytes;
                byte[]? _txDrained; //buffer just drained, handed back to _free at the NEXT take()

                //chunk scan state (persists across buffers)
                int _scanState;   //0 = reading prefix, 1 = in payload
                int _prefixGot;   //prefix bytes accumulated (0..PREFIX_BYTES)
                int _chunkLen;    //current chunk length being decoded
                int _payloadLeft; //payload bytes remaining in the current chunk

                volatile bool _aborted;

                public int __id => _outId; //outbound id

                //parsed tunnel_id; outbound() may rewrite it to reroute.
                public int tunnel_id = 0;

                public Relay Init(int id, int id_bytes, int tunnel_id_bytes, External inbound, OutboundSrc outbound_src)
                {
                    _outId = id;
                    _idBytes = id_bytes;
                    _tidBytes = tunnel_id_bytes;
                    Inbound = inbound;
                    _outboundSrc = outbound_src;
                    return this;
                }

                ///<summary>
                ///Scans <c>b[pos..end)</c> for the end of the chunked body, resuming across calls. Returns the index just past
                ///the terminator if found, else -1. Pure pointer walk, no copy. With <paramref name="regionStart"/> ≥ 0 every
                ///framing byte met (length prefixes, the terminator) is noted as a hole relative to it; -1 notes nothing.
                ///A source that ends its stream with ABORT ends it here too, and the region is marked to forward that.
                ///</summary>
                int scan(byte[] b, int pos, int end, int regionStart)
                {
                    while (pos < end)
                        if (_scanState == 0) //prefix
                        {
                            var from = pos;
                            while (_prefixGot < PREFIX_BYTES && pos < end)
                                _chunkLen |= b[pos++] << (8 * _prefixGot++);
                            if (0 <= regionStart)
                                hole(from - regionStart, pos - from);
                            if (_prefixGot < PREFIX_BYTES)
                                return -1; //prefix straddles the buffer boundary
                            if (_chunkLen == 0 || _chunkLen == Transmitter.Chunked.ABORT)
                            {
                                _rxAbort = _chunkLen != 0;
                                _chunkLen = 0;
                                _prefixGot = 0;
                                _tidGot = 0;
                                _outboundResolved = false;
                                return pos; //EOS: index just after the terminator
                            }

                            _payloadLeft = _chunkLen;
                            _chunkLen = 0;
                            _prefixGot = 0;
                            _scanState = 1;
                        }
                        else //payload
                        {
                            var take = Math.Min(_payloadLeft, end - pos);
                            pos += take;
                            _payloadLeft -= take;
                            if (_payloadLeft == 0)
                                _scanState = 0;
                            else
                                return -1; //payload continues in the next buffer
                        }

                    return -1;
                }

                ///<summary>Notes <paramref name="length"/> framing bytes at <paramref name="at"/> (relative to the region start)
                ///in the region being staged.</summary>
                void hole(int at, int length)
                {
                    if (length == 0)
                        return;
                    _rxHoleBytes += length;
                    var n = _rxHoleCount;
                    if (0 < n && _rxHoles[n * 2 - 2] + _rxHoles[n * 2 - 1] == at) //right after the previous hole: one hole
                    {
                        _rxHoles[n * 2 - 1] += length;
                        return;
                    }

                    if (_rxHoles.Length == n * 2)
                        Array.Resize(ref _rxHoles, n * 4);
                    _rxHoles[n * 2] = at;
                    _rxHoles[n * 2 + 1] = length;
                    _rxHoleCount = n + 1;
                }

                ///<summary>Starts staging a region: no holes, no ABORT seen yet.</summary>
                void stage()
                {
                    _rxHoleCount = _rxHoleBytes = 0;
                    _rxAbort = false;
                }

                ///<summary>
                ///No live target for the current packet (<see cref="OutboundSrc.outbound"/> returned null): consume its chunked
                ///body up to the terminating <c>[0]</c> and forward nothing. A dropped packet is never promoted, so all of its
                ///body keeps arriving here through <see cref="__put_bytes"/>.
                ///</summary>
                bool drop(Receiver src, byte[] b, int pos, int end)
                {
                    while (_overGot < _overread) //body bytes over-read into the id come first
                    {
                        _lead[0] = (byte)((uint)_outId >> ((_idBytes + _overGot++) * 8));
                        if (0 <= scan(_lead, 0, 1, -1))
                            return dropped(src, pos);
                    }

                    var eos = scan(b, pos, end, -1);
                    if (eos < 0)
                    {
                        src.byte_ = end; //the whole buffer is body → consumed, continue with the next one
                        return false;
                    }

                    return dropped(src, eos);
                }

                bool dropped(Receiver src, int pos)
                {
                    _drop = false;
                    src.byte_ = pos;
                    src.slot.dst = null; //tunneling relay: never actor traffic → skip OnReceived
                    return true;
                }

                //--- Receive side ---------------------------------------------------------------------

                ///<summary>First-entry: the deserializer dispatches the first body bytes here. Decides
                ///copy (single-buffer) vs promote-to-swap (multi-buffer).</summary>
                public bool __put_bytes(Receiver src)
                {
                    if (_aborted)
                    {
                        src.byte_ = src.byte_max; //torn down → discard the rest of the body
                        return true;
                    }

                    var b = src.buffer!;
                    //Enqueue gate: hold the NEW packet while the previous outbound pack is queued/in flight.
                    if (!_rxStaged && !_outboundResolved && _enqueued)
                        return false;

                    //Read AFTER the gate: Close(Transmitter) raises it before releasing the gate, so a packet that got
                    //through can never be the lost one mistaken for a fresh start.
                    if (_outboundLost)
                    {
                        _outboundLost = false;
                        discardSlot(); //the dead transmit will never take it
                        if (_rxStaged) //a region already scanned but not published: account for it as its publish would have
                        {
                            _rxStaged = false;
                            _rxBuf = _rxSwapBuf = null;
                            if (_rxLast)
                                return dropped(src, src.byte_ + _rxTake); //it was the packet's end
                            src.byte_ += _rxTake;
                            _drop = true;
                        }
                        else if (_outboundResolved) //the lost packet is still arriving
                            _drop = true;
                    }

                    if (!_rxStaged)
                    {
                        var pos = src.byte_;
                        var end = src.byte_max;
                        //Phase 0 — parse tunnel_id (over-read region of _outId first, then the buffer; straddle-safe).
                        if (!_outboundResolved)
                        {
                            if (_tidGot == 0)
                            {
                                tunnel_id = 0;
                                _overGot = 0;
                                _overread = src.id_bytes - _idBytes;
                            }

                            while (_tidGot < _tidBytes)
                            {
                                int v;
                                if (_overGot < _overread)
                                    v = (int)(((uint)_outId >> ((_idBytes + _overGot++) * 8)) & 0xFF);
                                else if (pos < end)
                                    v = b[pos++];
                                else
                                    break;
                                tunnel_id |= v << (8 * _tidGot++);
                            }

                            src.byte_ = pos;
                            if (_tidGot < _tidBytes)
                                return false; //tunnel_id straddles → resume on the next input
                            //tunnel_id complete → route. The callback may rewrite tunnel_id; it either enqueues us (sending_put) on
                            //the connection it returns, or returns null when there is no live target — then this packet is dropped.
                            _outboundResolved = true;
                            _seq = (_seq + 1) & int.MaxValue; //a new packet: a _lostSeq still around belongs to an older one; never -1
                            _enqueued = true;                 //before outbound()/sending_put → visible to the transmit dequeue
                            Outbound = _outboundSrc.outbound(this, tunnel_id)!;
                            if (Outbound == null)
                            {
                                _enqueued = false; //nothing was queued → no OnSerialized will ever release the gate
                                _drop = true;      //consume this packet's body up to its [0], forward nothing
                            }
                        }

                        if (_drop)
                            return drop(src, b, pos, end);

                        stage();
                        //Over-read body bytes (front of the chunked body pulled into _outId) are isolated into _rxWork and
                        //prepended to the available inbound bytes, then scanned/staged from _rxWork.
                        var leadBody = _overread - _overGot;
                        if (leadBody > 0)
                        {
                            _rxWork ??= ArrayPool<byte>.Shared.Rent(Math.Max(b.Length, 256));
                            for (var k = 0; k < leadBody; k++)
                                _rxWork[k] = (byte)((uint)_outId >> ((_idBytes + _overGot + k) * 8));
                            _overGot += leadBody;

                            var copyB = Math.Min(end - pos, _rxWork.Length - leadBody); //inbound bytes appended after the lead
                            Array.Copy(b, pos, _rxWork, leadBody, copyB);
                            var total = leadBody + copyB;

                            var eos = scan(_rxWork, 0, total, 0); //scan [lead | inbound] in the scratch
                            _rxBuf = _rxWork;
                            _rxOff = 0;
                            _rxSwap = 0;
                            _rxSwapBuf = null;
                            if (eos < 0) //no EOS yet → forward [lead | inbound] as one non-final region
                            {
                                _rxLen = total;
                                _rxLast = false;
                                _rxTake = copyB;
                            }
                            else //EOS within [lead | inbound]
                            {
                                _rxLen = eos;
                                _rxLast = true;
                                var fromB = eos - leadBody; //inbound bytes consumed up to EOS (lead bytes never came from b)
                                if (fromB < 0)
                                    fromB = 0;
                                _rxTake = fromB;
                            }

                            _rxStaged = true;
                        }
                        else
                        {
                            if (pos == end)
                                return false; //body begins in the next buffer

                            //Produce a region into the _rx staging fields. _rxWork = free work buffer (scratch / swap-in).
                            _rxWork ??= ArrayPool<byte>.Shared.Rent(b.Length);
                            var eos = scan(b, pos, end, pos);
                            if (eos < 0 && Inbound.canSwapReceive) //no EOS → large packet → PROMOTE: hand b to the slot, swap _rxWork in as receive buffer
                            {
                                _rxBuf = b;
                                _rxOff = pos;
                                _rxLen = end - pos;
                                _rxLast = false;
                                _rxSwap = 1;
                                _rxSwapBuf = _rxWork;
                                _rxTake = end - pos;
                            }
                            else //copy the region into _rxWork (scratch); the deserializer keeps b. Its end, or b cannot be taken over.
                            {
                                var bodyLen = eos < 0 ? end - pos : eos - pos;
                                if (_rxWork.Length < bodyLen) //too small → return the old scratch first (solely owned here: pre-publish, not shared/swapped)
                                {
                                    ArrayPool<byte>.Shared.Return(_rxWork);
                                    _rxWork = ArrayPool<byte>.Shared.Rent(Math.Max(b.Length, bodyLen));
                                }

                                Array.Copy(b, pos, _rxWork, 0, bodyLen);
                                _rxBuf = _rxWork;
                                _rxOff = 0;
                                _rxLen = bodyLen;
                                _rxLast = 0 <= eos;
                                _rxSwap = 0;
                                _rxSwapBuf = null;
                                _rxTake = bodyLen;
                            }

                            _rxStaged = true;
                        }
                    }

                    //Publish (receive lock site #1). Locked OR slot full ⇒ park + re-drive the transmit (wake-on-defer).
                    if (!publish())
                    {
                        Outbound?.WakeTransmit();
                        return false;
                    }

                    //Published → finalize once: consume FIRST, then rotate the receive buffer, then wake the transmit.
                    _rxStaged = false;
                    src.byte_ += _rxTake;
                    finalizeSwap();
                    var done = _rxSwap != 0 || _rxLast;
                    if (done)
                        src.slot.dst = null; //tunneling relay: never actor traffic → skip OnReceived
                    Outbound?.WakeTransmit();
                    return done; //false ⇒ non-final region forwarded → keep this relay as the slot dst
                }

                ///<summary>Steady-state (after promotion): every inbound buffer arrives here.</summary>
                public int Write(byte[] src, int src_byte, int src_bytes)
                {
                    if (_aborted)
                        return src_bytes;
                    var end = src_byte + src_bytes;
                    if (_outboundLost) //only an unfinished packet is served here, so the lost one is still arriving
                    {
                        _outboundLost = false;
                        discardSlot(); //the dead transmit will never take it
                        _drop = true;
                        if (_rxStaged) //a region already scanned but not published: account for it as its finalize would have
                        {
                            _rxStaged = false;
                            _rxBuf = _rxSwapBuf = null;
                            if (!_rxLast)
                                return _rxRet; //all of it was body: consumed, src stays the receive buffer
                            _drop = false;
                            Inbound.swapReceive(null, src); //it held the end: restore id-dispatched receiving, src (with any trailing) stays
                            return _rxRet;
                        }
                    }

                    if (_drop)
                    {
                        var at = scan(src, src_byte, end, -1);
                        if (at < 0)
                            return src_bytes; //all body → consumed, keep dropping
                        _drop = false;
                        Inbound.swapReceive(null, src); //packet over: restore id-dispatched receiving, src (with any trailing) stays
                        return at - src_byte;
                    }

                    if (!_rxStaged)
                    {
                        stage();
                        _rxWork ??= ArrayPool<byte>.Shared.Rent(src.Length);
                        var eos = scan(src, src_byte, end, src_byte);
                        if (eos < 0) //no EOS → hand the whole region to the slot, swap _rxWork in, keep relaying
                        {
                            _rxBuf = src;
                            _rxOff = src_byte;
                            _rxLen = src_bytes;
                            _rxLast = false;
                            _rxSwap = 1;
                            _rxSwapBuf = _rxWork;
                            _rxRet = src_bytes;
                        }
                        else if (eos == end) //clean EOS at buffer end (no trailing): hold src, restore deserializer into _rxWork
                        {
                            _rxBuf = src;
                            _rxOff = src_byte;
                            _rxLen = eos - src_byte;
                            _rxLast = true;
                            _rxSwap = 2;
                            _rxSwapBuf = _rxWork;
                            _rxRet = src_bytes;
                        }
                        else //EOS mid-buffer: copy body into _rxWork (scratch); src (with the trailing) stays the receive buffer
                        {
                            var bodyLen = eos - src_byte;
                            if (_rxWork.Length < bodyLen) //too small → return the old scratch first (solely owned here: pre-publish, not shared/swapped)
                            {
                                ArrayPool<byte>.Shared.Return(_rxWork);
                                _rxWork = ArrayPool<byte>.Shared.Rent(Math.Max(src.Length, bodyLen));
                            }

                            Array.Copy(src, src_byte, _rxWork, 0, bodyLen);
                            _rxBuf = _rxWork;
                            _rxOff = 0;
                            _rxLen = bodyLen;
                            _rxLast = true;
                            _rxSwap = 3;
                            _rxSwapBuf = src;
                            _rxRet = eos - src_byte; //consume up to eos; transport stashes the trailing
                        }

                        _rxStaged = true;
                    }

                    //Publish (receive lock site #1). Locked OR slot full ⇒ park (return 0) + re-drive the transmit.
                    if (!publish())
                    {
                        Outbound?.WakeTransmit();
                        return 0;
                    }

                    _rxStaged = false;
                    finalizeSwap();
                    Outbound?.WakeTransmit();
                    return _rxRet;
                }

                //RECEIVE lock site #1: publish the staged _rx region into the shared slot and grab a free buffer for next work.
                bool publish()
                {
                    if (Interlocked.CompareExchange(ref _lock, 1, 0) != 0)
                        return false; //lost CAS → defer (no spin)
                    if (_sBuf != null)
                    {
                        Volatile.Write(ref _lock, 0);
                        return false;
                    } //slot full → release & defer

                    _sBuf = _rxBuf;
                    _sOff = _rxOff;
                    _sLen = _rxLen;
                    _sPayload = _rxLen - _rxHoleBytes;
                    (_sHoles, _rxHoles) = (_rxHoles, _sHoles); //the slot was empty: its array is free for the next staging
                    _sHoleCount = _rxHoleCount;
                    _sLast = _rxLast;
                    _sAbort = _rxAbort;
                    _sTid = tunnel_id;
                    var nextWork = _free;
                    _free = null;
                    Volatile.Write(ref _lock, 0);
                    _rxWork = nextWork; //may be null → allocated on the next produce
                    return true;
                }

                //TRANSMIT lock site #2: take the slot region into _tx and hand the previously-drained buffer back to _free.
                bool take()
                {
                    if (Interlocked.CompareExchange(ref _lock, 1, 0) != 0)
                        return false; //lost CAS → defer (no spin)
                    if (_sBuf == null)
                    {
                        Volatile.Write(ref _lock, 0);
                        return false;
                    } //slot empty → release & defer

                    _txBuf = _sBuf;
                    _txOff = _sOff;
                    _txLen = _sLen;
                    _txPayload = _sPayload;
                    (_txHoles, _sHoles) = (_sHoles, _txHoles); //the previous region is done: its array goes back to the slot
                    _txHoleCount = _sHoleCount;
                    _txLast = _sLast;
                    _txAbort = _sAbort;
                    _txTid = _sTid;
                    _txOutId = _outId;
                    _txIdBytes = _idBytes;
                    _txTidBytes = _tidBytes;
                    _sBuf = null;
                    _free = _txDrained;
                    _txDrained = null; //return the previously-drained buffer for the receive to reuse
                    Volatile.Write(ref _lock, 0);
                    _txRel = 0;
                    _txHoleAt = 0;
                    _txChunkLeft = 0;
                    return true;
                }

                //Receive-side finalize after a successful publish(): rotate the receive buffer per the staged plan.
                void finalizeSwap()
                {
                    if (_rxSwap == 1)
                        Inbound.swapReceive(this, _rxSwapBuf!);
                    else if (_rxSwap == 2)
                        Inbound.swapReceive(null, _rxSwapBuf!);
                    else if (_rxSwap == 3)
                        Inbound.swapReceive(null, _rxSwapBuf!);
                }

                //--- Transmit side --------------------------------------------------------------------

                ///<summary>
                ///Drives this instance as its own outbound <see cref="Transmitter.IDataPass"/>: the <c>[id][tunnel_id]</c>
                ///prefix once, then every region as one chunk of its own (split only past <see cref="Transmitter.Chunked.MAX"/>),
                ///then <c>[0]</c> — or <see cref="Transmitter.Chunked.ABORT"/> when the source vanished. Returns <c>false</c> to
                ///park (buffer full, or no region yet) and <c>true</c> once the terminator is written.
                ///</summary>
                public bool __get_bytes(Transmitter dst)
                {
                    if (_aborted)
                        return true; //torn down → retire this outbound pack so the transmitter resumes its own queue
                    var outBuf = dst.buffer!;
                    for (;;)
                        switch (_txState)
                        {
                            case TX_BETWEEN:
                                //No region in hand, so no chunk open: the one place a vanished source is acted upon. A chunk once
                                //begun is always finished first — its bytes are all in memory — so the peer is never left inside one.
                                if (_lostSeq == _seq)
                                {
                                    _lostSeq = -1;
                                    discardSlot(); //a region published for the lost packet: the packet ends here
                                    if (!_prefixDone)
                                        return retire(dst); //nothing of it reached the wire: it simply vanishes
                                    _txEnd = Transmitter.Chunked.ABORT;
                                    _txState = TX_END;
                                    continue;
                                }

                                if (!take()) //locked (receive holds it) OR slot empty ⇒ park
                                {
                                    Inbound?.WakeReceive(); //re-drive the receive: if it lost the CAS to us it must retry publish()
                                    return false;
                                }

                                Inbound?.WakeReceive(); //took a region: slot emptied + a buffer handed back → the receive can produce
                                _txState = _prefixDone ? TX_REGION : TX_PREFIX;
                                continue;

                            case TX_PREFIX: //emit [pure id][tunnel_id] once, from the take()-snapshotted route
                                if (dst.byte_max - dst.byte_ < _txIdBytes + _txTidBytes)
                                    return false; //flush, resume with room (the taken region waits in _txBuf)
                                dst.put_val((ulong)(uint)_txOutId, _txIdBytes);
                                if (_txTidBytes > 0)
                                    dst.put_val((ulong)(uint)_txTid, _txTidBytes);
                                _prefixDone = true;
                                _txState = TX_REGION;
                                continue;

                            case TX_REGION:
                                if (_txChunkLeft == 0)
                                {
                                    if (_txPayload == 0) //the region is written (a region of framing only writes nothing — an empty chunk would read as the end)
                                    {
                                        _txDrained = _txBuf; //hand this buffer back to the receive at the NEXT take()
                                        _txBuf = null;
                                        if (_txLast)
                                        {
                                            _txEnd = _txAbort ? Transmitter.Chunked.ABORT : 0;
                                            _txState = TX_END;
                                        }
                                        else
                                            _txState = TX_BETWEEN;

                                        continue;
                                    }

                                    if (dst.byte_max - dst.byte_ < PREFIX_BYTES + 1)
                                        return false; //room for our chunk header and at least one byte of it
                                    _txChunkLeft = Math.Min(_txPayload, Transmitter.Chunked.MAX);
                                    dst.put_val((ulong)_txChunkLeft, PREFIX_BYTES);
                                }

                                while (0 < _txChunkLeft) //copy payload, stepping over the source's framing
                                {
                                    if (dst.byte_max <= dst.byte_)
                                        return false; //outbound buffer full → flush, resume on next turn
                                    while (_txHoleAt < _txHoleCount && _txHoles[_txHoleAt * 2] == _txRel)
                                        _txRel += _txHoles[_txHoleAt++ * 2 + 1];
                                    var stop = _txHoleAt < _txHoleCount ? _txHoles[_txHoleAt * 2] : _txLen;
                                    var n = Math.Min(Math.Min(stop - _txRel, _txChunkLeft), dst.byte_max - dst.byte_);
                                    Array.Copy(_txBuf!, _txOff + _txRel, outBuf, dst.byte_, n);
                                    dst.byte_ += n;
                                    _txRel += n;
                                    _txChunkLeft -= n;
                                    _txPayload -= n;
                                }

                                continue;

                            default: //TX_END: [0] ends the packet, ABORT ends it as void
                                if (dst.byte_max - dst.byte_ < PREFIX_BYTES)
                                    return false;
                                dst.put_val((ulong)_txEnd, PREFIX_BYTES);
                                return retire(dst);
                        }
                }

                ///<summary>Retires this outbound pack: the transmitter then runs <see cref="OnSerialized"/>, which opens the gate.</summary>
                bool retire(Transmitter dst)
                {
                    _txState = TX_BETWEEN;
                    dst.slot!.src = null; //tunneling relay: never actor traffic → skip the transmitter's pack-level handling
                    return true;
                }

                ///<summary>Unused in the copy relay (the body is copied through <see cref="__get_bytes"/> into the outbound
                ///transmitter's own buffer). Retained only to satisfy <see cref="Transmitter.BytesSrc"/>.</summary>
                public int Read(byte[] dst, int dst_byte, int dst_bytes) => _aborted ? -1 : 0;

                //--- Lifecycle (channel interfaces) ---------------------------------------------------

                public bool isOpen() => !_aborted;

                public void Close()
                {
                    _aborted = true;
                    Outbound?.WakeTransmit(); //resolved lazily by outbound(); may be null before the first packet
                    Inbound?.WakeReceive();
                }
            }

            ///<summary>
            ///Tunnel-endpoint bridge base: the virtual <see cref="Connection.External"/> a virtual connection (vconn) is
            ///built on (<see cref="Internal"/> == vconn), enqueued on the physical transmitter as its own
            ///<see cref="Transmitter.IDataPass"/>. A concrete subclass supplies <see cref="WakeTransmit"/> (enqueue a
            ///fresh outbound burst once per burst) and <see cref="OnSerializing"/> (resolve the
            ///<see cref="Transmitter.BytesSrc"/> that gets serialized — normally a tunnel-armed
            ///<see cref="Transmitter.Chunked"/> over this endpoint's outbound bytes). <see cref="inUse"/> is the
            ///single-enqueue gate, cleared by <see cref="OnSerialized"/> / <see cref="Close(Transmitter)"/>.
            ///</summary>
            public abstract class EndPoint : External, Transmitter.IDataPass
            {
                public int tunnel_id;          //this endpoint's tunnel_id — also what Id and the framing prefix use
                protected Internal? _internal; //underscore-prefixed: `internal` is a C# keyword. Exposed as the Internal property below
                protected int receiveTimeout = int.MaxValue;
                protected int transmitTimeout = int.MaxValue;
                protected bool inUse; //an outbound pack is queued / in flight for this endpoint

                //The External surface below is nothing but properties over the protected backing fields above, so a
                //subclass may read and write exactly the same state directly.
                //A tunnel endpoint owns no slot in a host registry.
                public int index() => 0;

                //On a virtual link the tunnel id is the identity of the far end, and the framing prefix reads
                //the same field.
                public int id
                {
                    get => tunnel_id;
                    set => tunnel_id = value;
                }

                public int ReceiveTimeout
                {
                    get => receiveTimeout;
                    set => receiveTimeout = value;
                }

                public int TransmitTimeout
                {
                    get => transmitTimeout;
                    set => transmitTimeout = value;
                }

                public bool IsOpen => true;

                public void Close() {}

                public void Abort() {}

                public Internal Internal
                {
                    get => _internal!;
                    set => _internal = value;
                }

                ///<summary>Enqueue this endpoint on the physical transmitter (once) so its turn pulls
                ///<see cref="OnSerializing"/>. Application/transport-specific.</summary>
                public abstract void WakeTransmit();

                ///<summary>Called when this endpoint is dequeued for serialization: return the
                ///<see cref="Transmitter.BytesSrc"/> to serialize (normally a tunnel-armed
                ///<see cref="Transmitter.Chunked"/>), or <c>null</c> to skip this turn.</summary>
                public abstract Transmitter.BytesSrc? OnSerializing(Transmitter transmitter);

                public virtual void OnSerialized(Transmitter transmitter, Transmitter.BytesSrc transmitted) { inUse = false; }

                ///<summary>
                ///The physical link died while this endpoint's burst was queued or in flight on it. What the burst had
                ///already framed is gone with the link, and the peer abandons the virtual connection's partial pack (its
                ///receiver resets with the link). The pack still in flight on <see cref="Internal"/>'s transmitter is
                ///therefore dropped too — see <see cref="Transmitter.Abandon"/> — so the next burst starts at a pack
                ///boundary. A burst ends only between packs, so a burst that was merely queued finds nothing to drop.
                ///Dropped BEFORE the gate opens: a wake that slips in afterwards may start a burst at once.
                ///</summary>
                public virtual void Close(Transmitter transmitter)
                {
                    (_internal?.BytesSrc as Transmitter)?.Abandon();
                    inUse = false;
                }

                public EndPoint Init(int tunnel_id)
                {
                    this.tunnel_id = tunnel_id; //single source of truth — also what Id and the framing prefix use
                    return this;
                }
            }
        }
    }

    ///<summary>
    ///Transform-chain LEAF for a <c>string</c> field in the <c>AdHoc.varint</c> text codec — the PREFIX-LESS
    ///<c>[varint characters…]</c> wire that <see cref="Connection.Transmitter.put_str"/> and
    ///<see cref="Connection.Receiver.try_get_str"/> produce: no character count, the string simply ends WITH
    ///the enclosing stream (the chain's framer sees the terminator and finalizes the reception in its
    ///<c>[0]</c>-terminator branch). Emitted/consumed INSIDE a chain: <c>leaf → stages → chunked root</c>.
    ///Embed it with the machinery every chain leaf uses — <c>datatype(chain_id, leaf, next_case)</c> — exactly
    ///as a pack-typed leaf embeds itself.
    ///<para>
    ///Truly STATELESS — <see cref="ONE"/> serves every connection and every field concurrently, because every piece
    ///of working state already lives in the machine driving it. A park inside <c>put_str</c>/<c>try_get_str</c> is
    ///completed BY THIS LEAF (the parked-resume branch inlines the <c>case STR</c>/<c>case STR_RAW</c> body),
    ///because inside a chain the delivery can reach the leaf directly, bypassing the mode dispatcher — whose
    ///<c>case STR</c>/<c>case STR_RAW</c>/<c>case STR_UTF8</c>
    ///therefore SKIP a leaf park (<c>slot.state == (uint)bit</c>) so the same bytes are never processed twice.
    ///The per-use inputs ride machine registers that are otherwise
    ///idle for the whole span of a string transfer:
    ///<list type="bullet">
    ///<item>TRANSMIT — the source string is staged in <see cref="str"/> by <see cref="Connection.Transmitter.put(string,bool,uint)"/>;
    ///content produced in pieces streams fragment-by-fragment via <see cref="Connection.Transmitter.strs"/>
    ///(the fragments concatenate on the wire into ONE string — bit-identical to sending the pre-concatenated whole).</item>
    ///<item>RECEIVE — the character ceiling (<c>[D(+N)]</c>) is staged in <see cref="bits"/> by
    ///<see cref="Connection.Receiver.try_get_string(uint,bool,int)"/>; the decoded string is left in <see cref="str"/>, where the
    ///field's code collects it with <see cref="Connection.Receiver.get_string"/> after the chain completes.</item>
    ///</list>
    ///</para>
    ///<para>
    ///<b>Park discriminator.</b> The field's own retry case rides <see cref="bit"/> as its COMPLEMENT
    ///(<c>bit == ~get_string_case</c>): seeded by the stagers and re-seeded by EVERY string primitive at entry —
    ///plain fields included — so it is never stale. A plain field's park therefore always leaves
    ///<c>slot.state == case</c> with <c>bit == ~case</c> (never equal); only this leaf's FIRST park flips the pair
    ///into lock-step (the primitive's park stamps <c>slot.state = case</c>; the leaf then just flips
    ///<c>bit = ~bit</c>), making <c>slot.state == (uint)bit</c> hold exactly
    ///while a chain-leaf string park is in flight — a collision-free test, since a case value is unique within its
    ///pack's switch and a chain REUSES the slot it was armed on (the leaf cannot assume a zeroed state).
    ///</para>
    ///<para>
    ///These leaves may stay SINGLETONS for one reason: a string leaf is only ever a chain leaf, identified by the
    ///FIELD that armed it, so it never has to answer <c>__id</c> with a real value. A leaf that can be a TOP-LEVEL
    ///pack does have to, and no shared instance can — such a leaf must be a per-arming instance. A byte-stream leaf
    ///also needs no park discriminator at all: it parks without setting <see cref="mode"/>, so it never reaches
    ///those dispatcher arms.
    ///</para>
    ///</summary>
    public sealed class StringStream : Connection.Receiver.BytesDst, Connection.Transmitter.BytesSrc
    {
        ///<summary>The shared instance — the class carries no state, so one is all there ever is.</summary>
        public static readonly StringStream ONE = new();

        StringStream() {}

        ///<summary>Id-less: a chain leaf is identified by the FIELD that armed the chain, never dispatched by id.</summary>
        public int __id => int.MinValue;

        public bool __put_bytes(Connection.Receiver src)
        {
            if (src.slot!.state == (uint)src.bit)
                //parked resume — in a chain the delivery can reach this leaf directly, bypassing the receiver's
                //mode dispatcher (whose case STR_RAW SKIPS this park — see there). getting_chars resumes its own
                //split-char state from u8 / bytes_left and, with no count, never self-completes: the string ends
                //WITH the stream, finalized by the framer's [0]-terminator branch (see Chunked).
                return src.getting_chars(int.MaxValue);

            //First entry — no park yet (bit == ~case, seeded by the try_get_string(max_chars, utf, case) stager).
            src.try_get_str(src.bits, ~src.bit); //always parks: a prefix-less string ends only with the stream
            src.bit = ~src.bit;                  //park → flip: try_get_str's park already stamped slot.state = case, so from here on slot.state == (uint)bit
            return false;
        }

        public bool __get_bytes(Connection.Transmitter dst)
        {
            if (dst.slot!.state != (uint)dst.bit) //first entry — no park yet (bit == ~case, seeded by the put(src, utf, case) stager)
            {
                if (!dst.put_str(dst.str!, (uint)~dst.bit))
                {
                    dst.bit = ~dst.bit; //park → flip: put_str's park already stamped slot.state = case, so from here on slot.state == (uint)bit
                    return false;
                }
            }
            else
            { //Parked resume — the case STR body runs HERE (the transmitter's mode dispatcher SKIPS this park).
                //No length phase on this wire: the pending varint is always a (partial) character.
                if (!dst.varint())
                    return false;

                while (dst.u4 < dst.str!.Length)
                    if (!dst.varint(dst.str[(int)dst.u4++]))
                        return false;
            }

            //The current fragment is out. Streaming content produced in pieces? Pull fragment after fragment
            //from the supplier — they concatenate ON THE WIRE (no prefix, no separator: just more characters
            //of the SAME string). A park inside put_str stamps slot.state = the passed case and the flip locks
            //slot.state == (uint)bit again, so the resume lands in the parked branch above and, once the
            //fragment completes, falls back into this pull loop.
            if (dst.strs != null)
            {
                for (string? s; (s = dst.strs()) != null;)
                    if (!dst.put_str(s, (uint)~dst.bit))
                    {
                        dst.bit = ~dst.bit; //park → flip — same lock-step as above
                        return false;
                    }
                dst.strs = null; //drained — the wire string ends with this fragment
            }
            dst.str = null; //release the staged source
            return true;
        }
    }

    ///<summary>
    ///The <see cref="StringStream"/> leaf over <b>UTF-8</b>: the PREFIX-LESS <c>[UTF-8 bytes]</c> wire —
    ///exactly what <see cref="Connection.Transmitter.put_utf"/> and <see cref="Connection.Receiver.try_get_utf"/>
    ///produce: no character count, the string simply ends WITH the enclosing stream (the chain's framer sees
    ///the terminator and finalizes the reception in its <c>[0]</c>-terminator branch). Emitted/consumed INSIDE
    ///a chain (the <c>[Zstd] ToStream&lt;E, string&gt;</c> case: the UTF-8 leaf is compressed under the chunked
    ///root on the streamed path). Same stateless singleton contract and the same register staging as
    ///<see cref="StringStream"/> — see there for the mechanics.
    ///<para>
    ///The codec's contract carries over unchanged: the TRANSMIT side does not validate — well-formed UTF-16
    ///(no unpaired surrogates) is the caller's obligation, see <c>put_utf</c>'s CONTRACT; malformed UTF-8 on
    ///the receive side is reported through <c>error_handler</c> as <c>OnError.BYTES_DISTORTION</c> with U+FFFD
    ///substituted — decoding stays deterministic and always terminates at the stream's end.
    ///</para>
    ///</summary>
    public sealed class UTFStream : Connection.Receiver.BytesDst, Connection.Transmitter.BytesSrc
    {
        ///<summary>The shared instance — the class carries no state, so one is all there ever is.</summary>
        public static readonly UTFStream ONE = new();

        UTFStream() {}

        ///<summary>Id-less: a chain leaf is identified by the FIELD that armed the chain, never dispatched by id.</summary>
        public int __id => int.MinValue;

        public bool __put_bytes(Connection.Receiver src)
        {
            if (src.slot!.state == (uint)src.bit)
                //parked resume — in a chain the delivery can reach this leaf directly, bypassing the receiver's
                //mode dispatcher (whose case STR_UTF8 SKIPS this park — see there). getting_string_utf resumes
                //its own mid-sequence state from u8 / bytes_left and never self-completes: the string ends WITH
                //the stream, finalized by the framer's [0]-terminator branch (see Chunked).
                return src.getting_string_utf();

            //First entry — no park yet (bit == ~case, seeded by the try_get_string(max_chars, utf, case) stager).
            src.try_get_utf(src.bits, ~src.bit); //always parks: a prefix-less string ends only with the stream
            src.bit = ~src.bit;                  //park → flip: try_get_utf's park already stamped slot.state = case, so from here on slot.state == (uint)bit
            return false;
        }

        public bool __get_bytes(Connection.Transmitter dst)
        {
            if (dst.slot!.state != (uint)dst.bit) //first entry — no park yet (bit == ~case, seeded by the put(src, utf, case) stager)
            {
                if (!dst.put_utf(dst.str!, (uint)~dst.bit))
                {
                    dst.bit = ~dst.bit; //park → flip: put_utf's park already stamped slot.state = case, so from here on slot.state == (uint)bit
                    return false;
                }
            }
            else
            { //Parked resume — the case STR_UTF8 body runs HERE (the transmitter's mode dispatcher SKIPS this park).
                //No length phase on this wire — a park always stages char-phase state (split-sequence bytes in
                //u8_ / bytes_left), which putting_utf resumes itself.
                if (!dst.putting_utf())
                    return false;
            }

            //The current fragment is out. Streaming content produced in pieces? Pull fragment after fragment
            //from the supplier — they concatenate ON THE WIRE (no prefix, no separator: just more UTF-8 bytes
            //of the SAME string). put_utf's CONTRACT applies to EACH fragment: well-formed UTF-16, a surrogate
            //pair never split across fragments. Park/flip keeps slot.state == (uint)bit, so the resume lands in
            //the parked branch above and, once the fragment completes, falls back into this pull loop.
            if (dst.strs != null)
            {
                for (string? s; (s = dst.strs()) != null;)
                    if (!dst.put_utf(s, (uint)~dst.bit))
                    {
                        dst.bit = ~dst.bit; //park → flip — same lock-step as above
                        return false;
                    }
                dst.strs = null; //drained — the wire string ends with this fragment
            }
            dst.str = null; //release the staged source (put_utf already cleared it — kept for symmetry)
            return true;
        }
    }

    ///<summary>
    ///The "mode" sentinels of the receive/transmit state machine. A primitive read or write is attempted
    ///directly against <see cref="buffer"/>; if the buffer runs out mid-value, the slot's state records the
    ///resume point and <see cref="mode"/> is set to one of these to record WHAT kind of value is half-assembled.
    ///On the next buffer fill the dispatcher picks the partial value back up. <see cref="OK"/> means "nothing
    ///pending — proceed to the next field"; <see cref="RETRY"/> is the generic "need more bytes, resume at the
    ///saved state". The values form a contiguous block from <see cref="OK"/> so the whole set stays clear of any
    ///real field index.
    ///</summary>
    internal const uint OK = int.MaxValue, //Idle / done: nothing mid-assembly; advance to the next field. Also the success return of a write.
        STR = OK - 100,                    //Mid-string: assembling a string (varint char count, then the characters).
        STR_UTF8 = STR - 1,                //Mid-string over UTF-8: assembling a string (varint char count, then the characters as raw UTF-8 bytes).
        RETRY = STR + 1,                   //Generic "need more bytes": resume the half-finished step at the slot's saved state.
        VAL4 = RETRY + 1,                  //Mid fixed 4-byte value: raw 32-bit payload (e.g. float / fixed int) gathered into u4.
        VAL8 = VAL4 + 1,                   //Mid fixed 8-byte value: raw 64-bit payload (e.g. double / fixed long) gathered into u8.
        INT1 = VAL8 + 1,                   //Mid 1-byte integer: one wire byte to be sign-extended into u8.
        INT2 = INT1 + 1,                   //Mid 2-byte integer: two wire bytes to be sign-extended into u8.
        INT4 = INT2 + 1,                   //Mid 4-byte integer: four wire bytes to be sign-extended into u8.
        LEN0 = INT4 + 1,                   //Mid collection length stored in 0 bytes (length fixed/implicit; no bytes read).
        LEN1 = LEN0 + 1,                   //Mid collection length stored in 1 byte.
        LEN2 = LEN1 + 1,                   //Mid collection length stored in 2 bytes.
        BITS = LEN2 + 1,                   //Mid bit-field: gathering packed bits into the `bits` accumulator.
        BITS_BYTES = BITS + 1,             //Mid bit-field followed by byte-aligned data (bits first, then bytes).
        VARINT = BITS_BYTES + 1,           //Mid Base_-128 varint: gathering a variable-length integer one continuation byte at a time.
        STREAM_PACK = VARINT + 1,          //Parked at a streamed-datatype boundary: the next drive routes into unpark() to re-frame the chained pack (see streaming_mode).
        STR_RAW = STREAM_PACK + 1;         //Mid PREFIX-LESS string: varint characters with no declared count — the string ends WITH the enclosing stream, finalized by the framer's [0]-terminator branch (see Receiver.Chunked).

    ///<summary>
    ///Number of valid bits currently held in the <see cref="bits"/> accumulator (the bit cursor for packed
    ///bit-field reads/writes); ranges from 0 to 7.
    ///</summary>
    protected int bit;

    ///<summary>
    ///The string currently being assembled from the stream (receive) or fed to the stream (transmit).
    ///</summary>
    public string? str;

    ///<summary>
    ///Bit accumulator: packed bit-fields are shifted in/out here, <see cref="bit"/> bits at a time, before they
    ///spill to or from whole bytes in <see cref="buffer"/>.
    ///</summary>
    public uint bits;

    ///<summary>
    ///The single reusable working buffer through which all bytes flow. Its size, not the pack size, bounds
    ///resident memory; it is borrowed for the duration of a Read/Write call and released on return.
    ///</summary>
    public byte[]? buffer;

    ///<summary>
    ///Read/write cursor: index of the next byte to process in <see cref="buffer"/>.
    ///</summary>
    public int byte_;

    ///<summary>
    ///Exclusive upper bound for access into <see cref="buffer"/> — bytes <c>[<see cref="byte_"/>..<see cref="byte_max"/>)</c>
    ///are available this turn. See <see cref="remaining"/>.
    ///</summary>
    public int byte_max;

    ///<summary>
    ///The size of the window an abstract pack is handed for a one-byte array (see <see cref="window"/>). One at a time -
    ///the pack returns before the codec goes on - so one register is enough.
    ///</summary>
    protected int window_bytes;

    ///<summary>
    ///Opens a window of the buffer for up to <paramref name="bytes"/> bytes of a one-byte array - as many as the buffer
    ///holds (to receive) or takes (to send) now, from the cursor. An abstract pack reads or writes the span the way that
    ///suits it; the codec closes the window with <c>window_done</c>, which moves the cursor past it.
    ///</summary>
    public Span<byte> window(int bytes) => buffer!.AsSpan(byte_, window_bytes = Math.Min(bytes, remaining));

    ///<summary>Closes the window <see cref="window"/> opened: the cursor past it.</summary>
    ///<returns>the bytes the window held - the codec moves its index by them.</returns>
    protected int window_close()
    {
        byte_ += window_bytes;
        return window_bytes;
    }

    //`bytes` (1..8) little-endian bytes at `pos` as a ulong: one read while 8 bytes are in the array - the bytes past
    //`bytes` are masked off
    internal static ulong load(byte[] buf, int pos, int bytes)
    {
        if (pos + 8 <= buf.Length)
        {
            var v = System.Buffers.Binary.BinaryPrimitives.ReadUInt64LittleEndian(buf.AsSpan(pos));
            return bytes == 8 ? v : v & (1UL << (bytes << 3)) - 1;
        }
        var u = 0UL;
        for (var i = 0; i < bytes; i++)
            u |= (ulong)buf[pos + i] << (i << 3);
        return u;
    }

    //the `bytes` (1..8) lowest bytes of `v` little-endian at `pos`: one write while 8 bytes fit before `max` - the bytes
    //past `bytes` are behind the position the caller moves to, the stream overwrites them; nothing is written past `max`
    internal static void store(byte[] buf, int pos, ulong v, int bytes, int max)
    {
        if (pos + 8 <= max)
            System.Buffers.Binary.BinaryPrimitives.WriteUInt64LittleEndian(buf.AsSpan(pos), v);
        else
            for (var i = 0; i < bytes; i++, v >>= 8)
                buf[pos + i] = (byte)v;
    }

    ///<summary>The code of one bit item - already masked - as the item's type: what <c>get_bits&lt;T&gt;</c> gives for it.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static T bits_as<T>(ulong code)
    {
        var u = (uint)code;
        return Unsafe.As<uint, T>(ref u);
    }

    ///<summary>
    ///The state-machine sentinel describing what value, if any, is mid-assembly when the buffer drained.
    ///See the <see cref="OK"/>/<see cref="RETRY"/>/<see cref="VARINT"/>/… constants above.
    ///</summary>
    public uint mode;

    ///<summary>
    ///32-bit staging register: holds the value of a 4-byte read/write (and the running varint result) while it
    ///is assembled from or emitted to the buffer.
    ///</summary>
    internal uint u4;

    ///<summary>
    ///64-bit staging register: holds the value of an 8-byte read/write, the sign-extended INTn result, and
    ///varint accumulation.
    ///</summary>
    public ulong u8;

    ///<summary>
    ///Secondary 64-bit staging register, used when one operation needs two values in flight at once (e.g. a
    ///length/flag alongside the main value, or string-decode bookkeeping).
    ///</summary>
    public ulong u8_;

    ///<summary>
    ///Running byte offset within the current pack/stream payload (used by streaming and copy hooks).
    ///</summary>
    public ulong stream_byte;

    ///<summary>
    ///Gets the value currently stored in the `u8` buffer, reinterpreted as type `T`.
    ///This is an unsafe cast and assumes `T` is compatible with an 8-byte representation.
    ///</summary>
    ///<typeparam name="T">The type to reinterpret the `u8` buffer as.</typeparam>
    ///<returns>The value from `u8` cast to type `T`.</returns>
    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    public T get8<T>() => Unsafe.As<ulong, T>(ref u8);

    ///<summary>Bytes still to transfer to finish the current multi-byte value (counts down as the buffer is consumed).</summary>
    int bytes_left;

    ///<summary>Total width in bytes of the current multi-byte value; with <see cref="bytes_left"/> it gives the byte offset already filled, so a resumed read shifts each byte into the right position.</summary>
    int bytes_max;

    ///<summary>
    ///Gets the number of bytes remaining in the `buffer` from the current `byte_` position to `byte_max`.
    ///</summary>
    public int remaining => byte_max - byte_;

    ///<summary>
    ///The bytes of a one-byte array field, for the block copy the generated code does instead of a byte-by-byte loop
    ///(<see cref="Connection.Transmitter.put(ReadOnlySpan{byte}, int, int, uint)"/>,
    ///<see cref="Connection.Receiver.get_bytes(Span{byte}, int, int, uint)"/>). One name for every holder of one-byte
    ///items - <c>byte</c>, <c>sbyte</c>, a one-byte enum, in an array or a list - so the generated code does not depend
    ///on which one the field has.
    ///</summary>
    ///<summary>
    ///Copies whole elements of <paramref name="width"/> bytes between the wire (little-endian) and a holder's memory. On a
    ///little-endian host - every host .NET runs on in practice - the two are the same bytes: one memcpy. Elsewhere each
    ///element is reversed on the way.
    ///</summary>
    public static void copy_le(ReadOnlySpan<byte> src, Span<byte> dst, int width)
    {
        if (BitConverter.IsLittleEndian || width == 1)
        {
            src.CopyTo(dst);
            return;
        }
        for (var i = 0; i < src.Length; i += width)
            for (var j = 0; j < width; j++)
                dst[i + j] = src[i + width - 1 - j];
    }

    public static Span<byte> bytes<T>(T[] src)
        where T : unmanaged => MemoryMarshal.AsBytes(src.AsSpan());

    ///<inheritdoc cref="bytes{T}(T[])"/>
    public static Span<byte> bytes<T>(List<T> src)
        where T : unmanaged => MemoryMarshal.AsBytes(CollectionsMarshal.AsSpan(src));

    ///<summary>
    ///A list being received: grown to <paramref name="count"/> items first, so the block lands in place. The list is
    ///created for exactly that many, so it does not reallocate; on a resumed call the count is already there.
    ///</summary>
    public static Span<byte> bytes<T>(List<T> src, int count)
        where T : unmanaged
    {
        CollectionsMarshal.SetCount(src, count);
        return MemoryMarshal.AsBytes(CollectionsMarshal.AsSpan(src));
    }

    ///<summary>
    ///Resizes an array to a new length. If the array is expanded, new elements are filled with `fill_value`.
    ///If the array is shrunk, elements are truncated. If lengths are equal, the original array is returned.
    ///</summary>
    ///<typeparam name="T">The type of elements in the array.</typeparam>
    ///<param name="src">The source array to resize.</param>
    ///<param name="new_length">The desired new length of the array.</param>
    ///<param name="fill_value">The value to use for newly added elements if the array is expanded.</param>
    ///<returns>The resized array. This may be the original array instance if `new_length` matches the original length, or a new array instance if `Array.Resize` reallocates.</returns>
    public static T[] Resize<T>(T[] src, int new_length, T fill_value)
    {
        var len = src.Length;
        if (len == new_length)
            return src;

        Array.Resize(ref src, new_length);
        if (len < new_length)
            Array.Fill(src, fill_value, len, new_length - len);
        return src;
    }

    ///<summary>
    ///Resizes a `List<T>` to a new length. If the list is expanded, new elements are added with `fillValue`.
    ///If the list is shrunk, elements are removed from the end.
    ///</summary>
    ///<typeparam name="T">The type of elements in the list.</typeparam>
    ///<param name="list">The list to resize.</param>
    ///<param name="newLength">The desired new length of the list.</param>
    ///<param name="fillValue">The value to use for newly added elements if the list is expanded.</param>
    ///<returns>The original list instance, resized.</returns>
    public static List<T> Resize<T>(List<T> list, int newLength, T fillValue)
    {
        if (list.Count < newLength)
            while (list.Count < newLength)
                list.Add(fillValue);
        else
            list.RemoveRange(newLength, list.Count - newLength);

        return list;
    }

    ///<summary>
    ///Resizes the specified `IList<T>` to the new length.
    ///If `newLength` is greater than the current count, the list is expanded and new elements are filled with `fillValue`.
    ///If `newLength` is less than the current count, the list is truncated.
    ///This method handles `T[]` and `List<T>` efficiently, and provides a generic fallback for other `IList<T>` implementations.
    ///</summary>
    ///<typeparam name="T">The type of elements in the list.</typeparam>
    ///<param name="list">The list to resize.</param>
    ///<param name="newLength">The desired length of the list.</param>
    ///<param name="fillValue">The value to use for filling the list if it is expanded.</param>
    ///<returns>The resized list. This may be a new instance if `list` was an array and resizing occurred, or the original instance for other `IList<T>` types.</returns>
    public static IList<T> Resize<T>(IList<T> list, int newLength, T fillValue)
    {
        switch (list)
        {
            case T[] array:
                return Resize(array, newLength, fillValue);

            case List<T> list_:
                return Resize(list_, newLength, fillValue);

            default:
                //If the list is neither an array nor a List<T>, handle the resizing manually
                if (list.Count < newLength)
                    while (list.Count < newLength)
                        list.Add(fillValue);
                else
                    while (list.Count > newLength)
                        list.RemoveAt(list.Count - 1);

                return list;
        }
    }

    ///<summary>
    ///Converts an `IList<T>` to a `List<T>`, taking at most `max` elements from the source.
    ///</summary>
    ///<typeparam name="T">The type of elements in the list.</typeparam>
    ///<param name="src">The source `IList<T>`.</param>
    ///<param name="max">The maximum number of elements to include in the new list.</param>
    ///<returns>A new `List<T>` containing elements from `src`, truncated or copied entirely based on `max`.</returns>
    public static List<T> toList<T>(IList<T> src, int max)
    {
        var ret = new List<T>(max);

        if (max < src.Count)
            for (var i = 0; i < max; i++)
                ret.Add(src[i]);
        else
            ret.AddRange(src);

        return ret;
    }

    ///<summary>
    ///Creates a new array of a specified size. If `fill` is not the default value for type `T`,
    ///the array is filled with `fill`. Otherwise, it's returned with default-initialized elements
    ///(which is the standard behavior for `new T[size]`).
    ///</summary>
    ///<typeparam name="T">The type of elements in the array.</typeparam>
    ///<param name="fill">The value to fill the array with if it's not the default for `T`.</param>
    ///<param name="size">The size of the array to create.</param>
    ///<returns>A new array of the specified size, potentially filled with `fill`.</returns>
    public static T[] sizeArray<T>(T fill, int size)
    {
        var ret = new T[size];
        //Only fill the array if fill is not the default value for the type (e.g., 0 for integers, null for reference types)
        if (EqualityComparer<T>.Default.Equals(fill, default))
            return ret;

        //Fill the array with the specified fill value
        Array.Fill(ret, fill);
        return ret;
    }

    ///<summary>
    ///Creates a new `List<T>` of a specified size, filling it with the given `fill` value.
    ///</summary>
    ///<typeparam name="T">The type of elements in the list.</typeparam>
    ///<param name="fill">The value to fill the list with.</param>
    ///<param name="size">The desired number of elements in the list.</param>
    ///<returns>A new `List<T>` of size `size`, with all elements initialized to `fill`.</returns>
    public static List<T> sizeList<T>(T fill, int size)
    {
        var ret = new List<T>(size);

        while (-1 < --size)
            ret.Add(fill);
        return ret;
    }
#region CRC
    ///<summary>
    ///Length of the CRC checksum in bytes. Currently 2 bytes for CRC16.
    ///</summary>
    const int CRC_LEN_BYTES = 2; //CRC len in bytes

    ///<summary>
    ///Nibble lookup table for CRC-16/CCITT (polynomial 0x1021, the XMODEM variant). Only 16 entries — one per
    ///4-bit nibble — rather than the usual 256-entry byte table, so each input byte is folded in two steps
    ///(high nibble then low nibble) by <see cref="crc16"/>: a second lookup buys a 16x smaller, cache-friendly table.
    ///</summary>
    static readonly ushort[] tab = { 0, 4129, 8258, 12387, 16516, 20645, 24774, 28903, 33032, 37161, 41290, 45419, 49548, 53677, 57806, 61935 };

    ///<summary>
    ///Calculates CRC16 for a given byte, updating an existing CRC value.
    ///This implementation is equivalent to the CRC-16/XMODEM variant.
    ///(Reference: Similar to Redis crc16: https://github.com/redis/redis/blob/unstable/src/crc16.c)
    ///For input "123456789", the output is 0x31C3 (decimal 12739).
    ///</summary>
    ///<param name="src">The input byte to include in the CRC calculation.</param>
    ///<param name="crc">The current CRC value (intermediate or initial).</param>
    ///<returns>The updated CRC value after processing the input byte.</returns>
    //!!!! Https://github.com/redis/redis/blob/95b1979c321eb6353f75df892ab8be68cf8f9a77/src/crc16.c
    //Output for "123456789"     : 31C3 (12739)
    static ushort crc16(byte src, ushort crc)
    {
        crc = (ushort)(tab[(crc >> 12 ^ src >> 4) & 0x0F] ^ crc << 4);
        return (ushort)(tab[(crc >> 12 ^ src & 0x0F) & 0x0F] ^ crc << 4);
    }
#endregion

    ///<summary>
    ///Implements equality comparison and hash code generation for `IList<T>` instances
    ///based on their element-wise content and sequence.
    ///</summary>
    ///<typeparam name="T">The type of elements in the list.</typeparam>
    public class ArrayEqualHash<T> : IEqualityComparer<IList<T>>
    {
        public bool Equals(IList<T>? x, IList<T>? y) => x == null || y == null ? x == y : x.Count == y.Count && x.SequenceEqual(y);

        public int GetHashCode(IList<T> list) => list.Aggregate(17, (current, item) => HashCode.Combine(current, item));
    }

    static readonly ConcurrentDictionary<object, object> pool = new();

    ///<summary>
    ///Gets a singleton instance of `ArrayEqualHash<T>` for the specified type `T`.
    ///This comparer can be used for `IList<T>` instances where equality depends on element sequence and values.
    ///</summary>
    ///<typeparam name="T">The type of elements in the lists to be compared.</typeparam>
    ///<returns>An `IEqualityComparer<IList<T>>` instance.</returns>
    public static IEqualityComparer<IList<T>> getArrayEqualHash<T>()
    {
        var t = typeof(T);
        if (pool.TryGetValue(t, out var value))
            return (IEqualityComparer<IList<T>>)value;
        var ret = new ArrayEqualHash<T>();
        pool[t] = ret;
        return ret;
    }

    ///<summary>
    ///Endianness-aware integer codec. Read/Write methods on the nested <see cref="OK"/> static class
    ///select the host endianness at JIT-time via <see cref="BitConverter.IsLittleEndian"/> (a recognized
    ///JIT-folded constant). Verified equivalent to the prior interface-based dispatch via
    ///DisassemblyDiagnoser (35-byte loop, identical instructions on .NET 10 RyuJIT AVX2).
    ///<para>
    ///<b>Compile-time hosts.</b> Define one of the following symbols to make the endianness a
    ///<i>C# compile-time constant</i> (the inactive branch is dropped from IL entirely, no JIT-fold required):
    ///<list type="bullet">
    ///<item><c>ADHOC_LE_HOST</c> &mdash; force little-endian. Safe on x86/x64/ARM-LE.</item>
    ///<item><c>ADHOC_BE_HOST</c> &mdash; force big-endian.</item>
    ///</list>
    ///With neither defined, the codec stays portable and the JIT does the folding at runtime.
    ///</para>
    ///</summary>
    internal static class Endianness
    {
#if ADHOC_BE_HOST && ADHOC_LE_HOST
#error "Define at most one of ADHOC_LE_HOST / ADHOC_BE_HOST."
#endif

#if ADHOC_BE_HOST
        //BE host: const false → C# compiler folds `LE_HOST ? a : b` to `b` at compile time.
        private const bool LE_HOST = false;
#elif ADHOC_LE_HOST
        //LE host: const true → C# compiler folds `LE_HOST ? a : b` to `a` at compile time.
        private const bool LE_HOST = true;
#else
        //Portable: BitConverter.IsLittleEndian is a JIT-time constant; the `?:` collapses in native code.
        private static readonly bool LE_HOST = BitConverter.IsLittleEndian;
#endif

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static ref byte RefAt(byte[] src, int index) => ref Unsafe.AddByteOffset(ref MemoryMarshal.GetArrayDataReference(src), (nint)(uint)index);

